INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31aafe00-bc07-4f3e-bcfe-bb2591ef1268', '豐陵行', '豐陵行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["羽衛煌煌一百里，曉出都門葬天子。","羣臣雜沓馳後先，宮官穰穰來不已。","是時新秋七月初，金神按節炎氣除。","清風飄飄輕雨灑，偃蹇旗斾卷以舒。","逾梁下坂笳鼓咽，嵽嵲遂走玄宮閭。","哭聲訇天百鳥噪，幽坎晝閉空靈輿。","皇帝孝心深且遠，資送禮備無贏餘。","設官置衛鎖嬪妓，供養朝夕象平居。","臣聞神道尚清淨，三代舊制存諸書。","墓藏廟祭不可亂，欲言非職知何如。"]', '["羽衛煌煌一百里，晓出都门葬天子。","羣臣杂沓驰後先，宮官穰穰来不已。","是时新秋七月初，金神按節炎氣除。","清风飄飄轻雨灑，偃蹇旗斾卷以舒。","逾梁下坂笳鼓咽，嵽嵲遂走玄宮閭。","哭声訇天百鸟噪，幽坎晝閉空靈輿。","皇帝孝心深且远，資送禮備無贏餘。","設官置衛鎖嬪妓，供養朝夕象平居。","臣闻神道尚清淨，三代旧制存諸书。","墓藏廟祭不可亂，欲言非職知何如。"]', '诗', 'shi', '', NULL, '豐陵行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35849f3-6334-49a3-8733-5fa7b8693356', '遊青龍寺贈崔大補闕', '游青龙寺贈崔大補闕', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋灰初吹季月管，日出卯南暉景短。","友生招我佛寺行，正值萬株紅葉滿。","光華閃壁見神鬼，赫赫炎官張火傘。","然雲燒樹火實駢，金烏下啄赬虬卵。","魂翻眼倒忘處所，赤氣沖融無間斷。","有如流傳上古時，九輪照燭乾坤旱。","二三道士席其間，靈液屢進玻黎盌。","忽驚顏色變韶稚，却信靈僊非怪誕。","桃源迷路竟茫茫，棗下悲歌徒纂纂。","前年嶺隅鄉思發，躑躅成山開不算。","去歲羇帆湘水明，霜楓千里隨歸伴。","猿呼鼯嘯鷓鴣啼，惻耳酸腸難濯澣。","思君攜手安能得，今者相從敢辭懶。","由來鈍騃寡參尋，況是儒官飽閑散。","惟君與我同懷抱，鋤去陵谷置平坦。","年少得途未要忙，時清諫疏尤宜罕。","何人有酒身無事，誰家多竹門可款。","須知節候即風寒，幸及亭午猶妍暖。","南山逼冬轉清瘦，刻畫圭角出崖窾。","當憂復被冰雪埋，汲汲來窺戒遲緩。"]', '["秋灰初吹季月管，日出卯南暉景短。","友生招我佛寺行，正值万株紅葉满。","光华閃壁见神鬼，赫赫炎官張火傘。","然云燒樹火實駢，金烏下啄赬虬卵。","魂翻眼倒忘处所，赤氣沖融無间斷。","有如流傳上古时，九輪照燭乾坤旱。","二三道士席其间，靈液屢進玻黎盌。","忽驚顏色变韶稚，却信靈僊非怪誕。","桃源迷路竟茫茫，棗下悲歌徒纂纂。","前年嶺隅乡思發，躑躅成山开不算。","去歲羇帆湘水明，霜楓千里隨归伴。","猿呼鼯嘯鷓鴣啼，惻耳酸腸难濯澣。","思君携手安能得，今者相從敢辞懶。","由来鈍騃寡參尋，況是儒官飽闲散。","惟君與我同懷抱，鋤去陵谷置平坦。","年少得途未要忙，时清諫疏尤宜罕。","何人有酒身無事，誰家多竹门可款。","須知節候即风寒，幸及亭午猶妍暖。","南山逼冬轉清瘦，刻畫圭角出崖窾。","當憂复被冰雪埋，汲汲来窺戒遲緩。"]', '诗', 'shi', '', NULL, '遊青龍寺贈崔大補闕 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f33af0-78ba-4a07-bb14-ff45aeea00c2', '贈崔立之評事', '贈崔立之評事', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["崔侯文章苦捷敏，高浪駕天輸不盡。","曾從關外來上都，隨身卷軸車連軫。","朝爲百賦猶鬱怒，暮作千詩轉遒緊。","搖毫擲簡自不供，頃刻青紅浮海蜃。","才豪氣猛易語言，往往蛟螭雜螻蚓。","知音自古稱難遇，世俗乍見那妨哂。","勿嫌法官未登朝，猶勝赤尉長趨尹。","時命雖乖心轉壯，技能虛富家逾窘。","念昔塵埃兩相逢，爭名齟齬持矛楯。","子時專場誇觜距，余始張軍嚴韅靷。","爾來但欲保封疆，莫學龐涓怯孫臏。","竄逐新歸厭聞鬧，齒髮早衰嗟可閔。","頻蒙怨句刺棄遺，豈有閑官敢推引。","深藏篋笥時一發，戢戢已多如束筍。","可憐無益費精神，有似黃金擲虛牝。","當今聖人求侍從，拔擢杞梓收楛箘。","東馬嚴徐已奮飛，枚臯即召窮且忍。","復聞王師西討蜀，霜風冽冽摧朝菌。","走章馳檄在得賢，燕雀紛拏要鷹隼。","竊料二途必處一，豈比恒人長蠢蠢。","勸君韜養待徴招，不用雕琢愁肝腎。","牆根菊花好沽酒，錢帛縱空衣可準。","暉暉簷日暖且鮮，摵摵井梧疎更殞。","高士例須憐麯糵，丈夫終莫生畦畛。","能來取醉任喧呼，死後賢愚俱泯泯。"]', '["崔侯文章苦捷敏，高浪駕天輸不尽。","曾從关外来上都，隨身卷軸车連軫。","朝爲百賦猶鬱怒，暮作千诗轉遒緊。","搖毫擲簡自不供，頃刻青紅浮海蜃。","才豪氣猛易語言，往往蛟螭杂螻蚓。","知音自古稱难遇，世俗乍见那妨哂。","勿嫌法官未登朝，猶勝赤尉长趨尹。","时命雖乖心轉壯，技能虛富家逾窘。","念昔塵埃兩相逢，爭名齟齬持矛楯。","子时專場誇觜距，余始張軍嚴韅靷。","爾来但欲保封疆，莫学龐涓怯孫臏。","竄逐新归厭闻鬧，齒髮早衰嗟可閔。","頻蒙怨句刺棄遺，豈有闲官敢推引。","深藏篋笥时一發，戢戢已多如束筍。","可怜無益費精神，有似黄金擲虛牝。","當今聖人求侍從，拔擢杞梓收楛箘。","东马嚴徐已奮飞，枚臯即召窮且忍。","复闻王師西討蜀，霜风冽冽摧朝菌。","走章驰檄在得賢，燕雀紛拏要鷹隼。","竊料二途必处一，豈比恒人长蠢蠢。","勸君韜養待徴招，不用雕琢愁肝腎。","牆根菊花好沽酒，錢帛縱空衣可準。","暉暉簷日暖且鲜，摵摵井梧疎更殞。","高士例須怜麯糵，丈夫終莫生畦畛。","能来取醉任喧呼，死後賢愚俱泯泯。"]', '诗', 'shi', '', NULL, '贈崔立之評事 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a123c44-bba1-4f01-9dc9-715a25da8eea', '送區弘南歸', '送區弘南归', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["穆昔南征軍不歸，蟲沙猿鶴伏以飛。","洶洶洞庭莽翠微，九疑鑱天荒是非。","野有象犀水貝璣，分散百寶人士稀。","我遷於南日周圍，來見者衆莫伊俙。","爰有區子熒熒暉，觀以彝訓或從違。","我念前人譬葑菲，落以斧引以纆徽。","雖有不逮驅騑騑，或採於薄漁於磯。","服役不辱言不譏，從我荆州來京畿。","離其母妻絕因依，嗟我道不能自肥。","子雖勤苦終何希，王都觀闕雙巍巍。","騰蹋衆駿事鞍鞿，佩服上色紫與緋。","獨子之節可嗟唏，母附書至妻寄衣。","開書拆衣淚痕晞，雖不敕還情庶幾。","朝暮盤羞惻庭闈，幽房無人感伊威。","人生此難餘可祈，子去矣時若發機。","蜃沈海底氣昇霏，彩雉野伏朝扇翬。","處子窈窕王所妃，苟有令德隱不腓。","況今天子鋪德威，蔽能者誅薦受禨。","出送撫背我涕揮，行行正直慎脂韋。","業成志樹來頎頎，我當爲子言天扉。"]', '["穆昔南征軍不归，蟲沙猿鹤伏以飞。","洶洶洞庭莽翠微，九疑鑱天荒是非。","野有象犀水貝璣，分散百寶人士稀。","我遷於南日周圍，来见者衆莫伊俙。","爰有區子熒熒暉，观以彝訓或從違。","我念前人譬葑菲，落以斧引以纆徽。","雖有不逮驱騑騑，或採於薄漁於磯。","服役不辱言不譏，從我荆州来京畿。","離其母妻絕因依，嗟我道不能自肥。","子雖勤苦終何希，王都观闕雙巍巍。","腾蹋衆駿事鞍鞿，佩服上色紫與緋。","独子之節可嗟唏，母附书至妻寄衣。","开书拆衣泪痕晞，雖不敕還情庶幾。","朝暮盤羞惻庭闈，幽房無人感伊威。","人生此难餘可祈，子去矣时若發機。","蜃沈海底氣昇霏，彩雉野伏朝扇翬。","处子窈窕王所妃，苟有令德隐不腓。","況今天子鋪德威，蔽能者誅薦受禨。","出送撫背我涕揮，行行正直慎脂韋。","業成志樹来頎頎，我當爲子言天扉。"]', '诗', 'shi', '', NULL, '送區弘南歸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b0fd3d-e436-43bb-98b3-3949c75a902a', '三星行', '三星行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我生之辰，月宿南斗。","牛奮其角，箕張其口。","牛不見服箱，斗不挹酒漿。","箕獨有神靈，無時停簸揚。","無善名已聞，無惡聲已讙。","名聲相乘除，得少失有餘。","三星各在天，什伍東西陳。","嗟汝牛與斗，汝獨不能神。"]', '["我生之辰，月宿南斗。","牛奮其角，箕張其口。","牛不见服箱，斗不挹酒漿。","箕独有神靈，無时停簸揚。","無善名已闻，無惡声已讙。","名声相乘除，得少失有餘。","三星各在天，什伍东西陳。","嗟汝牛與斗，汝独不能神。"]', '诗', 'shi', '', NULL, '三星行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30cacc20-7b61-4c3b-af5b-cd0e154a9672', '剝啄行', '剝啄行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["剝剝啄啄，有客至門。","我不出應，客去而嗔。","從者語我，子胡爲然。","我不厭客，困於語言。","欲不出納，以堙其源。","空堂幽幽，有秸有莞。","門以兩板，叢書於間。","窅窅深塹，其墉甚完。","彼寧可隳，此不可干。","從者語我，嗟子誠難。","子雖云爾，其口益蕃。","我爲子謀，有萬其全。","凡今之人，急名與官。","子不引去，與爲波瀾。","雖不開口，雖不開關。","變化咀嚼，有鬼有神。","今去不勇，其如後艱。","我謝再拜，汝無復云。","往追不及，來不有年。"]', '["剝剝啄啄，有客至门。","我不出應，客去而嗔。","從者語我，子胡爲然。","我不厭客，困於語言。","欲不出納，以堙其源。","空堂幽幽，有秸有莞。","门以兩板，叢书於间。","窅窅深塹，其墉甚完。","彼寧可隳，此不可干。","從者語我，嗟子誠难。","子雖云爾，其口益蕃。","我爲子謀，有万其全。","凡今之人，急名與官。","子不引去，與爲波瀾。","雖不开口，雖不开关。","变化咀嚼，有鬼有神。","今去不勇，其如後艱。","我謝再拜，汝無复云。","往追不及，来不有年。"]', '诗', 'shi', '', NULL, '剝啄行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e1b184-2377-472a-a27d-5151bc27b391', '青青水中蒲三首 一', '青青水中蒲三首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["青青水中蒲，下有一雙魚。","君今上隴去，我在與誰居。"]', '["青青水中蒲，下有一雙鱼。","君今上隴去，我在與誰居。"]', '诗', 'shi', '', NULL, '青青水中蒲三首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7b9119-e202-4288-b6b0-91642072dbf4', '青青水中蒲三首 二', '青青水中蒲三首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["青青水中蒲，長在水中居。","寄語浮萍草，相隨我不如。"]', '["青青水中蒲，长在水中居。","寄語浮萍草，相隨我不如。"]', '诗', 'shi', '', NULL, '青青水中蒲三首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f0b9f1-9390-4b75-9386-54b48ec57b5f', '青青水中蒲三首 三', '青青水中蒲三首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["青青水中蒲，葉短不出水。","婦人不下堂，行子在萬里。"]', '["青青水中蒲，葉短不出水。","婦人不下堂，行子在万里。"]', '诗', 'shi', '', NULL, '青青水中蒲三首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530ab82c-db31-45ed-bab1-01599eb9d5fe', '孟東野失子', '孟东野失子', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["失子將何尤，吾將上尤天。","女實主下人，與奪一何偏。","彼於女何有，乃令蕃且延。","此獨何罪辜，生死旬日間。","上呼無時聞，滴地淚到泉。","地祇爲之悲，瑟縮久不安。","乃呼大靈龜，騎雲款天門。","問天主下人，薄厚胡不均。","天曰天地人，由來不相關。","吾懸日與月，吾繫星與辰。","日月相噬齧，星辰踣而顛。","吾不女之罪，知非女由因。","且物各有分，孰能使之然。","有子與無子，禍福未可原。","魚子滿母腹，一一欲誰憐。","細腰不自乳，舉族常孤鰥。","鴟梟啄母腦，母死子始翻。","蝮蛇生子時，坼裂腸與肝。","好子雖云好，未還恩與勤。","惡子不可說，鴟梟蝮蛇然。","有子且勿喜，無子固勿歎。","上聖不待敎，賢聞語而遷。","下愚聞語惑，雖敎無由悛。","大靈頓頭受，即日以命還。","地祇謂大靈，女往告其人。","東野夜得夢，有夫玄衣巾。","闖然入其戶，三稱天之言。","再拜謝玄夫，收悲以歡忻。"]', '["失子將何尤，吾將上尤天。","女實主下人，與奪一何偏。","彼於女何有，乃令蕃且延。","此独何罪辜，生死旬日间。","上呼無时闻，滴地泪到泉。","地祇爲之悲，瑟縮久不安。","乃呼大靈龟，騎云款天门。","问天主下人，薄厚胡不均。","天曰天地人，由来不相关。","吾懸日與月，吾繫星與辰。","日月相噬齧，星辰踣而顛。","吾不女之罪，知非女由因。","且物各有分，孰能使之然。","有子與無子，禍福未可原。","鱼子满母腹，一一欲誰怜。","細腰不自乳，舉族常孤鰥。","鴟梟啄母腦，母死子始翻。","蝮蛇生子时，坼裂腸與肝。","好子雖云好，未還恩與勤。","惡子不可说，鴟梟蝮蛇然。","有子且勿喜，無子固勿歎。","上聖不待敎，賢闻語而遷。","下愚闻語惑，雖敎無由悛。","大靈頓头受，即日以命還。","地祇謂大靈，女往告其人。","东野夜得梦，有夫玄衣巾。","闖然入其戶，三稱天之言。","再拜謝玄夫，收悲以歡忻。"]', '诗', 'shi', '', NULL, '孟東野失子 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63043fd8-cf4d-402e-86a0-209e54a5338d', '陸渾山火和皇甫湜用其韻', '陸渾山火和皇甫湜用其韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["皇甫補官古賁渾，時當玄冬澤乾源。","山狂谷很相吐吞，風怒不休何軒軒。","擺磨出火以自燔，有聲夜中驚莫原。","天跳地踔顛乾坤，赫赫上照窮崖垠。","截然高周燒四垣，神焦鬼爛無逃門。","三光弛隳不復暾，虎熊麋豬逮猴猿。","水龍鼉龜魚與黿，鴉鴟雕鷹雉鵠鵾。","燖炰煨爊孰飛奔，祝融告休酌卑尊。","錯陳齊玫闢華園，芙蓉披猖塞鮮繁。","千鍾萬鼓咽耳喧，攢雜啾嚄沸篪塤。","彤幢絳旃紫纛旛，炎官熱屬朱冠褌。","髹其肉皮通䏶臀，頹胸垤腹車掀轅。","緹顏靺股豹兩鞬，霞車虹靷日轂轓。","丹蕤縓蓋緋繙㠾，紅帷赤幕羅脤膰。","𥁃池波風肉陵屯，谽呀鉅壑頗黎盆。","豆登五山瀛四尊，熙熙釂醻笑語言。","雷公擘山海水翻，齒牙嚼齧舌腭反。","電光䃸磹赬目䁔，頊冥收威避玄根。","斥棄輿馬背厥孫，縮身潛喘拳肩跟。","君臣相憐加愛恩，命黑螭偵焚其元。","天闕悠悠不可援，夢通上帝血面論。","側身欲進叱於閽，帝賜九河湔涕痕。","又詔巫陽反其魂，徐命之前問何冤。","火行於冬古所存，我如禁之絕其飧。","女丁婦壬傳世婚，一朝結讐奈後昆。","時行當反慎藏蹲，視桃著花可小騫。","月及申酉利復怨，助汝五龍從九鯤。","溺厥邑囚之崑崙，皇甫作詩止睡昏。","辭誇出真遂上焚，要余和增怪又煩，雖欲悔舌不可捫。"]', '["皇甫補官古賁渾，时當玄冬澤乾源。","山狂谷很相吐吞，风怒不休何軒軒。","擺磨出火以自燔，有声夜中驚莫原。","天跳地踔顛乾坤，赫赫上照窮崖垠。","截然高周燒四垣，神焦鬼爛無逃门。","三光弛隳不复暾，虎熊麋豬逮猴猿。","水龙鼉龟鱼與黿，鴉鴟雕鷹雉鵠鵾。","燖炰煨爊孰飞奔，祝融告休酌卑尊。","錯陳齊玫闢华园，芙蓉披猖塞鲜繁。","千鍾万鼓咽耳喧，攢杂啾嚄沸篪塤。","彤幢絳旃紫纛旛，炎官熱屬朱冠褌。","髹其肉皮通䏶臀，頹胸垤腹车掀轅。","緹顏靺股豹兩鞬，霞车虹靷日轂轓。","丹蕤縓蓋緋繙㠾，紅帷赤幕羅脤膰。","𥁃池波风肉陵屯，谽呀鉅壑頗黎盆。","豆登五山瀛四尊，熙熙釂醻笑語言。","雷公擘山海水翻，齒牙嚼齧舌腭反。","電光䃸磹赬目䁔，頊冥收威避玄根。","斥棄輿马背厥孫，縮身潛喘拳肩跟。","君臣相怜加愛恩，命黑螭偵焚其元。","天闕悠悠不可援，梦通上帝血面論。","側身欲進叱於閽，帝賜九河湔涕痕。","又詔巫陽反其魂，徐命之前问何冤。","火行於冬古所存，我如禁之絕其飧。","女丁婦壬傳世婚，一朝結讐奈後昆。","时行當反慎藏蹲，視桃著花可小騫。","月及申酉利复怨，助汝五龙從九鯤。","溺厥邑囚之崑崙，皇甫作诗止睡昏。","辞誇出真遂上焚，要余和增怪又煩，雖欲悔舌不可捫。"]', '诗', 'shi', '', NULL, '陸渾山火和皇甫湜用其韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7daab7d-768f-40a6-9cdc-73b79b0760d4', '縣齋讀書', '縣斋读书', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["出宰山水縣，讀書松桂林。","蕭條捐末事，邂逅得初心。","哀狖醒俗耳，清泉潔塵襟。","詩成有共賦，酒熟無孤斟。","青竹時默釣，白雲日幽尋。","南方本多毒，北客恒懼侵。","謫譴甘自守，滯留愧難任。","投章類縞帶，佇答逾兼金。"]', '["出宰山水縣，读书松桂林。","蕭條捐末事，邂逅得初心。","哀狖醒俗耳，清泉潔塵襟。","诗成有共賦，酒熟無孤斟。","青竹时默釣，白云日幽尋。","南方本多毒，北客恒懼侵。","謫譴甘自守，滯留愧难任。","投章類縞带，佇答逾兼金。"]', '诗', 'shi', '', NULL, '縣齋讀書 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d70922b-4e1b-4eb5-ae5b-79df44859f57', '新竹', '新竹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["筍添南堦竹，日日成清閟。","縹節已儲霜，黃苞猶揜翠。","出欄抽五六，當戶羅三四。","高標陵秋嚴，貞色奪春媚。","稀生巧補林，併出疑爭地。","縱橫乍依行，爛熳忽無次。","風枝未飄吹，露粉先涵淚。","何人可攜翫，清景空瞪視。"]', '["筍添南堦竹，日日成清閟。","縹節已儲霜，黄苞猶揜翠。","出欄抽五六，當戶羅三四。","高標陵秋嚴，貞色奪春媚。","稀生巧補林，併出疑爭地。","縱橫乍依行，爛熳忽無次。","风枝未飄吹，露粉先涵泪。","何人可携翫，清景空瞪視。"]', '诗', 'shi', '', NULL, '新竹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff205d9-e2f9-4721-910c-90213458841a', '晚菊', '晚菊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["少年飲酒時，踊躍見菊花。","今來不復飲，每見恒咨嗟。","佇立摘滿手，行行把歸家。","此時無與語，棄置奈悲何。"]', '["少年饮酒时，踊躍见菊花。","今来不复饮，每见恒咨嗟。","佇立摘满手，行行把归家。","此时無與語，棄置奈悲何。"]', '诗', 'shi', '', NULL, '晚菊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01239a8e-37d4-4f39-bd57-5b8c7227618d', '落齒', '落齒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["去年落一牙，今年落一齒。","俄然落六七，落勢殊未已。","餘存皆動搖，盡落應始止。","憶初落一時，但念豁可恥。","及至落二三，始憂衰即死。","每一將落時，懔懔恒在已。","叉牙妨食物，顛倒怯漱水。","終焉捨我落，意與崩山比。","今來落既熟，見落空相似。","餘存二十餘，次第知落矣。","儻常歲落一，自足支兩紀。","如其落併空，與漸亦同指。","人言齒之落，壽命理難恃。","我言生有涯，長短俱死爾。","人言齒之豁，左右驚諦視。","我言莊周云，水雁各有喜。","語訛默固好，嚼廢軟還美。","因歌遂成詩，持用詫妻子。"]', '["去年落一牙，今年落一齒。","俄然落六七，落勢殊未已。","餘存皆动搖，尽落應始止。","憶初落一时，但念豁可恥。","及至落二三，始憂衰即死。","每一將落时，懔懔恒在已。","叉牙妨食物，顛倒怯漱水。","終焉捨我落，意與崩山比。","今来落既熟，见落空相似。","餘存二十餘，次第知落矣。","儻常歲落一，自足支兩紀。","如其落併空，與漸亦同指。","人言齒之落，壽命理难恃。","我言生有涯，长短俱死爾。","人言齒之豁，左右驚諦視。","我言莊周云，水雁各有喜。","語訛默固好，嚼廢軟還美。","因歌遂成诗，持用詫妻子。"]', '诗', 'shi', '', NULL, '落齒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6213326-0c71-4a26-b5ee-344172e0656f', '哭楊兵部凝陸歙州參', '哭楊兵部凝陸歙州參', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["人皆期七十，纔半豈蹉跎。","併出知己淚，自然白髮多。","晨興爲誰慟，還坐久滂沱。","論文與晤語，已矣可如何。"]', '["人皆期七十，纔半豈蹉跎。","併出知己泪，自然白髮多。","晨兴爲誰慟，還坐久滂沱。","論文與晤語，已矣可如何。"]', '诗', 'shi', '', NULL, '哭楊兵部凝陸歙州參 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c89efe-d541-488b-b257-b03b53ea66d6', '苦寒', '苦寒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["四時各平分，一氣不可兼。","隆寒奪春序，顓頊固不廉。","太昊弛維綱，畏避但守謙。","遂令黃泉下，萌牙夭句尖。","草木不復抽，百味失苦甜。","凶飆攪宇宙，鋩刃甚割砭。","日月雖云尊，不能活烏蟾。","羲和送日出，恇怯頻窺覘。","炎帝持祝融，呵噓不相炎。","而我當此時，恩光何由沾。","肌膚生鱗甲，衣被如刀鐮。","氣寒鼻莫齅，血凍指不拈。","濁醪沸入喉，口角如銜箝。","將持匕箸食，觸指如排籤。","侵爐不覺暖，熾炭屢已添。","探湯無所益，何況纊與縑。","虎豹僵穴中，蛟螭死幽潛。","熒惑喪纏次，六龍冰脫髯。","芒碭大包內，生類恐盡殲。","啾啾窗間雀，不知已微纖。","舉頭仰天鳴，所願晷刻淹。","不如彈射死，却得親炰燖。","鸞皇苟不存，爾固不在占。","其餘蠢動儔，俱死誰恩嫌。","伊我稱最靈，不能女覆苫。","悲哀激憤歎，五藏難安恬。","中宵倚牆立，淫淚何漸漸。","天王哀無辜，惠我下顧瞻。","褰旒去耳纊，調和進梅鹽。","賢能日登御，黜彼傲與憸。","生風吹死氣，豁達如褰簾。","懸乳零落墮，晨光入前簷。","雪霜頓銷釋，土脉膏且黏。","豈徒蘭蕙榮，施及艾與蒹。","日萼行鑠鑠，風條坐襜襜。","天乎苟其能，吾死意亦厭。"]', '["四时各平分，一氣不可兼。","隆寒奪春序，顓頊固不廉。","太昊弛維綱，畏避但守謙。","遂令黄泉下，萌牙夭句尖。","草木不复抽，百味失苦甜。","凶飆攪宇宙，鋩刃甚割砭。","日月雖云尊，不能活烏蟾。","羲和送日出，恇怯頻窺覘。","炎帝持祝融，呵噓不相炎。","而我當此时，恩光何由沾。","肌膚生鱗甲，衣被如刀鐮。","氣寒鼻莫齅，血凍指不拈。","濁醪沸入喉，口角如銜箝。","將持匕箸食，觸指如排籤。","侵爐不覺暖，熾炭屢已添。","探湯無所益，何況纊與縑。","虎豹僵穴中，蛟螭死幽潛。","熒惑喪纏次，六龙冰脫髯。","芒碭大包內，生類恐尽殲。","啾啾窗间雀，不知已微纖。","舉头仰天鳴，所願晷刻淹。","不如彈射死，却得親炰燖。","鸾皇苟不存，爾固不在占。","其餘蠢动儔，俱死誰恩嫌。","伊我稱最靈，不能女覆苫。","悲哀激憤歎，五藏难安恬。","中宵倚牆立，淫泪何漸漸。","天王哀無辜，惠我下顧瞻。","褰旒去耳纊，調和進梅鹽。","賢能日登御，黜彼傲與憸。","生风吹死氣，豁達如褰簾。","懸乳零落墮，晨光入前簷。","雪霜頓銷釋，土脉膏且黏。","豈徒蘭蕙榮，施及艾與蒹。","日萼行鑠鑠，风條坐襜襜。","天乎苟其能，吾死意亦厭。"]', '诗', 'shi', '', NULL, '苦寒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('518d5f1a-fe1e-4fdd-8631-d707c55f836d', '和虞部盧四酬翰林錢七赤藤杖歌', '和虞部盧四酬翰林錢七赤藤杖歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["赤藤爲杖世未窺，臺郎始攜自滇池。","滇王掃宮避使者，跪進再拜語嗢咿。","繩橋拄過免傾墮，性命造次蒙扶持。","途經百國皆莫識，君臣聚觀逐旌麾。","共傳滇神出水獻，赤龍拔鬚血淋漓。","又云羲和操火鞭，暝到西極睡所遺。","幾重包裹自題署，不以珍怪誇荒夷。","歸來捧贈同舍子，浮光照手欲把疑。","空堂晝眠倚牖戶，飛電著壁搜蛟螭。","南宮清深禁闈密，唱和有類吹塤篪。","妍辭麗句不可繼，見寄聊且慰分司。"]', '["赤藤爲杖世未窺，台郎始携自滇池。","滇王掃宮避使者，跪進再拜語嗢咿。","繩橋拄過免傾墮，性命造次蒙扶持。","途經百国皆莫識，君臣聚观逐旌麾。","共傳滇神出水獻，赤龙拔鬚血淋漓。","又云羲和操火鞭，暝到西極睡所遺。","幾重包裹自題署，不以珍怪誇荒夷。","归来捧贈同舍子，浮光照手欲把疑。","空堂晝眠倚牖戶，飞電著壁搜蛟螭。","南宮清深禁闈密，唱和有類吹塤篪。","妍辞丽句不可繼，见寄聊且慰分司。"]', '诗', 'shi', '', NULL, '和虞部盧四酬翰林錢七赤藤杖歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e75248-a3b6-4d4e-922b-26db7503b686', '崔十六少府攝伊陽以詩及書見投因酬三十韻', '崔十六少府攝伊陽以诗及书见投因酬三十韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["崔君初來時，相識頗未慣。","但聞赤縣尉，不比博士慢。","賃屋得連牆，往來忻莫間。","我時亦新居，觸事苦難辦。","蔬飱要同喫，破襖請來綻。","謂言安堵後，貸借更何患。","不知孤遺多，舉族仰薄宦。","有時未朝餐，得米日已晏。","隔牆聞讙呼，衆口極鵝雁。","前計頓乖張，居然見真贋。","嬌兒好眉眼，褲脚凍兩骭。","捧書隨諸兄，累累兩角丱。","冬惟茹寒齏，秋始識瓜瓣。","問之不言飢，飫若厭芻豢。","才名三十年，久合居給諫。","白頭趨走裏，閉口絕謗訕。","府公舊同袍，拔擢宰山澗。","寄詩雜詼俳，有類說鵬鷃。","上言酒味酸，冬衣竟未擐。","下言人吏稀，惟足彪與虥。","又言致豬鹿，此語乃善幻。","三年國子師，腸肚習藜莧。","況住洛之涯，魴鱒可罩汕。","肯效屠門嚼，久嫌弋者篡。","謀拙日焦拳，活計似鋤剗。","男寒澀詩書，妻瘦剩腰襻。","爲官不事職，厥罪在欺謾。","行當自劾去，漁釣老葭薍。","歲窮寒氣驕，冰雪滑磴棧。","音問難屢通，何由覿清盼。"]', '["崔君初来时，相識頗未慣。","但闻赤縣尉，不比博士慢。","賃屋得連牆，往来忻莫间。","我时亦新居，觸事苦难辦。","蔬飱要同喫，破襖請来綻。","謂言安堵後，貸借更何患。","不知孤遺多，舉族仰薄宦。","有时未朝餐，得米日已晏。","隔牆闻讙呼，衆口極鵝雁。","前計頓乖張，居然见真贋。","嬌兒好眉眼，褲脚凍兩骭。","捧书隨諸兄，累累兩角丱。","冬惟茹寒齏，秋始識瓜瓣。","问之不言飢，飫若厭芻豢。","才名三十年，久合居給諫。","白头趨走裏，閉口絕謗訕。","府公旧同袍，拔擢宰山澗。","寄诗杂詼俳，有類说鵬鷃。","上言酒味酸，冬衣竟未擐。","下言人吏稀，惟足彪與虥。","又言致豬鹿，此語乃善幻。","三年国子師，腸肚習藜莧。","況住洛之涯，魴鱒可罩汕。","肯效屠门嚼，久嫌弋者篡。","謀拙日焦拳，活計似鋤剗。","男寒澀诗书，妻瘦剩腰襻。","爲官不事職，厥罪在欺謾。","行當自劾去，漁釣老葭薍。","歲窮寒氣驕，冰雪滑磴棧。","音问难屢通，何由覿清盼。"]', '诗', 'shi', '', NULL, '崔十六少府攝伊陽以詩及書見投因酬三十韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('161aef05-ddfa-4aa0-a282-75018f245eaf', '送侯參謀赴河中幕', '送侯參謀赴河中幕', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["憶昔初及第，各以少年稱。","君頤始生鬚，我齒清如冰。","爾時心氣壯，百事謂己能。","一別詎幾何，忽如隔晨興。","我齒豁可鄙，君顏老可憎。","相逢風塵中，相視迭嗟矜。","幸同學省官，末路再得朋。","東司絕敎授，遊[宴]以爲恒。","秋漁蔭密樹，夜博然明燈。","雪逕抵樵叟，風廊折談僧。","陸渾桃花間，有湯沸如烝。","三月崧少步，躑躅紅千層。","洲沙厭晚坐，嶺壁窮晨升。","沈冥不計日，爲樂不可勝。","遷滿一已異，乖離坐難憑。","行行事結束，人馬何蹻騰。","感激生膽勇，從軍豈嘗曾。","洸洸司徒公，天子爪與肱。","提師十萬餘，四海欽風稜。","河北兵未進，蔡州師新薨。","曷不請掃除，活彼黎與烝。","鄙夫誠怯弱，受恩媿徒弘。","猶思脫儒冠，棄死取先登。","又欲面言事，上書求詔徴。","侵官固非是，妄作譴可懲。","惟當待責免，耕斸歸溝塍。","今君得所附，勢若脫鞲鷹。","檄筆無與讓，幕謀職其膺。","收績開史牒，翰飛逐溟鵬。","男兒貴立事，流景不可乘。","歲老陰沴作，雲頹雪翻崩。","別袖拂洛水，征車轉崤陵。","勤勤酒不進，勉勉恨已仍。","送君出門歸，愁腸若牽繩。","默坐念語笑，癡如遇寒蠅。","策馬誰可適，晤言誰爲應。","席塵惜不掃，殘尊對空凝。","信知後會時，日月屢環絙。","生期理行役，歡緒絕難承。","寄書惟在頻，無恡簡與繒。"]', '["憶昔初及第，各以少年稱。","君頤始生鬚，我齒清如冰。","爾时心氣壯，百事謂己能。","一別詎幾何，忽如隔晨兴。","我齒豁可鄙，君顏老可憎。","相逢风塵中，相視迭嗟矜。","幸同学省官，末路再得朋。","东司絕敎授，游[宴]以爲恒。","秋漁蔭密樹，夜博然明灯。","雪逕抵樵叟，风廊折談僧。","陸渾桃花间，有湯沸如烝。","三月崧少步，躑躅紅千層。","洲沙厭晚坐，嶺壁窮晨升。","沈冥不計日，爲乐不可勝。","遷满一已異，乖離坐难憑。","行行事結束，人马何蹻腾。","感激生膽勇，從軍豈嘗曾。","洸洸司徒公，天子爪與肱。","提師十万餘，四海欽风稜。","河北兵未進，蔡州師新薨。","曷不請掃除，活彼黎與烝。","鄙夫誠怯弱，受恩媿徒弘。","猶思脫儒冠，棄死取先登。","又欲面言事，上书求詔徴。","侵官固非是，妄作譴可懲。","惟當待責免，耕斸归溝塍。","今君得所附，勢若脫鞲鷹。","檄笔無與讓，幕謀職其膺。","收績开史牒，翰飞逐溟鵬。","男兒貴立事，流景不可乘。","歲老陰沴作，云頹雪翻崩。","別袖拂洛水，征车轉崤陵。","勤勤酒不進，勉勉恨已仍。","送君出门归，愁腸若牽繩。","默坐念語笑，癡如遇寒蠅。","策马誰可適，晤言誰爲應。","席塵惜不掃，殘尊对空凝。","信知後會时，日月屢环絙。","生期理行役，歡緒絕难承。","寄书惟在頻，無恡簡與繒。"]', '诗', 'shi', '', NULL, '送侯參謀赴河中幕 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3bb0ed-fd03-487b-8d59-519db3076dc0', '東都遇春', '东都遇春', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["少年氣真狂，有意與春競。","行逢二三月，九州花相暎。","川原曉服鮮，桃李晨妝靚。","荒乘不知疲，醉死豈辭病。","飲噉惟所便，文章倚豪橫。","爾來曾幾時，白髮忽滿鏡。","舊遊喜乖張，新輩足嘲評。","心腸一變化，羞見時節盛。","得閑無所作，貴欲辭視聽。","深居疑避仇，默臥如當暝。","朝曦入牖來，鳥喚昏不醒。","爲生鄙計算，鹽米告屢罄。","坐疲都忘起，冠側懶復正。","幸蒙東都官，獲離機與穽。","乖慵遭傲僻，漸染生弊性。","既去焉能追，有來猶莫騁。","有船魏王池，往往縱孤泳。","水容與天色，此處皆綠淨。","岸樹共紛披，渚牙相緯經。","懷歸苦不果，即事取幽迸。","貪求匪名利，所得亦已併。","悠悠度朝昏，落落捐季孟。","羣公一何賢，上戴天子聖。","謀謨收禹績，四面出雄勁。","轉輸非不勤，稽逋有軍令。","在庭百執事，奉職各祗敬。","我獨胡爲哉，坐與億兆慶。","譬如籠中鳥，仰給活性命。","爲詩告友生，負愧終究竟。"]', '["少年氣真狂，有意與春競。","行逢二三月，九州花相暎。","川原晓服鲜，桃李晨妝靚。","荒乘不知疲，醉死豈辞病。","饮噉惟所便，文章倚豪橫。","爾来曾幾时，白髮忽满镜。","旧游喜乖張，新輩足嘲評。","心腸一变化，羞见时節盛。","得闲無所作，貴欲辞視听。","深居疑避仇，默臥如當暝。","朝曦入牖来，鸟喚昏不醒。","爲生鄙計算，鹽米告屢罄。","坐疲都忘起，冠側懶复正。","幸蒙东都官，獲離機與穽。","乖慵遭傲僻，漸染生弊性。","既去焉能追，有来猶莫騁。","有船魏王池，往往縱孤泳。","水容與天色，此处皆綠淨。","岸樹共紛披，渚牙相緯經。","懷归苦不果，即事取幽迸。","貪求匪名利，所得亦已併。","悠悠度朝昏，落落捐季孟。","羣公一何賢，上戴天子聖。","謀謨收禹績，四面出雄勁。","轉輸非不勤，稽逋有軍令。","在庭百執事，奉職各祗敬。","我独胡爲哉，坐與億兆慶。","譬如籠中鸟，仰給活性命。","爲诗告友生，負愧終究竟。"]', '诗', 'shi', '', NULL, '東都遇春 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd5aa26-9bbd-4f6c-964e-6d91f2491865', '感春五首 一', '感春五首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["辛夷高花最先開，青天露坐始此廻。","已呼孺人戛鳴瑟，更遣稚子傳清杯。","選壯軍興不爲用，坐狂朝論無由陪。","如今到死得閑處，還有詩賦歌康哉。"]', '["辛夷高花最先开，青天露坐始此廻。","已呼孺人戛鳴瑟，更遣稚子傳清杯。","選壯軍兴不爲用，坐狂朝論無由陪。","如今到死得闲处，還有诗賦歌康哉。"]', '诗', 'shi', '', NULL, '感春五首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac43513-de5f-451f-b968-71d3ff89ac64', '感春五首 二', '感春五首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["洛陽東風幾時來，川波岸柳春全廻。","宮門一鎖不復啓，雖有九陌無塵埃。","策馬上橋朝日出，樓闕赤白正崔嵬。","孤吟屢闋莫與和，寸恨至短誰能裁。"]', '["洛陽东风幾时来，川波岸柳春全廻。","宮门一鎖不复啓，雖有九陌無塵埃。","策马上橋朝日出，楼闕赤白正崔嵬。","孤吟屢闋莫與和，寸恨至短誰能裁。"]', '诗', 'shi', '', NULL, '感春五首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03fc8e4c-ad4a-4d6e-8896-50768d9c3b05', '感春五首 三', '感春五首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["春田可耕時已催，王師北討何當廻。","放車載草農事濟，戰馬苦飢誰念哉。","蔡州納節舊將死，起居諫議聯翩來。","朝廷未省有遺策，肯不垂意缾與罍。"]', '["春田可耕时已催，王師北討何當廻。","放车載草農事濟，戰马苦飢誰念哉。","蔡州納節旧將死，起居諫議聯翩来。","朝廷未省有遺策，肯不垂意缾與罍。"]', '诗', 'shi', '', NULL, '感春五首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba6448d-dc28-4d31-88be-43e29951be6d', '感春五首 四', '感春五首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["前隨杜尹拜表廻，笑言溢口何歡咍。","孔丞別我適臨汝，風骨峭峻遺塵埃。","音容不接祗隔夜，凶訃詎可相尋來。","天公高居鬼神惡，欲保性命誠難哉。"]', '["前隨杜尹拜表廻，笑言溢口何歡咍。","孔丞別我適臨汝，风骨峭峻遺塵埃。","音容不接祗隔夜，凶訃詎可相尋来。","天公高居鬼神惡，欲保性命誠难哉。"]', '诗', 'shi', '', NULL, '感春五首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d096b273-f8f4-4c86-bd39-4e915e2390a4', '感春五首 五', '感春五首 五', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["辛夷花房忽全開，將衰正盛須頻來。","清晨輝輝燭霞日，薄暮耿耿和煙埃。","朝明夕暗已足歎，況乃滿地成摧頹。","迎繁送謝別有意，誰肯留戀少環廻。"]', '["辛夷花房忽全开，將衰正盛須頻来。","清晨輝輝燭霞日，薄暮耿耿和煙埃。","朝明夕暗已足歎，況乃满地成摧頹。","迎繁送謝別有意，誰肯留戀少环廻。"]', '诗', 'shi', '', NULL, '感春五首 五 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a4ba02-d97f-4284-a5ad-2f2519423a66', '酬裴十六功曹巡府西驛塗中見寄', '酬裴十六功曹巡府西驛塗中见寄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["相公罷論道，聿至活東人。","御史坐言事，作吏府中塵。","遂令河南治，今古無儔倫。","四海日富庶，道途隘蹄輪。","府西三百里，候館同魚鱗。","相公謂御史，勞子去自巡。","是時山水秋，光景何鮮新。","哀鴻鳴清耳，宿霧褰高旻。","遺我行旅詩，軒軒有風神。","譬如黃金盤，照耀荆璞真。","我來亦已幸，事賢友其仁。","持竿洛水側，孤坐屢窮辰。","多才自勞苦，無用祗因循。","辭免期匪遠，行行及山春。"]', '["相公罷論道，聿至活东人。","御史坐言事，作吏府中塵。","遂令河南治，今古無儔倫。","四海日富庶，道途隘蹄輪。","府西三百里，候館同鱼鱗。","相公謂御史，勞子去自巡。","是时山水秋，光景何鲜新。","哀鴻鳴清耳，宿霧褰高旻。","遺我行旅诗，軒軒有风神。","譬如黄金盤，照耀荆璞真。","我来亦已幸，事賢友其仁。","持竿洛水側，孤坐屢窮辰。","多才自勞苦，無用祗因循。","辞免期匪远，行行及山春。"]', '诗', 'shi', '', NULL, '酬裴十六功曹巡府西驛塗中見寄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990f8b56-0bff-467c-8a10-ddc620c9db41', '燕河南府秀才得生字', '燕河南府秀才得生字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["吾皇紹祖烈，天下再太平。","詔下諸郡國，歲貢鄉曲英。","元和五年冬，房公尹東京。","功曹上言公，是月當登名。","乃選二十縣，試官得鴻生。","羣儒負己材，相賀簡擇精。","怒起簸羽翮，引吭吐鏗轟。","此都自周公，文章繼名聲。","自非絕殊尤，難使耳目驚。","今者遭震薄，不能出聲鳴。","鄙夫忝縣尹，愧慄難爲情。","惟求文章寫，不敢妬與爭。","還家敕妻兒，具此煎炰烹。","柿紅蒲萄紫，肴果相扶檠。","芳荼出蜀門，好酒濃且清。","何能充歡燕，庶以露厥誠。","昨聞詔書下，權公作邦楨。","文人得其職，文道當大行。","陰風攪短日，冷雨澀不晴。","勉哉戒徒馭，家國遲子榮。"]', '["吾皇紹祖烈，天下再太平。","詔下諸郡国，歲貢乡曲英。","元和五年冬，房公尹东京。","功曹上言公，是月當登名。","乃選二十縣，試官得鴻生。","羣儒負己材，相賀簡擇精。","怒起簸羽翮，引吭吐鏗轟。","此都自周公，文章繼名声。","自非絕殊尤，难使耳目驚。","今者遭震薄，不能出声鳴。","鄙夫忝縣尹，愧慄难爲情。","惟求文章寫，不敢妬與爭。","還家敕妻兒，具此煎炰烹。","柿紅蒲萄紫，肴果相扶檠。","芳荼出蜀门，好酒濃且清。","何能充歡燕，庶以露厥誠。","昨闻詔书下，權公作邦楨。","文人得其職，文道當大行。","陰风攪短日，冷雨澀不晴。","勉哉戒徒馭，家国遲子榮。"]', '诗', 'shi', '', NULL, '燕河南府秀才得生字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('374ebe7b-244f-4d37-b7dc-baa3da2a3556', '送李翺', '送李翺', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["廣州萬里途，山重江逶迤。","行行何時到，誰能定歸期。","揖我出門去，顏色異恒時。","雖云有追送，足跡絕自茲。","人生一世間，不自張與弛。","譬如浮江木，縱橫豈自知。","寧懷別時苦，勿作別後思。"]', '["廣州万里途，山重江逶迤。","行行何时到，誰能定归期。","揖我出门去，顏色異恒时。","雖云有追送，足跡絕自茲。","人生一世间，不自張與弛。","譬如浮江木，縱橫豈自知。","寧懷別时苦，勿作別後思。"]', '诗', 'shi', '', NULL, '送李翺 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af65cc35-b1d3-4469-8614-4a2277ea2436', '送石洪處士赴河陽幕得起字', '送石洪处士赴河陽幕得起字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長把種樹書，人云避世士。","忽騎將軍馬，自號報恩子。","風雲入壯懷，泉石別幽耳。","鉅鹿師欲老，常山險猶恃。","豈惟彼相憂，固是吾徒恥。","去去事方急，酒行可以起。"]', '["长把種樹书，人云避世士。","忽騎將軍马，自號報恩子。","风云入壯懷，泉石別幽耳。","鉅鹿師欲老，常山險猶恃。","豈惟彼相憂，固是吾徒恥。","去去事方急，酒行可以起。"]', '诗', 'shi', '', NULL, '送石洪處士赴河陽幕得起字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe066ba7-1212-4923-a9ab-49488d245b29', '送湖南李正字歸', '送湖南李正字归', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長沙入楚深，洞庭值秋晚。","人隨鴻雁少，江共蒹葭遠。","歷歷余所經，悠悠子當返。","孤遊懷耿介，旅宿夢婉娩。","風土稍殊音，魚蝦日異飯。","親交俱在此，誰與同息偃。"]', '["长沙入楚深，洞庭值秋晚。","人隨鴻雁少，江共蒹葭远。","歷歷余所經，悠悠子當返。","孤游懷耿介，旅宿梦婉娩。","风土稍殊音，鱼蝦日異飯。","親交俱在此，誰與同息偃。"]', '诗', 'shi', '', NULL, '送湖南李正字歸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bbb6433-3602-4ed6-a136-c44d90bf46d6', '辛卯年雪', '辛卯年雪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["元和六年春，寒氣不肯歸。","河南二月末，雪花一尺圍。","崩騰相排拶，龍鳳交橫飛。","波濤何飄揚，天風吹旛旂。","白帝盛羽衛，鬖髿振裳衣。","白霓先啓途，從以萬玉妃。","翕翕陵厚載，譁譁弄陰機。","生平未曾見，何暇議是非。","或云豐年祥，飽食可庶幾。","善禱吾所慕，誰言寸誠微。"]', '["元和六年春，寒氣不肯归。","河南二月末，雪花一尺圍。","崩腾相排拶，龙鳳交橫飞。","波濤何飄揚，天风吹旛旂。","白帝盛羽衛，鬖髿振裳衣。","白霓先啓途，從以万玉妃。","翕翕陵厚載，譁譁弄陰機。","生平未曾见，何暇議是非。","或云豐年祥，飽食可庶幾。","善禱吾所慕，誰言寸誠微。"]', '诗', 'shi', '', NULL, '辛卯年雪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a75f95e-9e6a-4060-8b7e-511bcde7fad3', '醉留東野', '醉留东野', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔年因讀李白杜甫詩，長恨二人不相從。","吾與東野生並世，如何復躡二子蹤。","東野不得官，白首誇龍鍾。","韓子稍姦黠，自慙青蒿倚長松。","低頭拜東野，願得終始如駏蛩。","東野不廻頭，有如寸筳撞鉅鐘。","我願身爲雲，東野變爲龍。","四方上下逐東野，雖有離別無由逢。"]', '["昔年因读李白杜甫诗，长恨二人不相從。","吾與东野生並世，如何复躡二子蹤。","东野不得官，白首誇龙鍾。","韓子稍姦黠，自慙青蒿倚长松。","低头拜东野，願得終始如駏蛩。","东野不廻头，有如寸筳撞鉅鐘。","我願身爲云，东野变爲龙。","四方上下逐东野，雖有離別無由逢。"]', '诗', 'shi', '', NULL, '醉留東野 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d45b2bb2-b2ab-4027-b8b0-293cf3d0c0b9', '李花二首 一', '李花二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["平旦入西園，梨花數株若矜夸。","旁有一株李，顏色慘慘似含嗟。","問之不肯道所以，獨繞百帀至日斜。","忽憶前時經此樹，正見芳意初萌牙。","奈何趁酒不省錄，不見玉枝攢霜葩。","泫然爲汝下雨淚，無由反斾羲和車。","東風來吹不解顏，蒼茫夜氣生相遮。","冰盤夏薦碧實脆，斥去不御慚其花。"]', '["平旦入西园，梨花數株若矜夸。","旁有一株李，顏色慘慘似含嗟。","问之不肯道所以，独繞百帀至日斜。","忽憶前时經此樹，正见芳意初萌牙。","奈何趁酒不省錄，不见玉枝攢霜葩。","泫然爲汝下雨泪，無由反斾羲和车。","东风来吹不解顏，蒼茫夜氣生相遮。","冰盤夏薦碧實脆，斥去不御慚其花。"]', '诗', 'shi', '', NULL, '李花二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b07804-4b6a-41f7-8a62-542e60a6a2a9', '李花二首 二', '李花二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["當春天地爭奢華，洛陽園苑尤紛拏。","誰將平地萬堆雪，翦刻作此連天花。","日光赤色照未好，明月暫入都交加。","夜領張徹投盧仝，乘雲共至玉皇家。","長姬香御四羅列，縞裙練帨無等差。","靜濯明妝有所奉，顧我未肯置齒牙。","清寒瑩骨肝膽醒，一生思慮無由邪。"]', '["當春天地爭奢华，洛陽园苑尤紛拏。","誰將平地万堆雪，翦刻作此連天花。","日光赤色照未好，明月暫入都交加。","夜領張徹投盧仝，乘云共至玉皇家。","长姬香御四羅列，縞裙練帨無等差。","静濯明妝有所奉，顧我未肯置齒牙。","清寒瑩骨肝膽醒，一生思慮無由邪。"]', '诗', 'shi', '', NULL, '李花二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a64b68-43ba-4194-94ea-8db5169d73ee', '招楊之罘', '招楊之罘', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["柏生兩石間，萬歲終不大。","野馬不識人，難以駕車蓋。","柏移就平地，馬羈入廄中。","馬思自由悲，柏有傷根容。","傷根柏不死，千丈日以至。","馬悲罷還樂，振迅矜鞍轡。","之罘南山來，文字得我驚。","館置使讀書，日有求歸聲。","我令之罘歸，失得柏與馬。","之罘別我去，計出柏馬下。","我自之罘歸，入門思而悲。","之罘別我去，能不思我爲。","灑埽縣中居，引水經竹間。","囂譁所不及，何異山中閑。","前陳百家書，食有肉與魚。","先王遺文章，綴緝實在余。","禮稱獨學陋，易貴不遠復。","作詩招之罘，晨夕抱飢渴。"]', '["柏生兩石间，万歲終不大。","野马不識人，难以駕车蓋。","柏移就平地，马羈入廄中。","马思自由悲，柏有傷根容。","傷根柏不死，千丈日以至。","马悲罷還乐，振迅矜鞍轡。","之罘南山来，文字得我驚。","館置使读书，日有求归声。","我令之罘归，失得柏與马。","之罘別我去，計出柏马下。","我自之罘归，入门思而悲。","之罘別我去，能不思我爲。","灑埽縣中居，引水經竹间。","囂譁所不及，何異山中闲。","前陳百家书，食有肉與鱼。","先王遺文章，綴緝實在余。","禮稱独学陋，易貴不远复。","作诗招之罘，晨夕抱飢渴。"]', '诗', 'shi', '', NULL, '招楊之罘 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1404531-b21b-4e48-b715-9a9ead6cf56c', '寄盧仝', '寄盧仝', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["玉川先生洛城裏，破屋數間而已矣。","一奴長鬚不裹頭，一婢赤脚老無齒。","辛勤奉養十餘人，上有慈親下妻子。","先生結髮憎俗徒，閉門不出動一紀。","至今鄰僧乞米送，僕忝縣尹能不恥。","俸錢供給公私餘，時致薄少助祭祀。","勸參留守謁大尹，言語纔及輙掩耳。","水北山人得名聲，去年去作幕下士。","水南山人又繼往，鞍馬僕從塞閭里。","少室山人索價高，兩以諫官徴不起。","彼皆刺口論世事，有力未免遭驅使。","先生事業不可量，惟用法律自繩己。","春秋三傳束高閣，獨抱遺經究終始。","往年弄筆嘲同異，怪辭驚衆謗不已。","近來自說尋坦途，猶上虛空跨綠駬。","去年生兒名添丁，意令與國充耘耔。","國家丁口連四海，豈無農夫親耒耜。","先生抱才終大用，宰相未許終不仕。","假如不在陳力列，立言垂範亦足恃。","苗裔當蒙十世宥，豈謂貽厥無基阯。","故知忠孝生天性，潔身亂倫安足擬。","昨晚長鬚來下狀，隔牆惡少惡難似。","每騎屋山下窺闞，渾舍驚怕走折趾。","憑依婚媾欺官吏，不信令行能禁止。","先生受屈未曾語，忽此來告良有以。","嗟我身爲赤縣令，操權不用欲何俟。","立召賊曹呼伍伯，盡取鼠輩尸諸市。","先生又遣長鬚來，如此處置非所喜。","況又時當長養節，都邑未可猛政理。","先生固是余所畏，度量不敢窺涯涘。","放縱是誰之過歟，效尤戮僕愧前史。","買羊沽酒謝不敏，偶逢明月曜桃李。","先生有意許降臨，更遣長鬚致雙鯉。"]', '["玉川先生洛城裏，破屋數间而已矣。","一奴长鬚不裹头，一婢赤脚老無齒。","辛勤奉養十餘人，上有慈親下妻子。","先生結髮憎俗徒，閉门不出动一紀。","至今鄰僧乞米送，僕忝縣尹能不恥。","俸錢供給公私餘，时致薄少助祭祀。","勸參留守謁大尹，言語纔及輙掩耳。","水北山人得名声，去年去作幕下士。","水南山人又繼往，鞍马僕從塞閭里。","少室山人索價高，兩以諫官徴不起。","彼皆刺口論世事，有力未免遭驱使。","先生事業不可量，惟用法律自繩己。","春秋三傳束高閣，独抱遺經究終始。","往年弄笔嘲同異，怪辞驚衆謗不已。","近来自说尋坦途，猶上虛空跨綠駬。","去年生兒名添丁，意令與国充耘耔。","国家丁口連四海，豈無農夫親耒耜。","先生抱才終大用，宰相未許終不仕。","假如不在陳力列，立言垂範亦足恃。","苗裔當蒙十世宥，豈謂貽厥無基阯。","故知忠孝生天性，潔身亂倫安足擬。","昨晚长鬚来下狀，隔牆惡少惡难似。","每騎屋山下窺闞，渾舍驚怕走折趾。","憑依婚媾欺官吏，不信令行能禁止。","先生受屈未曾語，忽此来告良有以。","嗟我身爲赤縣令，操權不用欲何俟。","立召賊曹呼伍伯，尽取鼠輩尸諸市。","先生又遣长鬚来，如此处置非所喜。","況又时當长養節，都邑未可猛政理。","先生固是余所畏，度量不敢窺涯涘。","放縱是誰之過歟，效尤戮僕愧前史。","買羊沽酒謝不敏，偶逢明月曜桃李。","先生有意許降臨，更遣长鬚致雙鯉。"]', '诗', 'shi', '', NULL, '寄盧仝 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef723493-47e5-4466-bc49-c2cecd0bcb63', '酬司門盧四兄雲夫院長望秋作', '酬司门盧四兄云夫院长望秋作', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長安雨洗新秋出，極目寒鏡開塵函。","終南曉望蹋龍尾，倚天更覺青巉巉。","自知短淺無所補，從事久此穿朝衫。","歸來得便即遊覽，暫似壯馬脫重銜。","曲江荷花蓋十里，江湖生目思莫緘。","樂遊下矚無遠近，綠槐萍合不可芟。","白首寓居誰借問，平地寸步扃雲巖。","雲夫吾兄有狂氣，嗜好與俗殊酸鹹。","日來省我不肯去，論詩說賦相諵諵。","望秋一章已驚絕，猶言低抑避謗讒。","若使乘酣騁雄怪，造化何以當鐫劖。","嗟我小生值強伴，怯膽變勇神明鑒。","馳坑跨谷終未悔，爲利而止真貪饞。","高揖羣公謝名譽，遠追甫白感至諴。","樓頭完月不共宿，其奈就缺行攕攕。"]', '["长安雨洗新秋出，極目寒镜开塵函。","終南晓望蹋龙尾，倚天更覺青巉巉。","自知短淺無所補，從事久此穿朝衫。","归来得便即游覽，暫似壯马脫重銜。","曲江荷花蓋十里，江湖生目思莫緘。","乐游下矚無远近，綠槐萍合不可芟。","白首寓居誰借问，平地寸步扃云巖。","云夫吾兄有狂氣，嗜好與俗殊酸鹹。","日来省我不肯去，論诗说賦相諵諵。","望秋一章已驚絕，猶言低抑避謗讒。","若使乘酣騁雄怪，造化何以當鐫劖。","嗟我小生值強伴，怯膽变勇神明鑒。","驰坑跨谷終未悔，爲利而止真貪饞。","高揖羣公謝名譽，远追甫白感至諴。","楼头完月不共宿，其奈就缺行攕攕。"]', '诗', 'shi', '', NULL, '酬司門盧四兄雲夫院長望秋作 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e9f5dd2-0524-495f-8a52-94212ad97ed4', '誰氏子', '誰氏子', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["非癡非狂誰氏子，去入王屋稱道士。","白頭老母遮門啼，挽斷衫袖留不止。","翠眉新婦年二十，載送還家哭穿市。","或云欲學吹鳳笙，所慕靈妃嫓蕭史。","又云時俗輕尋常，力行險怪取貴仕。","神僊雖然有傳說，知者盡知其妄矣。","聖君賢相安可欺，乾死窮山竟何俟。","嗚呼余心誠豈弟，願往敎誨究終始。","罰一勸百政之經，不從而誅未晚耳。","誰其友親能哀憐，寫吾此詩持送似。"]', '["非癡非狂誰氏子，去入王屋稱道士。","白头老母遮门啼，挽斷衫袖留不止。","翠眉新婦年二十，載送還家哭穿市。","或云欲学吹鳳笙，所慕靈妃嫓蕭史。","又云时俗轻尋常，力行險怪取貴仕。","神僊雖然有傳说，知者尽知其妄矣。","聖君賢相安可欺，乾死窮山竟何俟。","嗚呼余心誠豈弟，願往敎誨究終始。","罰一勸百政之經，不從而誅未晚耳。","誰其友親能哀怜，寫吾此诗持送似。"]', '诗', 'shi', '', NULL, '誰氏子 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d44bf2d-b57a-447f-a0ee-57f512d2727d', '河南令舍池臺', '河南令舍池台', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["灌池纔盈五六丈，築臺不過七八尺。","欲將層級壓籬落，未許波瀾量斗石。","規摹雖巧何足誇，景趣不遠真可惜。","長令人吏遠趨走，已有蛙黽助狼籍。"]', '["灌池纔盈五六丈，築台不過七八尺。","欲將層級壓籬落，未許波瀾量斗石。","規摹雖巧何足誇，景趣不远真可惜。","长令人吏远趨走，已有蛙黽助狼籍。"]', '诗', 'shi', '', NULL, '河南令舍池臺 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76461079-8151-4e54-9be8-f650b406a657', '送無本師歸范陽', '送無本師归范陽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["無本於爲文，身大不及膽。","吾嘗示之難，勇往無不敢。","蛟龍弄角牙，造次欲手攬。","衆鬼囚大幽，下覰襲玄窞。","天陽熙四海，注視首不頷。","鯨鵬相摩窣，兩舉快一噉。","夫豈能必然，固已謝黯黮。","狂詞肆滂葩，低昂見舒慘。","姦窮怪變得，往往造平澹。","蠭蟬碎錦纈，綠池披菡萏。","芝英擢荒榛，孤翮起連菼。","家住幽都遠，未識氣先感。","來尋吾何能，無殊嗜昌歜。","始見洛陽春，桃枝綴紅糝。","遂來長安里，時卦轉習坎。","老嬾無鬬心，久不事鉛槧。","欲以金帛酬，舉室常顑頷。","念當委我去，雪霜刻以憯。","獰飆攪空衢，天地與頓撼。","勉率吐歌詩，慰女別後覽。"]', '["無本於爲文，身大不及膽。","吾嘗示之难，勇往無不敢。","蛟龙弄角牙，造次欲手攬。","衆鬼囚大幽，下覰襲玄窞。","天陽熙四海，注視首不頷。","鯨鵬相摩窣，兩舉快一噉。","夫豈能必然，固已謝黯黮。","狂词肆滂葩，低昂见舒慘。","姦窮怪变得，往往造平澹。","蠭蟬碎錦纈，綠池披菡萏。","芝英擢荒榛，孤翮起連菼。","家住幽都远，未識氣先感。","来尋吾何能，無殊嗜昌歜。","始见洛陽春，桃枝綴紅糝。","遂来长安里，时卦轉習坎。","老嬾無鬬心，久不事鉛槧。","欲以金帛酬，舉室常顑頷。","念當委我去，雪霜刻以憯。","獰飆攪空衢，天地與頓撼。","勉率吐歌诗，慰女別後覽。"]', '诗', 'shi', '', NULL, '送無本師歸范陽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9b8047-2410-47ae-a24c-aad7342b338f', '石鼓歌', '石鼓歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["張生手持石鼓文，勸我試作石鼓歌。","少陵無人謫仙死，才薄將奈石鼓何。","周綱陵遲四海沸，宣王憤起揮天戈。","大開明堂受朝賀，諸侯劒佩鳴相磨。","蒐于岐陽騁雄俊，萬里禽獸皆遮羅。","鐫功勒成告萬世，鑿石作鼓隳嵯峨。","從臣才藝咸第一，揀選撰刻留山阿。","雨淋日炙野火燎，鬼物守護煩撝呵。","公從何處得紙本，毫髮盡備無差訛。","辭嚴義密讀難曉，字體不類隸與科。","年深豈免有缺畫，快劒斫斷生蛟鼉。","鸞翔鳳翥衆僊下，珊瑚碧樹交枝柯。","金繩鐵索鎖紐壯，古鼎躍水龍騰梭。","陋儒編詩不收入，二雅褊迫無委蛇。","孔子西行不到秦，掎摭星宿遺羲娥。","嗟予好古生苦晚，對此涕淚雙滂沱。","憶昔初蒙博士徴，其年始改稱元和。","故人從軍在右輔，爲我度量掘臼科。","濯冠沐浴告祭酒，如此至寶存豈多。","氊包席裹可立致，十鼓祗載數駱駝。","薦諸太廟比郜鼎，光價豈止百倍過。","聖恩若許留太學，諸生講解得切磋。","觀經鴻都尚填咽，坐見舉國來奔波。","剜苔剔蘚露節角，安置妥帖平不頗。","大廈深簷與蓋覆，經歷久遠期無佗。","中朝大官老於事，詎肯感激徒媕婀。","牧童敲火牛礪角，誰復著手爲摩挲。","日銷月鑠就埋沒，六年西顧空吟哦。","羲之俗書趁姿媚，數紙尚可博白鵝。","繼周八代爭戰罷，無人收拾理則那。","方今太平日無事，柄任儒術崇丘軻。","安能以此上論列，願借辨口如懸河。","石鼓之歌止於此，嗚呼吾意其蹉跎。"]', '["張生手持石鼓文，勸我試作石鼓歌。","少陵無人謫仙死，才薄將奈石鼓何。","周綱陵遲四海沸，宣王憤起揮天戈。","大开明堂受朝賀，諸侯劒佩鳴相磨。","蒐于岐陽騁雄俊，万里禽獸皆遮羅。","鐫功勒成告万世，鑿石作鼓隳嵯峨。","從臣才藝咸第一，揀選撰刻留山阿。","雨淋日炙野火燎，鬼物守護煩撝呵。","公從何处得紙本，毫髮尽備無差訛。","辞嚴義密读难晓，字體不類隸與科。","年深豈免有缺畫，快劒斫斷生蛟鼉。","鸾翔鳳翥衆僊下，珊瑚碧樹交枝柯。","金繩鐵索鎖紐壯，古鼎躍水龙腾梭。","陋儒編诗不收入，二雅褊迫無委蛇。","孔子西行不到秦，掎摭星宿遺羲娥。","嗟予好古生苦晚，对此涕泪雙滂沱。","憶昔初蒙博士徴，其年始改稱元和。","故人從軍在右輔，爲我度量掘臼科。","濯冠沐浴告祭酒，如此至寶存豈多。","氊包席裹可立致，十鼓祗載數駱駝。","薦諸太廟比郜鼎，光價豈止百倍過。","聖恩若許留太学，諸生講解得切磋。","观經鴻都尚填咽，坐见舉国来奔波。","剜苔剔蘚露節角，安置妥帖平不頗。","大廈深簷與蓋覆，經歷久远期無佗。","中朝大官老於事，詎肯感激徒媕婀。","牧童敲火牛礪角，誰复著手爲摩挲。","日銷月鑠就埋沒，六年西顧空吟哦。","羲之俗书趁姿媚，數紙尚可博白鵝。","繼周八代爭戰罷，無人收拾理則那。","方今太平日無事，柄任儒術崇丘軻。","安能以此上論列，願借辨口如懸河。","石鼓之歌止於此，嗚呼吾意其蹉跎。"]', '诗', 'shi', '', NULL, '石鼓歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b07aab6-3a5c-44ca-b474-70083158bed5', '雙鳥詩', '雙鸟诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雙鳥海外來，飛飛到中州。","一鳥落城市，一鳥集巖幽。","不得相伴鳴，爾來三千秋。","兩鳥各閉口，萬象銜口頭。","春風卷地起，百鳥皆飄浮。","兩鳥忽相逢，百日鳴不休。","有耳聒皆聾，有口反自羞。","百舌舊饒聲，從此恒低頭。","得病不呻喚，泯默至死休。","雷公告天公，百物須膏油。","自從兩鳥鳴，聒亂雷聲收。","鬼神怕嘲詠，造化皆停留。","草木有微情，挑抉示九州。","蟲鼠誠微物，不堪苦誅求。","不停兩鳥鳴，百物皆生愁。","不停兩鳥鳴，自此無春秋。","不停兩鳥鳴，日月難旋輈。","不停兩鳥鳴，大法失九疇。","周公不爲公，孔丘不爲丘。","天公怪兩鳥，各捉一處囚。","百蟲與百鳥，然後鳴啾啾。","兩鳥既別處，閉聲省愆尤。","朝食千頭龍，暮食千頭牛。","朝飲河生塵，暮飲海絕流。","還當三千秋，更起鳴相酬。"]', '["雙鸟海外来，飞飞到中州。","一鸟落城市，一鸟集巖幽。","不得相伴鳴，爾来三千秋。","兩鸟各閉口，万象銜口头。","春风卷地起，百鸟皆飄浮。","兩鸟忽相逢，百日鳴不休。","有耳聒皆聾，有口反自羞。","百舌旧饒声，從此恒低头。","得病不呻喚，泯默至死休。","雷公告天公，百物須膏油。","自從兩鸟鳴，聒亂雷声收。","鬼神怕嘲詠，造化皆停留。","草木有微情，挑抉示九州。","蟲鼠誠微物，不堪苦誅求。","不停兩鸟鳴，百物皆生愁。","不停兩鸟鳴，自此無春秋。","不停兩鸟鳴，日月难旋輈。","不停兩鸟鳴，大法失九疇。","周公不爲公，孔丘不爲丘。","天公怪兩鸟，各捉一处囚。","百蟲與百鸟，然後鳴啾啾。","兩鸟既別处，閉声省愆尤。","朝食千头龙，暮食千头牛。","朝饮河生塵，暮饮海絕流。","還當三千秋，更起鳴相酬。"]', '诗', 'shi', '', NULL, '雙鳥詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2aa754f-6e6a-4eea-8361-bfef283409ec', '贈劉師服', '贈劉師服', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["羨君齒牙牢且潔，大肉硬餅如刀截。","我今呀豁落者多，所存十餘皆兀臲。","匙抄爛飯穩送之，合口軟嚼如牛呞。","妻兒恐我生悵望，盤中不飣栗與棃。","祗今年纔四十五，後日懸知漸莽鹵。","朱顏皓頸訝莫親，此外諸餘誰更數。","憶昔太公仕進初，口含兩齒無贏餘。","虞翻十三比豈少，遂自惋恨形於書。","丈夫命存百無害，誰能點檢形骸外。","巨緡東釣儻可期，與子共飽鯨魚膾。"]', '["羨君齒牙牢且潔，大肉硬餅如刀截。","我今呀豁落者多，所存十餘皆兀臲。","匙抄爛飯穩送之，合口軟嚼如牛呞。","妻兒恐我生悵望，盤中不飣栗與棃。","祗今年纔四十五，後日懸知漸莽鹵。","朱顏皓頸訝莫親，此外諸餘誰更數。","憶昔太公仕進初，口含兩齒無贏餘。","虞翻十三比豈少，遂自惋恨形於书。","丈夫命存百無害，誰能点檢形骸外。","巨緡东釣儻可期，與子共飽鯨鱼膾。"]', '诗', 'shi', '', NULL, '贈劉師服 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3badf1e6-af73-4e46-8567-eb4a61673057', '題炭谷湫祠堂', '題炭谷湫祠堂', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["萬生都陽明，幽暗鬼所寰。","嗟龍獨何智，出入人鬼間。","不知誰爲助，若執造化關。","厭處平地水，巢居插天山。","列峰若攢指，石盂仰環環。","巨靈高其捧，保此一掬慳。","森沈固含蓄，本以儲陰奸。","魚鼈蒙擁護，羣嬉傲天頑。","翾翾棲託禽，飛飛一何閑。","祠堂像侔真，擢玉紆煙鬟。","羣怪儼伺候，恩威在其顏。","我來日正中，悚惕思先還。","寄立尺寸地，敢言來途艱。","吁無吹毛刃，血此牛蹄殷。","至令乘水旱，鼓舞寡與鰥。","林叢鎮冥冥，窮年無由刪。","妍英雜豔實，星瑣黃朱斑。","石級皆險滑，顛躋莫牽攀。","龍區雛衆碎，付與宿已頒。","棄去可奈何，吾其死茅菅。"]', '["万生都陽明，幽暗鬼所寰。","嗟龙独何智，出入人鬼间。","不知誰爲助，若執造化关。","厭处平地水，巢居插天山。","列峰若攢指，石盂仰环环。","巨靈高其捧，保此一掬慳。","森沈固含蓄，本以儲陰奸。","鱼鼈蒙擁護，羣嬉傲天頑。","翾翾棲託禽，飞飞一何闲。","祠堂像侔真，擢玉紆煙鬟。","羣怪儼伺候，恩威在其顏。","我来日正中，悚惕思先還。","寄立尺寸地，敢言来途艱。","吁無吹毛刃，血此牛蹄殷。","至令乘水旱，鼓舞寡與鰥。","林叢鎮冥冥，窮年無由刪。","妍英杂豔實，星瑣黄朱斑。","石級皆險滑，顛躋莫牽攀。","龙區雛衆碎，付與宿已頒。","棄去可奈何，吾其死茅菅。"]', '诗', 'shi', '', NULL, '題炭谷湫祠堂 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8adc45-8900-4717-9037-020169e0df9f', '聽穎師彈琴', '听穎師彈琴', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昵昵兒女語，恩怨相爾汝。","劃然變軒昂，勇士赴敵場。","浮雲柳絮無根蔕，天地闊遠隨飛揚。","喧啾百鳥羣，忽見孤鳳皇。","躋攀分寸不可上，失勢一落千丈強。","嗟余有兩耳，未省聽絲篁。","自聞穎師彈，起坐在一旁。","推手遽止之，濕衣淚滂滂。","穎乎爾誠能，無以冰炭置我腸。"]', '["昵昵兒女語，恩怨相爾汝。","劃然变軒昂，勇士赴敵場。","浮云柳絮無根蔕，天地闊远隨飞揚。","喧啾百鸟羣，忽见孤鳳皇。","躋攀分寸不可上，失勢一落千丈強。","嗟余有兩耳，未省听絲篁。","自闻穎師彈，起坐在一旁。","推手遽止之，濕衣泪滂滂。","穎乎爾誠能，無以冰炭置我腸。"]', '诗', 'shi', '', NULL, '聽穎師彈琴 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b10808b-630a-4551-860f-abe2ecc4c051', '送陸暢歸江南', '送陸暢归江南', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["舉舉江南子，名以能詩聞。","一來取高第，官佐東宮軍。","迎婦丞相府，誇映秀士羣。","鸞鳴桂樹間，觀者何繽紛。","人事喜顛倒，旦夕異所云。","蕭蕭青雲幹，遂逐荆棘焚。","歲晚鴻雁過，鄉思見新文。","踐此秦關雪，家彼吳洲雲。","悲啼上車女，骨肉不可分。","感慨都門別，丈夫酒方醺。","我實門下士，力薄蚋與蚊。","受恩不即報，永負湘中墳。"]', '["舉舉江南子，名以能诗闻。","一来取高第，官佐东宮軍。","迎婦丞相府，誇映秀士羣。","鸾鳴桂樹间，观者何繽紛。","人事喜顛倒，旦夕異所云。","蕭蕭青云幹，遂逐荆棘焚。","歲晚鴻雁過，乡思见新文。","踐此秦关雪，家彼吳洲云。","悲啼上车女，骨肉不可分。","感慨都门別，丈夫酒方醺。","我實门下士，力薄蚋與蚊。","受恩不即報，永負湘中墳。"]', '诗', 'shi', '', NULL, '送陸暢歸江南 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22420c03-fb25-4ce7-a428-093f04461ebf', '送進士劉師服東歸', '送進士劉師服东归', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["猛虎落檻穽，坐食如孤㹠。","丈夫在富貴，豈必守一門。","公心有勇氣，公口有直言。","奈何任埋沒，不自求騰軒。","僕本亦進士，頗嘗究根源。","由來骨鯁材，喜被軟弱吞。","低頭受侮笑，隱忍硉兀冤。","泥雨城東路，夏槐作雲屯。","還家雖闕短，指日親晨飧。","攜持令名歸，自足貽家尊。","時節不可翫，親交可攀援。","勉來取金紫，勿久休中園。"]', '["猛虎落檻穽，坐食如孤㹠。","丈夫在富貴，豈必守一门。","公心有勇氣，公口有直言。","奈何任埋沒，不自求腾軒。","僕本亦進士，頗嘗究根源。","由来骨鯁材，喜被軟弱吞。","低头受侮笑，隐忍硉兀冤。","泥雨城东路，夏槐作云屯。","還家雖闕短，指日親晨飧。","携持令名归，自足貽家尊。","时節不可翫，親交可攀援。","勉来取金紫，勿久休中园。"]', '诗', 'shi', '', NULL, '送進士劉師服東歸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c486e4f-38fd-4f61-848a-9ed6da82a49e', '嘲魯連子', '嘲魯連子', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["魯連細而黠，有似黃鷂子。","田巴兀老蒼，憐汝矜爪觜。","開端要驚人，雄跨吾厭矣。","高拱禪鴻聲，若輟一杯水。","獨稱唐虞賢，顧未知之耳。"]', '["魯連細而黠，有似黄鷂子。","田巴兀老蒼，怜汝矜爪觜。","开端要驚人，雄跨吾厭矣。","高拱禪鴻声，若輟一杯水。","独稱唐虞賢，顧未知之耳。"]', '诗', 'shi', '', NULL, '嘲魯連子 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ee65924-3f5e-46f7-9e44-bfa0e8938679', '贈張籍', '贈張籍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["吾老著讀書，餘事不挂眼。","有兒雖甚憐，敎示不免簡。","君來好呼出，踉蹡越門限。","懼其無所知，見則先媿赧。","昨因有緣事，上馬插手版。","留君住廳食，使立侍盤𧣴。","薄暮歸見君，迎我笑而莞。","指渠相賀言，此是黃金產。","吾愛其風骨，粹美無可揀。","試將詩義授，如以肉貫丳。","開祛露毫末，自得高蹇嵼。","我身蹈丘軻，爵位不早綰。","固宜長有人，文章紹編剗。","感荷君子德，怳若乘朽棧。","召令吐所記，解摘了瑟僴。","顧視窗壁間，親戚競覘矕。","喜氣排寒冬，逼耳鳴睍睆。","如今更誰恨，便可耕灞滻。"]', '["吾老著读书，餘事不挂眼。","有兒雖甚怜，敎示不免簡。","君来好呼出，踉蹡越门限。","懼其無所知，见則先媿赧。","昨因有緣事，上马插手版。","留君住廳食，使立侍盤𧣴。","薄暮归见君，迎我笑而莞。","指渠相賀言，此是黄金產。","吾愛其风骨，粹美無可揀。","試將诗義授，如以肉貫丳。","开祛露毫末，自得高蹇嵼。","我身蹈丘軻，爵位不早綰。","固宜长有人，文章紹編剗。","感荷君子德，怳若乘朽棧。","召令吐所記，解摘了瑟僴。","顧視窗壁间，親戚競覘矕。","喜氣排寒冬，逼耳鳴睍睆。","如今更誰恨，便可耕灞滻。"]', '诗', 'shi', '', NULL, '贈張籍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f275d5-d466-4ba0-8293-3889e7db130b', '調張籍', '調張籍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["李杜文章在，光燄萬丈長。","不知羣兒愚，那用故謗傷。","蚍蜉撼大樹，可笑不自量。","伊我生其後，舉頸遙相望。","夜夢多見之，晝思反微茫。","徒觀斧鑿痕，不矚治水航。","想當施手時，巨刃磨天揚。","垠崖劃崩豁，乾坤擺雷硠。","惟此兩夫子，家居率荒涼。","帝欲長吟哦，故遣起且僵。","翦翎送籠中，使看百鳥翔。","平生千萬篇，金薤垂琳琅。","仙官敕六丁，雷電下取將。","流落人間者，太山一毫芒。","我願生兩翅，捕逐出八荒。","精誠忽交通，百怪入我腸。","刺手拔鯨牙，舉瓢酌天漿。","騰身跨汗漫，不著織女襄。","顧語地上友，經營無太忙。","乞君飛霞佩，與我高頡頏。"]', '["李杜文章在，光燄万丈长。","不知羣兒愚，那用故謗傷。","蚍蜉撼大樹，可笑不自量。","伊我生其後，舉頸遙相望。","夜梦多见之，晝思反微茫。","徒观斧鑿痕，不矚治水航。","想當施手时，巨刃磨天揚。","垠崖劃崩豁，乾坤擺雷硠。","惟此兩夫子，家居率荒涼。","帝欲长吟哦，故遣起且僵。","翦翎送籠中，使看百鸟翔。","平生千万篇，金薤垂琳琅。","仙官敕六丁，雷電下取將。","流落人间者，太山一毫芒。","我願生兩翅，捕逐出八荒。","精誠忽交通，百怪入我腸。","刺手拔鯨牙，舉瓢酌天漿。","腾身跨汗漫，不著织女襄。","顧語地上友，經營無太忙。","乞君飞霞佩，與我高頡頏。"]', '诗', 'shi', '', NULL, '調張籍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69d1917-b86e-48a6-a8f3-079cef0064aa', '盧郎中雲夫寄示送盤谷子詩兩章歌以和之', '盧郎中云夫寄示送盤谷子诗兩章歌以和之', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔尋李愿向盤谷，正見高崖巨壁爭開張。","是時新晴天井溢，誰把長劒倚太行。","衝風吹破落天外，飛雨白日灑洛陽。","東蹈燕川食曠野，有饋木蕨芽滿筐。","馬頭溪深不可厲，借車載過水入箱。","平沙綠浪榜方口，雁鴨飛起穿垂楊。","窮探極覽頗恣橫，物外日月本不忙。","歸來辛苦欲誰爲，坐令再往之計墮眇芒。","閉門長安三日雪，推書撲筆歌慨慷。","旁無壯士遣屬和，遠憶盧老詩顛狂。","開緘忽覩送歸作，字向紙上皆軒昂。","又知李侯竟不顧，方冬獨入崔嵬藏。","我今進退幾時決，十年蠢蠢隨朝行。","家請官供不報答，何異雀鼠偷太倉。","行抽手版付丞相，不待彈劾還耕桑。"]', '["昔尋李愿向盤谷，正见高崖巨壁爭开張。","是时新晴天井溢，誰把长劒倚太行。","衝风吹破落天外，飞雨白日灑洛陽。","东蹈燕川食曠野，有饋木蕨芽满筐。","马头溪深不可厲，借车載過水入箱。","平沙綠浪榜方口，雁鴨飞起穿垂楊。","窮探極覽頗恣橫，物外日月本不忙。","归来辛苦欲誰爲，坐令再往之計墮眇芒。","閉门长安三日雪，推书撲笔歌慨慷。","旁無壯士遣屬和，远憶盧老诗顛狂。","开緘忽覩送归作，字向紙上皆軒昂。","又知李侯竟不顧，方冬独入崔嵬藏。","我今進退幾时決，十年蠢蠢隨朝行。","家請官供不報答，何異雀鼠偷太倉。","行抽手版付丞相，不待彈劾還耕桑。"]', '诗', 'shi', '', NULL, '盧郎中雲夫寄示送盤谷子詩兩章歌以和之 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b75633a-02a2-42f6-9e63-189fc17c34d2', '寄皇甫湜', '寄皇甫湜', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["敲門驚晝睡，問報睦州吏。","手把一封書，上有皇甫字。","拆書放牀頭，涕與淚垂四。","昏昏還就枕，惘惘夢相值。","悲哉無奇術，安得生兩翅。"]', '["敲门驚晝睡，问報睦州吏。","手把一封书，上有皇甫字。","拆书放牀头，涕與泪垂四。","昏昏還就枕，惘惘梦相值。","悲哉無奇術，安得生兩翅。"]', '诗', 'shi', '', NULL, '寄皇甫湜 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4cd89d-4903-4e4f-9c7f-07d4be7f0f1d', '病中贈張十八', '病中贈張十八', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["中虛得暴下，避冷臥北窗。","不蹋曉鼓朝，安眠聽逢逢。","籍也處閭里，抱能未施邦。","文章自娛戲，金石日擊撞。","龍文百斛鼎，筆力可獨扛。","談舌久不掉，非君亮誰雙。","扶几導之言，曲節初摐摐。","半途喜開鑿，派別失大江。","吾欲盈其氣，不令見麾幢。","牛羊滿田野，解斾束空杠。","傾尊與斟酌，四壁堆罌缸。","玄帷隔雪風，照爐釘明釭。","夜闌縱捭闔，哆口疏眉厖。","勢侔高陽翁，坐約齊橫降。","連日挾所有，形軀頓胮肛。","將歸乃徐謂，子言得無哤。","回軍與角逐，斫樹收窮龐。","雌聲吐款要，酒壺綴羊腔。","君乃崑崙渠，籍乃嶺頭瀧。","譬如蟻蛭微，詎可陵崆㟅。","幸願終賜之，斬拔枿與樁。","從此識歸處，東流水淙淙。"]', '["中虛得暴下，避冷臥北窗。","不蹋晓鼓朝，安眠听逢逢。","籍也处閭里，抱能未施邦。","文章自娛戲，金石日擊撞。","龙文百斛鼎，笔力可独扛。","談舌久不掉，非君亮誰雙。","扶几導之言，曲節初摐摐。","半途喜开鑿，派別失大江。","吾欲盈其氣，不令见麾幢。","牛羊满田野，解斾束空杠。","傾尊與斟酌，四壁堆罌缸。","玄帷隔雪风，照爐釘明釭。","夜闌縱捭闔，哆口疏眉厖。","勢侔高陽翁，坐約齊橫降。","連日挾所有，形軀頓胮肛。","將归乃徐謂，子言得無哤。","回軍與角逐，斫樹收窮龐。","雌声吐款要，酒壺綴羊腔。","君乃崑崙渠，籍乃嶺头瀧。","譬如蟻蛭微，詎可陵崆㟅。","幸願終賜之，斬拔枿與樁。","從此識归处，东流水淙淙。"]', '诗', 'shi', '', NULL, '病中贈張十八 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3869758-c131-425c-b942-75c5b902355b', '雜詩', '杂诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["古史散左右，詩書置後前。","豈殊蠹書蟲，生死文字間。","古道自愚憃，古言自包纏。","當今固殊古，誰與爲欣歡。","獨攜無言子，共升崑崙顛。","長風飄襟裾，遂起飛高圓。","下視禹九州，一塵集豪端。","遨嬉未云幾，下已億萬年。","向者夸奪子，萬墳厭其巔。","惜哉抱所見，白黑未及分。","慷慨爲悲咤，淚如九河飜。","指摘相告語，雖還今誰親。","翩然下大荒，被髮騎騏驎。"]', '["古史散左右，诗书置後前。","豈殊蠹书蟲，生死文字间。","古道自愚憃，古言自包纏。","當今固殊古，誰與爲欣歡。","独携無言子，共升崑崙顛。","长风飄襟裾，遂起飞高圓。","下視禹九州，一塵集豪端。","遨嬉未云幾，下已億万年。","向者夸奪子，万墳厭其巔。","惜哉抱所见，白黑未及分。","慷慨爲悲咤，泪如九河飜。","指摘相告語，雖還今誰親。","翩然下大荒，被髮騎騏驎。"]', '诗', 'shi', '', NULL, '雜詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d9851e-ed86-4b43-96a4-cee84889e1c6', '寄崔二十六立之', '寄崔二十六立之', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["西城員外丞，心迹兩屈奇。","往歲戰詞賦，不將勢力隨。","下驢入省門，左右驚紛披。","傲兀坐試席，深叢見孤羆。","文如飜水成，初不用意爲。","四座各低面，不敢捩眼窺。","升階揖侍郎，歸舍日未敧。","佳句喧衆口，考官敢瑕疵。","連年收科第，若摘頷底髭。","回首卿相位，通途無他岐。","豈論校書郎，袍笏光參差。","童穉見稱說，祝身得如斯。","儕輩妒且熱，喘如竹筒吹。","老婦願嫁女，約不論財貲。","老翁不量分，累月笞其兒。","攪攪爭附託，無人角雄雌。","由來人間事，翻覆不可知。","安有巢中鷇，插翅飛天陲。","駒麛著爪牙，猛虎借與皮。","汝頭有韁繫，汝脚有索縻。","陷身泥溝間，誰復稟指撝。","不脫吏部選，可見偶與奇。","又作朝士貶，得非命所施。","客居京城中，十日營一炊。","逼迫走巴蠻，恩愛座上離。","昨來漢水頭，始得完孤羇。","桁挂新衣裳，盎棄食殘糜。","苟無飢寒苦，那用分高卑。","憐我還好古，宦途同險巘。","每旬遺我書，竟歲無差池。","新篇奚其思，風幡肆逶迤。","又論諸毛功，劈水看蛟螭。","雷電生睒睗，角鬣相撐披。","屬我感窮景，抱華不能摛。","唱來和相報，媿歎俾我疵。","又寄百尺綵，緋紅相盛衰。","巧能喻其誠，深淺抽肝脾。","開展放我側，方餐涕垂匙。","朋交日凋謝，存者逐利移。","子寧獨迷誤，綴綴意益彌。","舉頭庭樹豁，狂飆卷寒曦。","迢遞山水隔，何由應塤篪。","別來就十年，君馬記騧驪。","長女當及事，誰助出帨縭。","諸男皆秀朗，幾能守家規。","文字銳氣在，輝輝見旌麾。","摧腸與慼容，能復持酒巵。","我雖未耋老，髮禿骨力羸。","所餘十九齒，飄颻盡浮危。","玄花著兩眼，視物隔褷䙰。","燕席謝不詣，游鞍懸莫騎。","敦敦凭書案，譬彼鳥黏黐。","且吾聞之師，不以物自隳。","孤豚眠糞壤，不慕太廟犧。","君看一時人，幾輩先騰馳。","過半黑頭死，陰蟲食枯骴。","歡華不滿眼，咎責塞兩儀。","觀名計之利，詎足相陪裨。","仁者恥貪冒，受祿量所宜。","無能食國惠，豈異哀癃罷。","久欲辭謝去，休令衆睢睢。","況又嬰疹疾，寧保軀不貲。","不能前死罷，內實慙神祇。","舊籍在東郡，茅屋枳棘籬。","還歸非無指，灞渭揚春澌。","生兮耕吾疆，死也埋吾陂。","文書自傳道，不仗史筆垂。","夫子固吾黨，新恩釋銜羈。","去來伊洛上，相待安罛箄。","我有雙飲𧣴，其銀得朱提。","黃金塗物象，雕鐫妙工倕。","乃令千里鯨，幺麽微螽斯。","猶能爭明月，擺掉出渺瀰。","野草花葉細，不辨薋菉葹。","緜緜相糾結，狀似環城陴。","四隅芙蓉樹，擢豔皆猗猗。","鯨以興君身，失所逢百罹。","月以喻夫道，僶勉勵莫虧。","草木明覆載，妍醜齊榮萎。","願君恒御之，行止雜燧觿。","異日期對舉，當如合分支。"]', '["西城員外丞，心迹兩屈奇。","往歲戰词賦，不將勢力隨。","下驢入省门，左右驚紛披。","傲兀坐試席，深叢见孤羆。","文如飜水成，初不用意爲。","四座各低面，不敢捩眼窺。","升階揖侍郎，归舍日未敧。","佳句喧衆口，考官敢瑕疵。","連年收科第，若摘頷底髭。","回首卿相位，通途無他岐。","豈論校书郎，袍笏光參差。","童穉见稱说，祝身得如斯。","儕輩妒且熱，喘如竹筒吹。","老婦願嫁女，約不論財貲。","老翁不量分，累月笞其兒。","攪攪爭附託，無人角雄雌。","由来人间事，翻覆不可知。","安有巢中鷇，插翅飞天陲。","駒麛著爪牙，猛虎借與皮。","汝头有韁繫，汝脚有索縻。","陷身泥溝间，誰复稟指撝。","不脫吏部選，可见偶與奇。","又作朝士貶，得非命所施。","客居京城中，十日營一炊。","逼迫走巴蠻，恩愛座上離。","昨来漢水头，始得完孤羇。","桁挂新衣裳，盎棄食殘糜。","苟無飢寒苦，那用分高卑。","怜我還好古，宦途同險巘。","每旬遺我书，竟歲無差池。","新篇奚其思，风幡肆逶迤。","又論諸毛功，劈水看蛟螭。","雷電生睒睗，角鬣相撐披。","屬我感窮景，抱华不能摛。","唱来和相報，媿歎俾我疵。","又寄百尺綵，緋紅相盛衰。","巧能喻其誠，深淺抽肝脾。","开展放我側，方餐涕垂匙。","朋交日凋謝，存者逐利移。","子寧独迷誤，綴綴意益彌。","舉头庭樹豁，狂飆卷寒曦。","迢遞山水隔，何由應塤篪。","別来就十年，君马記騧驪。","长女當及事，誰助出帨縭。","諸男皆秀朗，幾能守家規。","文字銳氣在，輝輝见旌麾。","摧腸與慼容，能复持酒巵。","我雖未耋老，髮禿骨力羸。","所餘十九齒，飄颻尽浮危。","玄花著兩眼，視物隔褷䙰。","燕席謝不詣，游鞍懸莫騎。","敦敦凭书案，譬彼鸟黏黐。","且吾闻之師，不以物自隳。","孤豚眠糞壤，不慕太廟犧。","君看一时人，幾輩先腾驰。","過半黑头死，陰蟲食枯骴。","歡华不满眼，咎責塞兩儀。","观名計之利，詎足相陪裨。","仁者恥貪冒，受祿量所宜。","無能食国惠，豈異哀癃罷。","久欲辞謝去，休令衆睢睢。","況又嬰疹疾，寧保軀不貲。","不能前死罷，內實慙神祇。","旧籍在东郡，茅屋枳棘籬。","還归非無指，灞渭揚春澌。","生兮耕吾疆，死也埋吾陂。","文书自傳道，不仗史笔垂。","夫子固吾黨，新恩釋銜羈。","去来伊洛上，相待安罛箄。","我有雙饮𧣴，其銀得朱提。","黄金塗物象，雕鐫妙工倕。","乃令千里鯨，幺麽微螽斯。","猶能爭明月，擺掉出渺瀰。","野草花葉細，不辨薋菉葹。","緜緜相糾結，狀似环城陴。","四隅芙蓉樹，擢豔皆猗猗。","鯨以兴君身，失所逢百罹。","月以喻夫道，僶勉勵莫虧。","草木明覆載，妍醜齊榮萎。","願君恒御之，行止杂燧觿。","異日期对舉，當如合分支。"]', '诗', 'shi', '', NULL, '寄崔二十六立之 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7ae571-5241-4ea9-82f7-0d49eeebd710', '月蝕詩效玉川子作', '月蝕诗效玉川子作', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["元和庚寅斗插子，月十四日三更中。","森森萬木夜僵立，寒氣屓奰頑無風。","月形如白盤，完完上天東。","忽然有物來噉之，不知是何蟲。","如何至神物，遭此狼狽凶。","星如撒沙出，攢集爭強雄。","油燈不照席，是夕吐燄如長虹。","玉川子，涕泗下，中庭獨行。","念此日月者，爲天之眼睛。","此猶不自保，吾道何由行。","嘗聞古老言，疑是蝦蟆精。","徑圓千里納女腹，何處養女百醜形。","杷沙脚手鈍，誰使女解緣青冥。","黃帝有四目，帝舜重其明。","今天祗兩目，何故許食使偏盲。","堯呼大水浸十日，不惜萬國赤子魚頭生。","女於此時若食日，雖食八九無嚵名。","赤龍黑鳥燒口熱，翎鬣倒側相搪撐。","婪酣大肚遭一飽，飢腸徹死無由鳴。","後時食月罪當死，天羅磕帀何處逃汝刑。","玉川子立於庭而言曰，地行賤臣仝。","再拜敢告上天公，臣有一寸刃。","可刳凶蟆腸，無梯可上天。","天階無由有臣蹤，寄牋東南風。","天門西北祈風通，丁寧附耳莫漏泄。","薄命正值飛廉慵，東方青色龍。","牙角何呀呀，從官百餘座。","嚼啜煩官家，月蝕汝不知。","安用爲龍窟天河，赤鳥司南方。","尾禿翅觰沙，月蝕于汝頭。","汝口開呀呀，蝦蟆掠汝兩吻過。","忍學省事不以汝觜啄蝦蟆，於菟蹲於西。","旗旄衛毿㲚，既從白帝祠。","又食於蜡禮有加，忍令月被惡物食。","枉於汝口插齒牙，烏龜怯姦。","怕寒縮頸，以殼自遮。","終令夸蛾抉汝出，卜師燒錐鑽灼滿板如星羅。","此外內外官，瑣細不足科。","臣請悉埽除，慎勿許語令啾譁。","幷光全耀歸我月，盲眼鏡淨無纖瑕。","弊蛙拘送主府官，帝箸下腹嘗其皤。","依前使兔操杵臼，玉階桂樹閑婆娑。","姮娥還宮室，太陽有室家。","天雖高，耳屬地。","感臣赤心，使臣知意。","雖無明言，潛喻厥旨。","有氣有形，皆吾赤子。","雖忿大傷，忍殺孩穉。","還汝月明，安行于次。","盡釋衆罪，以蛙磔死。"]', '["元和庚寅斗插子，月十四日三更中。","森森万木夜僵立，寒氣屓奰頑無风。","月形如白盤，完完上天东。","忽然有物来噉之，不知是何蟲。","如何至神物，遭此狼狽凶。","星如撒沙出，攢集爭強雄。","油灯不照席，是夕吐燄如长虹。","玉川子，涕泗下，中庭独行。","念此日月者，爲天之眼睛。","此猶不自保，吾道何由行。","嘗闻古老言，疑是蝦蟆精。","徑圓千里納女腹，何处養女百醜形。","杷沙脚手鈍，誰使女解緣青冥。","黄帝有四目，帝舜重其明。","今天祗兩目，何故許食使偏盲。","堯呼大水浸十日，不惜万国赤子鱼头生。","女於此时若食日，雖食八九無嚵名。","赤龙黑鸟燒口熱，翎鬣倒側相搪撐。","婪酣大肚遭一飽，飢腸徹死無由鳴。","後时食月罪當死，天羅磕帀何处逃汝刑。","玉川子立於庭而言曰，地行賤臣仝。","再拜敢告上天公，臣有一寸刃。","可刳凶蟆腸，無梯可上天。","天階無由有臣蹤，寄牋东南风。","天门西北祈风通，丁寧附耳莫漏泄。","薄命正值飞廉慵，东方青色龙。","牙角何呀呀，從官百餘座。","嚼啜煩官家，月蝕汝不知。","安用爲龙窟天河，赤鸟司南方。","尾禿翅觰沙，月蝕于汝头。","汝口开呀呀，蝦蟆掠汝兩吻過。","忍学省事不以汝觜啄蝦蟆，於菟蹲於西。","旗旄衛毿㲚，既從白帝祠。","又食於蜡禮有加，忍令月被惡物食。","枉於汝口插齒牙，烏龟怯姦。","怕寒縮頸，以殼自遮。","終令夸蛾抉汝出，卜師燒錐鑽灼满板如星羅。","此外內外官，瑣細不足科。","臣請悉埽除，慎勿許語令啾譁。","幷光全耀归我月，盲眼镜淨無纖瑕。","弊蛙拘送主府官，帝箸下腹嘗其皤。","依前使兔操杵臼，玉階桂樹闲婆娑。","姮娥還宮室，太陽有室家。","天雖高，耳屬地。","感臣赤心，使臣知意。","雖無明言，潛喻厥旨。","有氣有形，皆吾赤子。","雖忿大傷，忍殺孩穉。","還汝月明，安行于次。","尽釋衆罪，以蛙磔死。"]', '诗', 'shi', '', NULL, '月蝕詩效玉川子作 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d2c0f7-48ad-4b35-b142-9ed40165e8e2', '孟生詩', '孟生诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["孟生江海士，古貌又古心。","嘗讀古人書，謂言古猶今。","作詩三百首，窅默咸池音。","騎驢到京國，欲和熏風琴。","豈識天子居，九重鬱沈沈。","一門百夫守，無籍不可尋。","晶光蕩相射，旗戟翩以森。","遷延乍却走，驚怪靡自任。","舉頭看白日，泣涕下霑襟。","朅來遊公卿，莫肯低華簪。","諒非軒冕族，應對多差參。","萍蓬風波急，桑榆日月侵。","奈何從進士，此路轉嶇嶔。","異質忌處羣，孤芳難寄林。","誰憐松桂性，競愛桃李陰。","朝悲辭樹葉，夕感歸巢禽。","顧我多慷慨，窮檐時見臨。","清宵靜相對，髮白聆苦吟。","采蘭起幽念，眇然望東南。","秦吳修且阻，兩地無數金。","我論徐方牧，好古天下欽。","竹實鳳所食，德馨神所歆。","求觀衆丘小，必上泰山岑。","求觀衆流細，必泛滄溟深。","子其聽我言，可以當所箴。","既獲則思返，無爲久滯淫。","卞和試三獻，期子在秋砧。"]', '["孟生江海士，古貌又古心。","嘗读古人书，謂言古猶今。","作诗三百首，窅默咸池音。","騎驢到京国，欲和熏风琴。","豈識天子居，九重鬱沈沈。","一门百夫守，無籍不可尋。","晶光蕩相射，旗戟翩以森。","遷延乍却走，驚怪靡自任。","舉头看白日，泣涕下霑襟。","朅来游公卿，莫肯低华簪。","諒非軒冕族，應对多差參。","萍蓬风波急，桑榆日月侵。","奈何從進士，此路轉嶇嶔。","異質忌处羣，孤芳难寄林。","誰怜松桂性，競愛桃李陰。","朝悲辞樹葉，夕感归巢禽。","顧我多慷慨，窮檐时见臨。","清宵静相对，髮白聆苦吟。","采蘭起幽念，眇然望东南。","秦吳修且阻，兩地無數金。","我論徐方牧，好古天下欽。","竹實鳳所食，德馨神所歆。","求观衆丘小，必上泰山岑。","求观衆流細，必泛滄溟深。","子其听我言，可以當所箴。","既獲則思返，無爲久滯淫。","卞和試三獻，期子在秋砧。"]', '诗', 'shi', '', NULL, '孟生詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9b330b-4d3f-4de9-96bd-610bdd918133', '射訓狐', '射訓狐', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["有鳥夜飛名訓狐，矜凶挾狡誇自呼。","乘時陰黑止我屋，聲勢慷慨非常麤。","安然大喚誰畏忌，造作百怪非無須。","聚鬼徵妖自朋扇，擺掉栱桷頹塈塗。","慈母抱兒怕入席，那暇更護雞窠雛。","我念乾坤德泰大，卵此惡物常勤劬。","縱之豈即遽有害，斗柄行拄西南隅。","誰謂停奸計尤劇，意欲唐突羲和烏。","侵更歷漏氣彌厲，何由僥倖休須臾。","咨余往射豈得已，候女兩眼張睢盱。","梟驚墮梁蛇走竇，一夫斬頸羣雛枯。"]', '["有鸟夜飞名訓狐，矜凶挾狡誇自呼。","乘时陰黑止我屋，声勢慷慨非常麤。","安然大喚誰畏忌，造作百怪非無須。","聚鬼徵妖自朋扇，擺掉栱桷頹塈塗。","慈母抱兒怕入席，那暇更護雞窠雛。","我念乾坤德泰大，卵此惡物常勤劬。","縱之豈即遽有害，斗柄行拄西南隅。","誰謂停奸計尤劇，意欲唐突羲和烏。","侵更歷漏氣彌厲，何由僥倖休須臾。","咨余往射豈得已，候女兩眼張睢盱。","梟驚墮梁蛇走竇，一夫斬頸羣雛枯。"]', '诗', 'shi', '', NULL, '射訓狐 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b0a242-4a1f-483b-9b13-63f488d66822', '將歸贈孟東野房蜀客', '將归贈孟东野房蜀客', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["君門不可入，勢利互相推。","借問讀書客，胡爲在京師。","舉頭未能對，閉眼聊自思。","倏忽十六年，終朝苦寒飢。","宦途竟寥落，鬢髮坐差池。","潁水清且寂，箕山坦而夷。","如今便當去，咄咄無自疑。"]', '["君门不可入，勢利互相推。","借问读书客，胡爲在京師。","舉头未能对，閉眼聊自思。","倏忽十六年，終朝苦寒飢。","宦途竟寥落，鬢髮坐差池。","潁水清且寂，箕山坦而夷。","如今便當去，咄咄無自疑。"]', '诗', 'shi', '', NULL, '將歸贈孟東野房蜀客 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7f6507-833d-42b2-b311-8643337f1767', '答孟郊', '答孟郊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["規模背時利，文字覰天巧。","人皆餘酒肉，子獨不得飽。","纔春思已亂，始秋悲又攪。","朝餐動及午，夜諷恒至卯。","名聲暫羶腥，腸肚鎮煎煼。","古心雖自鞭，世路終難拗。","弱拒喜張臂，猛拏閑縮爪。","見倒誰肯扶，從嗔我須齩。"]', '["規模背时利，文字覰天巧。","人皆餘酒肉，子独不得飽。","纔春思已亂，始秋悲又攪。","朝餐动及午，夜諷恒至卯。","名声暫羶腥，腸肚鎮煎煼。","古心雖自鞭，世路終难拗。","弱拒喜張臂，猛拏闲縮爪。","见倒誰肯扶，從嗔我須齩。"]', '诗', 'shi', '', NULL, '答孟郊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577f012c-8d67-4550-85df-204fd765b488', '從仕', '從仕', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["居閑食不足，從仕力難任。","兩事皆害性，一生恒苦心。","黃昏歸私室，惆悵起歎音。","棄置人間世，古來非獨今。"]', '["居闲食不足，從仕力难任。","兩事皆害性，一生恒苦心。","黄昏归私室，惆悵起歎音。","棄置人间世，古来非独今。"]', '诗', 'shi', '', NULL, '從仕 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e9346a-f26a-43b0-8b93-a0eeaf09b90d', '短燈檠歌', '短灯檠歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長檠八尺空自長，短檠二尺便且光。","黃簾綠幕朱戶閉，風露氣入秋堂涼。","裁衣寄遠淚眼暗，搔頭頻挑移近牀。","太學儒生東魯客，二十辭家來射策。","夜書細字綴語言，兩目眵昏頭雪白。","此時提攜當案前，看書到曉那能眠。","一朝富貴還自恣，長檠高張照珠翠。","吁嗟世事無不然，牆角君看短檠棄。"]', '["长檠八尺空自长，短檠二尺便且光。","黄簾綠幕朱戶閉，风露氣入秋堂涼。","裁衣寄远泪眼暗，搔头頻挑移近牀。","太学儒生东魯客，二十辞家来射策。","夜书細字綴語言，兩目眵昏头雪白。","此时提携當案前，看书到晓那能眠。","一朝富貴還自恣，长檠高張照珠翠。","吁嗟世事無不然，牆角君看短檠棄。"]', '诗', 'shi', '', NULL, '短燈檠歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f212e6-2886-49c3-8bfb-9bcacbfb3cae', '送劉師服', '送劉師服', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["夏半陰氣始，淅然雲景秋。","蟬聲入客耳，驚起不可留。","草草具盤饌，不待酒獻酬。","士生爲名累，有似魚中鈎。","齎材入市賣，貴者恒難售。","豈不畏顦顇，爲功忌中休。","勉哉耘其業，以待歲晚收。"]', '["夏半陰氣始，淅然云景秋。","蟬声入客耳，驚起不可留。","草草具盤饌，不待酒獻酬。","士生爲名累，有似鱼中鈎。","齎材入市賣，貴者恒难售。","豈不畏顦顇，爲功忌中休。","勉哉耘其業，以待歲晚收。"]', '诗', 'shi', '', NULL, '送劉師服 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1104a6-5946-4226-93c3-d75d4a1e8b84', '符讀書城南', '符读书城南', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["木之就規矩，在梓匠輪輿。","人之能爲人，由腹有詩書。","詩書勤乃有，不勤腹空虛。","欲知學之力，賢愚同一初。","由其不能學，所入遂異閭。","兩家各生子，提孩巧相如。","少長聚嬉戲，不殊同隊魚。","年至十二三，頭角稍相疎。","二十漸乖張，清溝映汙渠。","三十骨骼成，乃一龍一豬。","飛黃騰踏去，不能顧蟾蜍。","一爲馬前卒，鞭背生蟲蛆。","一爲公與相，潭潭府中居。","問之何因爾，學與不學歟。","金璧雖重寶，費用難貯儲。","學問藏之身，身在則有餘。","君子與小人，不繫父母且。","不見公與相，起身自犂鉏。","不見三公後，寒飢出無驢。","文章豈不貴，經訓乃菑畬。","潢潦無根源，朝滿夕已除。","人不通古今，馬牛而襟裾。","行身陷不義，況望多名譽。","時秋積雨霽，新涼入郊墟。","燈火稍可親，簡編可卷舒。","豈不旦夕念，爲爾惜居諸。","恩義有相奪，作詩勸躊躇。"]', '["木之就規矩，在梓匠輪輿。","人之能爲人，由腹有诗书。","诗书勤乃有，不勤腹空虛。","欲知学之力，賢愚同一初。","由其不能学，所入遂異閭。","兩家各生子，提孩巧相如。","少长聚嬉戲，不殊同隊鱼。","年至十二三，头角稍相疎。","二十漸乖張，清溝映汙渠。","三十骨骼成，乃一龙一豬。","飞黄腾踏去，不能顧蟾蜍。","一爲马前卒，鞭背生蟲蛆。","一爲公與相，潭潭府中居。","问之何因爾，学與不学歟。","金璧雖重寶，費用难貯儲。","学问藏之身，身在則有餘。","君子與小人，不繫父母且。","不见公與相，起身自犂鉏。","不见三公後，寒飢出無驢。","文章豈不貴，經訓乃菑畬。","潢潦無根源，朝满夕已除。","人不通古今，马牛而襟裾。","行身陷不義，況望多名譽。","时秋積雨霽，新涼入郊墟。","灯火稍可親，簡編可卷舒。","豈不旦夕念，爲爾惜居諸。","恩義有相奪，作诗勸躊躇。"]', '诗', 'shi', '', NULL, '符讀書城南 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa81c8f9-094a-45a0-ab24-166c99217b5d', '示爽', '示爽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["宣城去京國，里數逾三千。","念汝欲別我，解裝具盤筵。","日昏不能散，起坐相引牽。","冬夜豈不長，達旦燈燭然。","座中悉親故，誰肯捨汝眠。","念汝將一身，西來曾幾年。","名科揜衆俊，州考居吏前。","今從府公召，府公又時賢。","時輩千百人，孰不謂汝妍。","汝來江南近，里閭故依然。","昔日同戲兒，看汝立路邊。","人生但如此，其實亦可憐。","吾老世味薄，因循致留連。","強顏班行內，何實非罪愆。","才短難自力，懼終莫洗湔。","臨分不汝誑，有路即歸田。"]', '["宣城去京国，里數逾三千。","念汝欲別我，解裝具盤筵。","日昏不能散，起坐相引牽。","冬夜豈不长，達旦灯燭然。","座中悉親故，誰肯捨汝眠。","念汝將一身，西来曾幾年。","名科揜衆俊，州考居吏前。","今從府公召，府公又时賢。","时輩千百人，孰不謂汝妍。","汝来江南近，里閭故依然。","昔日同戲兒，看汝立路邊。","人生但如此，其實亦可怜。","吾老世味薄，因循致留連。","強顏班行內，何實非罪愆。","才短难自力，懼終莫洗湔。","臨分不汝誑，有路即归田。"]', '诗', 'shi', '', NULL, '示爽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff6d4609-5b29-4244-8ee5-feed483a96f4', '人日城南登高', '人日城南登高', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["初正候纔兆，涉七氣已弄。","靄靄野浮陽，暉暉水披凍。","聖朝身不廢，佳節古所用。","親交既許來，子妷亦可從。","盤蔬冬春雜，尊酒清濁共。","令徵前事爲，觴詠新詩送。","扶杖凌圮阯，刺船犯枯葑。","戀池羣鴨回，釋嶠孤雲縱。","人生本坦蕩，誰使妄倥傯。","直指桃李闌，幽尋寧止重。"]', '["初正候纔兆，涉七氣已弄。","靄靄野浮陽，暉暉水披凍。","聖朝身不廢，佳節古所用。","親交既許来，子妷亦可從。","盤蔬冬春杂，尊酒清濁共。","令徵前事爲，觴詠新诗送。","扶杖凌圮阯，刺船犯枯葑。","戀池羣鴨回，釋嶠孤云縱。","人生本坦蕩，誰使妄倥傯。","直指桃李闌，幽尋寧止重。"]', '诗', 'shi', '', NULL, '人日城南登高 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac9f803-f3db-4ab1-a5be-41d37fa1eb5b', '病鴟', '病鴟', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["屋東惡水溝，有鴟墮鳴悲。","青泥揜兩翅，拍拍不得離。","羣童呌相召，瓦礫爭先之。","計校生平事，殺却理亦宜。","奪攘不媿耻，飽滿盤天嬉。","晴日占光景，高風恣追隨。","遂凌鸞鳳羣，肯顧鴻鵠卑。","今者命運窮，遭逢巧丸兒。","中汝要害處，汝能不得施。","於吾乃何有，不忍乘其危。","丐汝將死命，浴以清水池。","朝餐輟魚肉，暝宿防狐貍。","自知無以致，蒙德久猶疑。","飽入深竹叢，飢來傍階基。","亮無責報心，固以聽所爲。","昨日有氣力，飛跳弄藩籬。","今晨忽徑去，曾不報我知。","僥倖非汝福，天衢汝休窺。","京城事彈射，豎子不易欺。","勿諱泥坑辱，泥坑乃良規。"]', '["屋东惡水溝，有鴟墮鳴悲。","青泥揜兩翅，拍拍不得離。","羣童呌相召，瓦礫爭先之。","計校生平事，殺却理亦宜。","奪攘不媿耻，飽满盤天嬉。","晴日占光景，高风恣追隨。","遂凌鸾鳳羣，肯顧鴻鵠卑。","今者命運窮，遭逢巧丸兒。","中汝要害处，汝能不得施。","於吾乃何有，不忍乘其危。","丐汝將死命，浴以清水池。","朝餐輟鱼肉，暝宿防狐貍。","自知無以致，蒙德久猶疑。","飽入深竹叢，飢来傍階基。","亮無責報心，固以听所爲。","昨日有氣力，飞跳弄藩籬。","今晨忽徑去，曾不報我知。","僥倖非汝福，天衢汝休窺。","京城事彈射，豎子不易欺。","勿諱泥坑辱，泥坑乃良規。"]', '诗', 'shi', '', NULL, '病鴟 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01254379-b998-4526-a356-2ace1e5ea7fd', '華山女', '华山女', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["街東街西講佛經，撞鐘吹螺鬧宮庭。","廣張罪福資誘脅，聽衆狎恰排浮萍。","黃衣道士亦講說，座下寥落如明星。","華山女兒家奉道，欲驅異敎歸僊靈。","洗粧拭面著冠帔，白咽紅頰長眉青。","遂來陞座演真訣，觀門不許人開扃。","不知誰人暗相報，訇然振動如雷霆。","掃除衆寺人跡絕，驊騮塞路連椔軿。","觀中人滿坐觀外，後至無地無由聽。","抽簪脫釧解環佩，堆金疊玉光青熒。","天門貴人傳詔召，六宮願識師顏形。","玉皇頷首許歸去，乘龍駕鶴去青冥。","豪家少年豈知道，來遶百帀脚不停。","雲牕霧閣事恍惚，重重翠幕深金屏。","僊梯難攀俗緣重，浪憑青鳥通丁寧。"]', '["街东街西講佛經，撞鐘吹螺鬧宮庭。","廣張罪福資誘脅，听衆狎恰排浮萍。","黄衣道士亦講说，座下寥落如明星。","华山女兒家奉道，欲驱異敎归僊靈。","洗粧拭面著冠帔，白咽紅頰长眉青。","遂来陞座演真訣，观门不許人开扃。","不知誰人暗相報，訇然振动如雷霆。","掃除衆寺人跡絕，驊騮塞路連椔軿。","观中人满坐观外，後至無地無由听。","抽簪脫釧解环佩，堆金叠玉光青熒。","天门貴人傳詔召，六宮願識師顏形。","玉皇頷首許归去，乘龙駕鹤去青冥。","豪家少年豈知道，来遶百帀脚不停。","云牕霧閣事恍惚，重重翠幕深金屏。","僊梯难攀俗緣重，浪憑青鸟通丁寧。"]', '诗', 'shi', '', NULL, '華山女 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9136ef2-3660-4fee-bcf9-fd3d3fb0ee75', '讀皇甫湜公安園池詩書其後二首 一', '读皇甫湜公安园池诗书其後二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["晉人目二子，其猶吹一吷。","區區自其下，顧肯挂牙舌。","春秋書王法，不誅其人身。","爾雅注蟲魚，定非磊落人。","湜也困公安，不自閑窮年。","枉智思掎摭，糞壤污穢豈有臧。","誠不如兩忘，但以一概量。"]', '["晉人目二子，其猶吹一吷。","區區自其下，顧肯挂牙舌。","春秋书王法，不誅其人身。","爾雅注蟲鱼，定非磊落人。","湜也困公安，不自闲窮年。","枉智思掎摭，糞壤污穢豈有臧。","誠不如兩忘，但以一概量。"]', '诗', 'shi', '', NULL, '讀皇甫湜公安園池詩書其後二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c6f9211-995d-4707-9a2c-2cd1ccfcb17b', '讀皇甫湜公安園池詩書其後二首 二', '读皇甫湜公安园池诗书其後二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我有一池水，蒲葦生其間。","蟲魚沸相嚼，日夜不得閑。","我初往觀之，其後益不觀。","觀之亂我意，不如不觀完。","用將濟諸人，捨得業孔顏。","百年詎幾時，君子不可閑。"]', '["我有一池水，蒲葦生其间。","蟲鱼沸相嚼，日夜不得闲。","我初往观之，其後益不观。","观之亂我意，不如不观完。","用將濟諸人，捨得業孔顏。","百年詎幾时，君子不可闲。"]', '诗', 'shi', '', NULL, '讀皇甫湜公安園池詩書其後二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56cefd7-b197-4f95-a7ef-ecc9fce835f3', '路傍堠', '路傍堠', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["堆堆路傍堠，一雙復一隻。","迎我出秦關，送我入楚澤。","千以高山遮，萬以遠水隔。","吾君勤聽治，照與日月敵。","臣愚幸可哀，臣罪庶可釋。","何當迎送歸，緣路高歷歷。"]', '["堆堆路傍堠，一雙复一隻。","迎我出秦关，送我入楚澤。","千以高山遮，万以远水隔。","吾君勤听治，照與日月敵。","臣愚幸可哀，臣罪庶可釋。","何當迎送归，緣路高歷歷。"]', '诗', 'shi', '', NULL, '路傍堠 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af68c9e-81a1-4d1f-bcee-de44b015366c', '食曲河驛', '食曲河驛', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["晨及曲河驛，悽然自傷情。","羣烏巢庭樹，乳燕飛簷楹。","而我抱重罪，孑孑萬里程。","親戚頓乖角，圖史棄縱橫。","下負明義重，上孤朝命榮。","殺身諒無補，何用答生成。"]', '["晨及曲河驛，悽然自傷情。","羣烏巢庭樹，乳燕飞簷楹。","而我抱重罪，孑孑万里程。","親戚頓乖角，圖史棄縱橫。","下負明義重，上孤朝命榮。","殺身諒無補，何用答生成。"]', '诗', 'shi', '', NULL, '食曲河驛 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca0d65f-bea4-453b-9675-6b5b22b22f88', '過南陽', '過南陽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南陽郭門外，桑下麥青青。","行子去未已，春鳩鳴不停。","秦商邈既遠，湖海浩將經。","孰忍生以慼，吾其寄餘齡。"]', '["南陽郭门外，桑下麦青青。","行子去未已，春鳩鳴不停。","秦商邈既远，湖海浩將經。","孰忍生以慼，吾其寄餘齡。"]', '诗', 'shi', '', NULL, '過南陽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b3eba8-1805-453c-acba-8b80dea48929', '瀧吏', '瀧吏', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南行逾六旬，始下昌樂瀧。","險惡不可狀，船石相舂撞。","往問瀧頭吏，潮州尚幾里。","行當何時到，土風復何似。","瀧吏垂手笑，官何問之愚。","譬官居京邑，何由知東吳。","東吳遊宦鄉，官知自有由。","潮州底處所，有罪乃竄流。","儂幸無負犯，何由到而知。","官今行自到，那遽妄問爲。","不虞卒見困，汗出媿且駭。","吏曰聊戲官，儂嘗使往罷。","嶺南大抵同，官去道苦遼。","下此三千里，有州始名潮。","惡溪瘴毒聚，雷電常洶洶。","鱷魚大於船，牙眼怖殺儂。","州南數十里，有海無天地。","颶風有時作，掀簸真差事。","聖人於天下，於物無不容。","比聞此州囚，亦在生還儂。","官無嫌此州，固罪人所徙。","官當明時來，事不待說委。","官不自謹慎，宜即引分往。","胡爲此水邊，神色久戃慌。","㼚大缾甖小，所任自有宜。","官何不自量，滿溢以取斯。","工農雖小人，事業各有守。","不知官在朝，有益國家不。","得無虱其間，不武亦不文。","仁義飭其躬，巧姦敗羣倫。","叩頭謝吏言，始慚今更羞。","歷官二十餘，國恩竝未酬。","凡吏之所訶，嗟實頗有之。","不即金木誅，敢不識恩私。","潮州雖云遠，雖惡不可過。","於身實已多，敢不持自賀。"]', '["南行逾六旬，始下昌乐瀧。","險惡不可狀，船石相舂撞。","往问瀧头吏，潮州尚幾里。","行當何时到，土风复何似。","瀧吏垂手笑，官何问之愚。","譬官居京邑，何由知东吳。","东吳游宦乡，官知自有由。","潮州底处所，有罪乃竄流。","儂幸無負犯，何由到而知。","官今行自到，那遽妄问爲。","不虞卒见困，汗出媿且駭。","吏曰聊戲官，儂嘗使往罷。","嶺南大抵同，官去道苦遼。","下此三千里，有州始名潮。","惡溪瘴毒聚，雷電常洶洶。","鱷鱼大於船，牙眼怖殺儂。","州南數十里，有海無天地。","颶风有时作，掀簸真差事。","聖人於天下，於物無不容。","比闻此州囚，亦在生還儂。","官無嫌此州，固罪人所徙。","官當明时来，事不待说委。","官不自謹慎，宜即引分往。","胡爲此水邊，神色久戃慌。","㼚大缾甖小，所任自有宜。","官何不自量，满溢以取斯。","工農雖小人，事業各有守。","不知官在朝，有益国家不。","得無虱其间，不武亦不文。","仁義飭其躬，巧姦敗羣倫。","叩头謝吏言，始慚今更羞。","歷官二十餘，国恩竝未酬。","凡吏之所訶，嗟實頗有之。","不即金木誅，敢不識恩私。","潮州雖云远，雖惡不可過。","於身實已多，敢不持自賀。"]', '诗', 'shi', '', NULL, '瀧吏 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b11e88-8115-4a9b-8a18-8aa74515d39b', '贈別元十八協律六首 一', '贈別元十八協律六首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["知識久去眼，吾行其既遠。","瞢瞢莫訾省，默默但寢飯。","子兮何爲者，冠珮立憲憲。","何氏之從學，蘭蕙已滿畹。","於何翫其光，以至歲向晚。","治惟尚和同，無俟於謇謇。","或師絕學賢，不以藝自輓。","子兮獨如何，能自媚婉娩。","金石出聲音，宮室發關楗。","何人識章甫，而知駿蹄踠。","惜乎吾無居，不得留息偃。","臨當背面時，裁詩示繾綣。"]', '["知識久去眼，吾行其既远。","瞢瞢莫訾省，默默但寢飯。","子兮何爲者，冠珮立憲憲。","何氏之從学，蘭蕙已满畹。","於何翫其光，以至歲向晚。","治惟尚和同，無俟於謇謇。","或師絕学賢，不以藝自輓。","子兮独如何，能自媚婉娩。","金石出声音，宮室發关楗。","何人識章甫，而知駿蹄踠。","惜乎吾無居，不得留息偃。","臨當背面时，裁诗示繾綣。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce23af5-4a29-4f10-ae1d-ff0a17933f17', '贈別元十八協律六首 二', '贈別元十八協律六首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["英英桂林伯，實惟文武特。","遠勞從事賢，來弔逐臣色。","南裔多山海，道里屢紆直。","風波無程期，所憂動不測。","子行誠艱難，我去未窮極。","臨別且何言，有淚不可拭。"]', '["英英桂林伯，實惟文武特。","远勞從事賢，来弔逐臣色。","南裔多山海，道里屢紆直。","风波無程期，所憂动不測。","子行誠艱难，我去未窮極。","臨別且何言，有泪不可拭。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da8ee23-30f7-4767-a3e5-ffdcff9034ae', '贈別元十八協律六首 三', '贈別元十八協律六首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["吾友柳子厚，其人藝且賢。","吾未識子時，已覽贈子篇。","寤寐想風采，於今已三年。","不意流竄路，旬日同食眠。","所聞昔已多，所得今過前。","如何又須別，使我抱悁悁。"]', '["吾友柳子厚，其人藝且賢。","吾未識子时，已覽贈子篇。","寤寐想风采，於今已三年。","不意流竄路，旬日同食眠。","所闻昔已多，所得今過前。","如何又須別，使我抱悁悁。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e6afd4-d6dd-4347-b20b-c2133154a437', '贈別元十八協律六首 四', '贈別元十八協律六首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["勢要情所重，排斥則埃塵。","骨肉未免然，又況四海人。","嶷嶷桂林伯，矯矯義勇身。","生平所未識，待我逾交親。","遺我數幅書，繼以藥物珍。","藥物防瘴癘，書勸養形神。","不知四罪地，豈有再起辰。","窮途致感激，肝膽還輪囷。"]', '["勢要情所重，排斥則埃塵。","骨肉未免然，又況四海人。","嶷嶷桂林伯，矯矯義勇身。","生平所未識，待我逾交親。","遺我數幅书，繼以藥物珍。","藥物防瘴癘，书勸養形神。","不知四罪地，豈有再起辰。","窮途致感激，肝膽還輪囷。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f34d14-a94c-46d1-a049-34ae7e28a62a', '贈別元十八協律六首 五', '贈別元十八協律六首 五', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["讀書患不多，思義患不明。","患足已不學，既學患不行。","子今四美具，實大華亦榮。","王官不可闕，未宜後諸生。","嗟我擯南海，無由助飛鳴。"]', '["读书患不多，思義患不明。","患足已不学，既学患不行。","子今四美具，實大华亦榮。","王官不可闕，未宜後諸生。","嗟我擯南海，無由助飞鳴。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 五 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9144589-d38d-42f5-a834-7fddfc0a063c', '贈別元十八協律六首 六', '贈別元十八協律六首 六', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["寄書龍城守，君驥何時秣。","峽山逢颶風，雷電助撞捽。","乘潮簸扶胥，近岸指一髮。","兩巖雖云牢，水石互飛發。","屯門雖云高，亦映波浪沒。","余罪不足惜，子生未宜忽。","胡爲不忍別，感謝情至骨。"]', '["寄书龙城守，君驥何时秣。","峽山逢颶风，雷電助撞捽。","乘潮簸扶胥，近岸指一髮。","兩巖雖云牢，水石互飞發。","屯门雖云高，亦映波浪沒。","余罪不足惜，子生未宜忽。","胡爲不忍別，感謝情至骨。"]', '诗', 'shi', '', NULL, '贈別元十八協律六首 六 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2697a5-7914-4440-be16-db76bb88be26', '初南食貽元十八協律', '初南食貽元十八協律', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["鱟實如惠文，骨眼相負行。","蠔相黏爲山，百十各自生。","蒲魚尾如蛇，口眼不相營。","蛤即是蝦蟆，同實浪異名。","章舉馬甲柱，鬬以怪自呈。","其餘數十種，莫不可歎驚。","我來禦魑魅，自宜味南烹。","調以鹹與酸，芼以椒與橙。","腥臊始發越，咀吞面汗騂。","惟蛇舊所識，實憚口眼獰。","開籠聽其去，鬱屈尚不平。","賣爾非我罪，不屠豈非情。","不祈靈珠報，幸無嫌怨幷。","聊歌以記之，又以告同行。"]', '["鱟實如惠文，骨眼相負行。","蠔相黏爲山，百十各自生。","蒲鱼尾如蛇，口眼不相營。","蛤即是蝦蟆，同實浪異名。","章舉马甲柱，鬬以怪自呈。","其餘數十種，莫不可歎驚。","我来禦魑魅，自宜味南烹。","調以鹹與酸，芼以椒與橙。","腥臊始發越，咀吞面汗騂。","惟蛇旧所識，實憚口眼獰。","开籠听其去，鬱屈尚不平。","賣爾非我罪，不屠豈非情。","不祈靈珠報，幸無嫌怨幷。","聊歌以記之，又以告同行。"]', '诗', 'shi', '', NULL, '初南食貽元十八協律 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335314f2-aa38-4f25-a0c3-6d8e375daec6', '宿曾江口示姪孫湘二首 一', '宿曾江口示姪孫湘二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雲昏水奔流，天水漭相圍。","三江滅無口，其誰識涯圻。","暮宿投民村，高處水半扉。","犬雞俱上屋，不復走與飛。","篙舟入其家，暝聞屋中唏。","問知歲常然，哀此爲生微。","海風吹寒晴，波揚衆星輝。","仰視北斗高，不知路所歸。"]', '["云昏水奔流，天水漭相圍。","三江滅無口，其誰識涯圻。","暮宿投民村，高处水半扉。","犬雞俱上屋，不复走與飞。","篙舟入其家，暝闻屋中唏。","问知歲常然，哀此爲生微。","海风吹寒晴，波揚衆星輝。","仰視北斗高，不知路所归。"]', '诗', 'shi', '', NULL, '宿曾江口示姪孫湘二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d1bdba-d2a0-4c84-aa2f-dd4df8598766', '宿曾江口示姪孫湘二首 二', '宿曾江口示姪孫湘二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["舟行忘故道，屈曲高林間。","林間無所有，奔流但潺潺。","嗟我亦拙謀，致身落南蠻。","茫然失所詣，無路何能還。"]', '["舟行忘故道，屈曲高林间。","林间無所有，奔流但潺潺。","嗟我亦拙謀，致身落南蠻。","茫然失所詣，無路何能還。"]', '诗', 'shi', '', NULL, '宿曾江口示姪孫湘二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af8728f-fca2-4092-a9a1-b554bfbd0a8f', '答柳柳州食蝦蟆', '答柳柳州食蝦蟆', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蝦蟆雖水居，水特變形貌。","強號爲蛙蛤，於實無所校。","雖然兩股長，其奈脊皴皰。","跳躑雖云高，意不離濘淖。","鳴聲相呼和，無理只取鬧。","周公所不堪，灑灰垂典敎。","我棄愁海濱，恒願眠不覺。","叵堪朋類多，沸耳作驚爆。","端能敗笙磬，仍工亂學校。","雖蒙句踐禮，竟不聞報效。","大戰元鼎年，孰強孰敗橈。","居然當鼎味，豈不辱釣罩。","余初不下喉，近亦能稍稍。","常懼染蠻夷，失平生好樂。","而君復何爲，甘食比豢豹。","獵較務同俗，全身斯爲孝。","哀哉思慮深，未見許回櫂。"]', '["蝦蟆雖水居，水特变形貌。","強號爲蛙蛤，於實無所校。","雖然兩股长，其奈脊皴皰。","跳躑雖云高，意不離濘淖。","鳴声相呼和，無理只取鬧。","周公所不堪，灑灰垂典敎。","我棄愁海濱，恒願眠不覺。","叵堪朋類多，沸耳作驚爆。","端能敗笙磬，仍工亂学校。","雖蒙句踐禮，竟不闻報效。","大戰元鼎年，孰強孰敗橈。","居然當鼎味，豈不辱釣罩。","余初不下喉，近亦能稍稍。","常懼染蠻夷，失平生好乐。","而君复何爲，甘食比豢豹。","獵較務同俗，全身斯爲孝。","哀哉思慮深，未见許回櫂。"]', '诗', 'shi', '', NULL, '答柳柳州食蝦蟆 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c8b4a6f-8aad-458d-9ca3-43dff3b224bd', '別趙子', '別趙子', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我遷於揭陽，君先揭陽居。","揭陽去京華，其里萬有餘。","不謂小郭中，有子可與娛。","心平而行高，兩通詩與書。","婆娑海水南，簸弄明月珠。","及我遷宜春，意欲攜以俱。","擺頭笑且言，我豈不足歟。","又奚爲於北，往來以紛如。","海中諸山中，幽子頗不無。","相期風濤觀，已久不可渝。","又嘗疑龍蝦，果誰雄牙鬚。","蚌蠃魚鼈蟲，瞿瞿以狙狙。","識一已忘十，大同細自殊。","欲一窮究之，時歲屢謝除。","今子南且北，豈非亦有圖。","人心未嘗同，不可一理區。","宜各從所務，未用相賢愚。"]', '["我遷於揭陽，君先揭陽居。","揭陽去京华，其里万有餘。","不謂小郭中，有子可與娛。","心平而行高，兩通诗與书。","婆娑海水南，簸弄明月珠。","及我遷宜春，意欲携以俱。","擺头笑且言，我豈不足歟。","又奚爲於北，往来以紛如。","海中諸山中，幽子頗不無。","相期风濤观，已久不可渝。","又嘗疑龙蝦，果誰雄牙鬚。","蚌蠃鱼鼈蟲，瞿瞿以狙狙。","識一已忘十，大同細自殊。","欲一窮究之，时歲屢謝除。","今子南且北，豈非亦有圖。","人心未嘗同，不可一理區。","宜各從所務，未用相賢愚。"]', '诗', 'shi', '', NULL, '別趙子 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571d0836-d8bc-4bc6-91a5-a35b7db77bc4', '除官赴闕至江州寄鄂岳李大夫', '除官赴闕至江州寄鄂岳李大夫', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["盆城去鄂渚，風便一日耳。","不枉故人書，無因帆江水。","故人辭禮闈，旌節鎮江圻。","而我竄逐者，龍鍾初得歸。","別來已三歲，望望長迢遞。","咫尺不相聞，平生那可計。","我齒落且盡，君鬢白幾何。","年皆過半百，來日苦無多。","少年樂新知，衰暮思故友。","譬如親骨肉，寧免相可不。","我昔實愚惷，不能降色辭。","子犯亦有言，臣猶自知之。","公其務貰過，我亦請改事。","桑榆儻可收，願寄相思字。"]', '["盆城去鄂渚，风便一日耳。","不枉故人书，無因帆江水。","故人辞禮闈，旌節鎮江圻。","而我竄逐者，龙鍾初得归。","別来已三歲，望望长迢遞。","咫尺不相闻，平生那可計。","我齒落且尽，君鬢白幾何。","年皆過半百，来日苦無多。","少年乐新知，衰暮思故友。","譬如親骨肉，寧免相可不。","我昔實愚惷，不能降色辞。","子犯亦有言，臣猶自知之。","公其務貰過，我亦請改事。","桑榆儻可收，願寄相思字。"]', '诗', 'shi', '', NULL, '除官赴闕至江州寄鄂岳李大夫 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7df79d-4efe-48f6-9fca-f55ee33f5510', '南山有高樹行贈李宗閔', '南山有高樹行贈李宗閔', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南山有高樹，花葉何衰衰。","上有鳳皇巢，鳳皇乳且棲。","四旁多長枝，羣鳥所托依。","黃鵠據其高，衆鳥接其卑。","不知何山鳥，羽毛有光輝。","飛飛擇所處，正得衆所希。","上承鳳皇恩，自期永不衰。","中與黃鵠羣，不自隱其私。","下視衆鳥羣，汝徒竟何爲。","不知挾丸子，心默有所規。","彈汝枝葉間，汝翅不覺摧。","或言由黃鵠，黃鵠豈有之。","慎勿猜衆鳥，衆鳥不足猜。","無人語鳳皇，汝屈安得知。","黃鵠得汝去，婆娑弄毛衣。","前汝下視鳥，各議汝瑕疵。","汝豈無朋匹，有口莫肯開。","汝落蒿艾間，幾時復能飛。","哀哀故山友，中夜思汝悲。","路遠翅翎短，不得持汝歸。"]', '["南山有高樹，花葉何衰衰。","上有鳳皇巢，鳳皇乳且棲。","四旁多长枝，羣鸟所托依。","黄鵠據其高，衆鸟接其卑。","不知何山鸟，羽毛有光輝。","飞飞擇所处，正得衆所希。","上承鳳皇恩，自期永不衰。","中與黄鵠羣，不自隐其私。","下視衆鸟羣，汝徒竟何爲。","不知挾丸子，心默有所規。","彈汝枝葉间，汝翅不覺摧。","或言由黄鵠，黄鵠豈有之。","慎勿猜衆鸟，衆鸟不足猜。","無人語鳳皇，汝屈安得知。","黄鵠得汝去，婆娑弄毛衣。","前汝下視鸟，各議汝瑕疵。","汝豈無朋匹，有口莫肯开。","汝落蒿艾间，幾时复能飞。","哀哀故山友，中夜思汝悲。","路远翅翎短，不得持汝归。"]', '诗', 'shi', '', NULL, '南山有高樹行贈李宗閔 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d209ca-7919-4442-836f-97a406c8a208', '猛虎行', '猛虎行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["猛虎雖云惡，亦各有匹儕。","羣行深谷間，百獸望風低。","身食黃熊父，子食赤豹麛。","擇肉於熊豹，肯視兔與貍。","正晝當谷眠，眼有百步威。","自矜無當對，氣性縱以乖。","朝怒殺其子，暮還食其妃。","匹儕四散走，猛虎還孤棲。","狐鳴門兩旁，烏鵲從噪之。","出逐猴入居，虎不知所歸。","誰云猛虎惡，中路正悲啼。","豹來銜其尾，熊來攫其頤。","猛虎死不辭，但慚前所爲。","虎坐無助死，況如汝細微。","故當結以信，親當結以私。","親故且不保，人誰信汝爲。"]', '["猛虎雖云惡，亦各有匹儕。","羣行深谷间，百獸望风低。","身食黄熊父，子食赤豹麛。","擇肉於熊豹，肯視兔與貍。","正晝當谷眠，眼有百步威。","自矜無當对，氣性縱以乖。","朝怒殺其子，暮還食其妃。","匹儕四散走，猛虎還孤棲。","狐鳴门兩旁，烏鵲從噪之。","出逐猴入居，虎不知所归。","誰云猛虎惡，中路正悲啼。","豹来銜其尾，熊来攫其頤。","猛虎死不辞，但慚前所爲。","虎坐無助死，況如汝細微。","故當結以信，親當結以私。","親故且不保，人誰信汝爲。"]', '诗', 'shi', '', NULL, '猛虎行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb827220-205f-431b-8488-2aadba1434d2', '雪後寄崔二十六丞公', '雪後寄崔二十六丞公', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["藍田十月雪塞關，我興南望愁羣山。","攢天嵬嵬凍相映，君乃寄命於其間。","秩卑俸薄食口衆，豈有酒食開容顏。","殿前羣公賜食罷，驊騮蹋路驕且閑。","稱多量少鑒裁密，豈念幽桂遺榛菅。","幾欲犯嚴出薦口，氣象硉兀未可攀。","歸來殞涕揜關臥，心之紛亂誰能刪。","詩翁憔悴斸荒棘，清玉刻佩聯玦環。","腦脂遮眼臥壯士，大弨挂壁無由彎。","乾坤惠施萬物遂，獨於數子懷偏慳。","朝欷暮唶不可解，我心安得如石頑。"]', '["藍田十月雪塞关，我兴南望愁羣山。","攢天嵬嵬凍相映，君乃寄命於其间。","秩卑俸薄食口衆，豈有酒食开容顏。","殿前羣公賜食罷，驊騮蹋路驕且闲。","稱多量少鑒裁密，豈念幽桂遺榛菅。","幾欲犯嚴出薦口，氣象硉兀未可攀。","归来殞涕揜关臥，心之紛亂誰能刪。","诗翁憔悴斸荒棘，清玉刻佩聯玦环。","腦脂遮眼臥壯士，大弨挂壁無由彎。","乾坤惠施万物遂，独於數子懷偏慳。","朝欷暮唶不可解，我心安得如石頑。"]', '诗', 'shi', '', NULL, '雪後寄崔二十六丞公 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd18d6f-fdeb-4e04-94f0-24722019866f', '送僧澄觀', '送僧澄观', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["浮屠西來何施爲，擾擾四海爭奔馳。","構樓架閣切星漢，誇雄鬬麗止者誰。","僧伽後出淮泗上，勢到衆佛尤恢奇。","越商胡賈脫身罪，珪璧滿船寧計資。","清淮無波平如席，欄柱傾扶半天赤。","火燒水轉掃地空，突兀便高三百尺。","影沈潭底龍驚遁，當晝無雲跨虛碧。","借問經營本何人，道人澄觀名籍籍。","愈昔從軍大梁下，往來滿屋賢豪者。","皆言澄觀雖僧徒，公才吏用當今無。","後從徐州辟書至，紛紛過客何由記。","人言澄觀乃詩人，一座競吟詩句新。","向風長歎不可見，我欲收歛加冠巾。","洛陽窮秋厭窮獨，丁丁啄門疑啄木。","有僧來訪呼使前，伏犀插腦高頰權。","惜哉已老無所及，坐睨神骨空潸然。","臨淮太守初到郡，遠遣州民送音問。","好奇賞俊直難逢，去去爲致思從容。"]', '["浮屠西来何施爲，擾擾四海爭奔驰。","構楼架閣切星漢，誇雄鬬丽止者誰。","僧伽後出淮泗上，勢到衆佛尤恢奇。","越商胡賈脫身罪，珪璧满船寧計資。","清淮無波平如席，欄柱傾扶半天赤。","火燒水轉掃地空，突兀便高三百尺。","影沈潭底龙驚遁，當晝無云跨虛碧。","借问經營本何人，道人澄观名籍籍。","愈昔從軍大梁下，往来满屋賢豪者。","皆言澄观雖僧徒，公才吏用當今無。","後從徐州辟书至，紛紛過客何由記。","人言澄观乃诗人，一座競吟诗句新。","向风长歎不可见，我欲收歛加冠巾。","洛陽窮秋厭窮独，丁丁啄门疑啄木。","有僧来訪呼使前，伏犀插腦高頰權。","惜哉已老無所及，坐睨神骨空潸然。","臨淮太守初到郡，远遣州民送音问。","好奇賞俊直难逢，去去爲致思從容。"]', '诗', 'shi', '', NULL, '送僧澄觀 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70eca4ac-4132-4c1c-a72d-7237eb0a5288', '山南鄭相公樊員外酬答爲詩其末咸有見及語樊封以示愈依賦十四韻以獻', '山南鄭相公樊員外酬答爲诗其末咸有见及語樊封以示愈依賦十四韻以獻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["梁維西南屏，山厲水刻屈。","稟生肖剿剛，難諧在民物。","滎公鼎軸老，烹斡力健倔。","帝咨女予往，牙纛前岔坲。","威風挾惠氣，蓋壤兩劘拂。","茫漫華黑間，指畫變怳歘。","誠既富而美，章彙霍炳蔚。","日延講大訓，龜判錯衮黻。","樊子坐賓署，演孔刮老佛。","金舂撼玉應，厥臭劇蕙鬱。","遺我一言重，跽受惕齋慄。","辭慳義卓闊，呀豁疚掊掘。","如新去耵聹，雷霆逼颶䫻。","綴此豈爲訓，俚言紹莊屈。"]', '["梁維西南屏，山厲水刻屈。","稟生肖剿剛，难諧在民物。","滎公鼎軸老，烹斡力健倔。","帝咨女予往，牙纛前岔坲。","威风挾惠氣，蓋壤兩劘拂。","茫漫华黑间，指畫变怳歘。","誠既富而美，章彙霍炳蔚。","日延講大訓，龟判錯衮黻。","樊子坐賓署，演孔刮老佛。","金舂撼玉應，厥臭劇蕙鬱。","遺我一言重，跽受惕斋慄。","辞慳義卓闊，呀豁疚掊掘。","如新去耵聹，雷霆逼颶䫻。","綴此豈爲訓，俚言紹莊屈。"]', '诗', 'shi', '', NULL, '山南鄭相公樊員外酬答爲詩其末咸有見及語樊封以示愈依賦十四韻以獻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97782c86-fb89-436b-a76f-934bc872acb0', '奉和武相公鎮蜀時詠使宅韋太尉所養孔雀', '奉和武相公鎮蜀时詠使宅韋太尉所養孔雀', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["穆穆鸞鳳友，何年來止茲。","飄零失故態，隔絕抱長思。","翠角高獨聳，金華煥相差。","坐蒙恩顧重，畢命守堦墀。"]', '["穆穆鸾鳳友，何年来止茲。","飄零失故態，隔絕抱长思。","翠角高独聳，金华煥相差。","坐蒙恩顧重，畢命守堦墀。"]', '诗', 'shi', '', NULL, '奉和武相公鎮蜀時詠使宅韋太尉所養孔雀 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fc910c-a0e0-4c8b-af3a-1bba24f25e71', '感春三首 一', '感春三首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["偶坐藤樹下，暮春下旬間。","藤陰已可庇，落蘂還漫漫。","亹亹新葉大，瓏瓏晚花乾。","青天高寥寥，兩蝶飛翻翻。","時節適當爾，懷悲自無端。"]', '["偶坐藤樹下，暮春下旬间。","藤陰已可庇，落蘂還漫漫。","亹亹新葉大，瓏瓏晚花乾。","青天高寥寥，兩蝶飞翻翻。","时節適當爾，懷悲自無端。"]', '诗', 'shi', '', NULL, '感春三首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94a17f7-e838-45a8-a08d-8ee9f80237d6', '感春三首 二', '感春三首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["黃黃蕪菁花，桃李事已退。","狂風簸枯榆，狼籍九衢內。","春序一如此，汝顏安足賴。","誰能駕飛車，相從觀海外。"]', '["黄黄蕪菁花，桃李事已退。","狂风簸枯榆，狼籍九衢內。","春序一如此，汝顏安足賴。","誰能駕飞车，相從观海外。"]', '诗', 'shi', '', NULL, '感春三首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056b0cfb-aaa2-462d-8e22-61b6b4c92b5a', '感春三首 三', '感春三首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["晨遊百花林，朱朱兼白白。","柳枝弱而細，懸樹垂百尺。","左右同來人，金紫貴顯劇。","嬌童爲我歌，哀響跨箏笛。","豔姬蹋筵舞，清眸刺劒戟。","心懷平生友，莫一在燕席。","死者長眇芒，生者困乖隔。","少年真可喜，老大百無益。"]', '["晨游百花林，朱朱兼白白。","柳枝弱而細，懸樹垂百尺。","左右同来人，金紫貴显劇。","嬌童爲我歌，哀响跨箏笛。","豔姬蹋筵舞，清眸刺劒戟。","心懷平生友，莫一在燕席。","死者长眇芒，生者困乖隔。","少年真可喜，老大百無益。"]', '诗', 'shi', '', NULL, '感春三首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d54e31f-b5b7-462a-b9d0-17d45f49ac5a', '早赴街西行香贈盧李二中舍人', '早赴街西行香贈盧李二中舍人', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天街東西異，祗命遂成遊。","月明御溝曉，蟬吟堤樹秋。","老僧情不薄，僻寺境還幽。","寂寥二三子，歸騎得相收。"]', '["天街东西異，祗命遂成游。","月明御溝晓，蟬吟堤樹秋。","老僧情不薄，僻寺境還幽。","寂寥二三子，归騎得相收。"]', '诗', 'shi', '', NULL, '早赴街西行香贈盧李二中舍人 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab50975-6bf6-4537-ace4-a28f46037462', '晚寄張十八助敎周郎博士', '晚寄張十八助敎周郎博士', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["日薄風景曠，出歸偃前簷。","晴雲如擘絮，新月似磨鐮。","田野興偶動，衣冠情久厭。","吾生可攜手，歎息歲將淹。"]', '["日薄风景曠，出归偃前簷。","晴云如擘絮，新月似磨鐮。","田野兴偶动，衣冠情久厭。","吾生可携手，歎息歲將淹。"]', '诗', 'shi', '', NULL, '晚寄張十八助敎周郎博士 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b869632-0dcf-4e3c-98f5-291aaa1b3884', '題張十八所居', '題張十八所居', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["君居泥溝上，溝濁萍青青。","蛙讙橋未掃，蟬嘒門長扃。","名秩後千品，詩文齊六經。","端來問奇字，爲我講聲形。"]', '["君居泥溝上，溝濁萍青青。","蛙讙橋未掃，蟬嘒门长扃。","名秩後千品，诗文齊六經。","端来问奇字，爲我講声形。"]', '诗', 'shi', '', NULL, '題張十八所居 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6bf25ce-19e9-4316-bd35-cdc6bb050c61', '奉酬盧給事雲夫四兄曲江荷花行見寄幷呈上錢七兄閣老張十八助敎', '奉酬盧給事云夫四兄曲江荷花行见寄幷呈上錢七兄閣老張十八助敎', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["曲江千頃秋波淨，平鋪紅雲蓋明鏡。","大明宮中給事歸，走馬來看立不正。","遺我明珠九十六，寒光映骨睡驪目。","我今官閑得婆娑，問言何處芙蓉多。","撐舟昆明度雲錦，脚敲兩舷呌吳歌。","太白山高三百里，負雪崔嵬插花裏。","玉山前却不復來，曲江汀瀅水平盃。","我時相思不覺一回首，天門九扇相當開。","上界真人足官府，豈如散仙鞭笞鸞鳳終日相追陪。"]', '["曲江千頃秋波淨，平鋪紅云蓋明镜。","大明宮中給事归，走马来看立不正。","遺我明珠九十六，寒光映骨睡驪目。","我今官闲得婆娑，问言何处芙蓉多。","撐舟昆明度云錦，脚敲兩舷呌吳歌。","太白山高三百里，負雪崔嵬插花裏。","玉山前却不复来，曲江汀瀅水平盃。","我时相思不覺一回首，天门九扇相當开。","上界真人足官府，豈如散仙鞭笞鸾鳳終日相追陪。"]', '诗', 'shi', '', NULL, '奉酬盧給事雲夫四兄曲江荷花行見寄幷呈上錢七兄閣老張十八助敎 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f3a223-3b9a-4163-8814-78733007a6b9', '奉和錢七兄曹長盆池所植', '奉和錢七兄曹长盆池所植', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["翻翻江浦荷，而今生在此。","擢擢菰葉長，芳根復誰徙。","露涵兩鮮翠，風蕩相磨倚。","但取主人知，誰言盆盎是。"]', '["翻翻江浦荷，而今生在此。","擢擢菰葉长，芳根复誰徙。","露涵兩鲜翠，风蕩相磨倚。","但取主人知，誰言盆盎是。"]', '诗', 'shi', '', NULL, '奉和錢七兄曹長盆池所植 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453424e2-ef15-4710-956b-3ec491c17ec1', '記夢', '記梦', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["夜夢神官與我言，羅縷道妙角與根。","挈攜陬維口瀾翻，百二十刻須臾間。","我聽其言未云足，捨我先度橫山腹。","我徒三人共追之，一人前度安不危。","我亦平行蹋𠿕𧇠，神完骨蹻脚不掉。","側身上視溪谷盲，杖撞玉版聲彭𦨻。","神官見我開顏笑，前對一人壯非少。","石壇坡陀可坐臥，我手承頦肘拄座。","隆樓傑閣磊嵬高，天風飄飄吹我過。","壯非少者哦七言，六字常語一字難。","我以指撮白玉丹，行且咀噍行詰盤。","口前截斷第二句，綽虐顧我顏不歡。","乃知仙人未賢聖，護短憑愚邀我敬。","我能屈曲自世間，安能從汝巢神山。"]', '["夜梦神官與我言，羅縷道妙角與根。","挈携陬維口瀾翻，百二十刻須臾间。","我听其言未云足，捨我先度橫山腹。","我徒三人共追之，一人前度安不危。","我亦平行蹋𠿕𧇠，神完骨蹻脚不掉。","側身上視溪谷盲，杖撞玉版声彭𦨻。","神官见我开顏笑，前对一人壯非少。","石壇坡陀可坐臥，我手承頦肘拄座。","隆楼傑閣磊嵬高，天风飄飄吹我過。","壯非少者哦七言，六字常語一字难。","我以指撮白玉丹，行且咀噍行詰盤。","口前截斷第二句，綽虐顧我顏不歡。","乃知仙人未賢聖，護短憑愚邀我敬。","我能屈曲自世间，安能從汝巢神山。"]', '诗', 'shi', '', NULL, '記夢 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfed685-daa4-41cd-85cf-6cb3dd9a7a02', '南內朝賀歸呈同官', '南內朝賀归呈同官', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["薄雲蔽秋曦，清雨不成泥。","罷賀南內衙，歸涼曉淒淒。","綠槐十二街，渙散馳輪蹄。","余惟戇書生，孤身無所齎。","三黜竟不去，致官九列齊。","豈惟一身榮，佩玉冠簪犀。","滉蕩天門高，著籍朝厥妻。","文才不如人，行又無町畦。","問之朝廷事，略不知東西。","況於經籍深，豈究端與倪。","君恩太山重，不見酬稗稊。","所職事無多，又不自提撕。","明庭集孔鸞，曷取於鳧鷖。","樹以松與柏，不宜間蒿藜。","婉孌自媚好，幾時不見擠。","貪食以忘軀，尠不調鹽醯。","法吏多少年，磨淬出角圭。","將舉汝愆尤，以爲己階梯。","收身歸關東，期不到死迷。"]', '["薄云蔽秋曦，清雨不成泥。","罷賀南內衙，归涼晓淒淒。","綠槐十二街，渙散驰輪蹄。","余惟戇书生，孤身無所齎。","三黜竟不去，致官九列齊。","豈惟一身榮，佩玉冠簪犀。","滉蕩天门高，著籍朝厥妻。","文才不如人，行又無町畦。","问之朝廷事，略不知东西。","況於經籍深，豈究端與倪。","君恩太山重，不见酬稗稊。","所職事無多，又不自提撕。","明庭集孔鸾，曷取於鳧鷖。","樹以松與柏，不宜间蒿藜。","婉孌自媚好，幾时不见擠。","貪食以忘軀，尠不調鹽醯。","法吏多少年，磨淬出角圭。","將舉汝愆尤，以爲己階梯。","收身归关东，期不到死迷。"]', '诗', 'shi', '', NULL, '南內朝賀歸呈同官 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee85ef6-fa41-4448-b06d-15dc3ccdcc76', '朝歸', '朝归', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["峩峩進賢冠，耿耿水蒼佩。","服章豈不好，不與德相對。","顧影聽其聲，赬顏汗漸背。","進乏犬雞效，又不勇自退。","坐食取其肥，無堪等聾瞶。","長風吹天墟，秋日萬里曬。","抵暮但昏眠，不成歌慷慨。"]', '["峩峩進賢冠，耿耿水蒼佩。","服章豈不好，不與德相对。","顧影听其声，赬顏汗漸背。","進乏犬雞效，又不勇自退。","坐食取其肥，無堪等聾瞶。","长风吹天墟，秋日万里曬。","抵暮但昏眠，不成歌慷慨。"]', '诗', 'shi', '', NULL, '朝歸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c79a46-c520-4e2d-ac07-bab0b16c0685', '雜詩四首 一', '杂诗四首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["朝蠅不須驅，暮蚊不可拍。","蠅蚊滿八區，可盡與相格。","得時能幾時，與汝恣啖咋。","涼風九月到，掃不見蹤跡。"]', '["朝蠅不須驱，暮蚊不可拍。","蠅蚊满八區，可尽與相格。","得时能幾时，與汝恣啖咋。","涼风九月到，掃不见蹤跡。"]', '诗', 'shi', '', NULL, '雜詩四首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb17101-1f54-4814-b625-6870432ced12', '雜詩四首 二', '杂诗四首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["鵲鳴聲楂楂，烏噪聲擭擭。","爭鬬庭宇間，持身博彈射。","黃鵠能忍飢，兩翅久不擘。","蒼蒼雲海路，歲晚將無獲。"]', '["鵲鳴声楂楂，烏噪声擭擭。","爭鬬庭宇间，持身博彈射。","黄鵠能忍飢，兩翅久不擘。","蒼蒼云海路，歲晚將無獲。"]', '诗', 'shi', '', NULL, '雜詩四首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0425716c-30c2-4fa6-9b52-0ac8078a0f69', '雜詩四首 三', '杂诗四首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["截橑爲欂櫨，斵楹以爲椽。","束蒿以代之，小大不相權。","雖無風雨災，得不覆且顛。","解轡棄騏麟，蹇驢鞭使前。","崑崙高萬里，歲盡道苦邅。","停車臥輪下，絕意於神僊。"]', '["截橑爲欂櫨，斵楹以爲椽。","束蒿以代之，小大不相權。","雖無风雨災，得不覆且顛。","解轡棄騏麟，蹇驢鞭使前。","崑崙高万里，歲尽道苦邅。","停车臥輪下，絕意於神僊。"]', '诗', 'shi', '', NULL, '雜詩四首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6062fcb5-fc32-4697-b068-783cd0d2797b', '雜詩四首 四', '杂诗四首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雀鳴朝營食，鳩鳴暮覓羣。","獨有知時鶴，雖鳴不緣身。","喑蟬終不鳴，有抱不列陳。","蛙黽鳴無謂，閤閤祗亂人。"]', '["雀鳴朝營食，鳩鳴暮覓羣。","独有知时鹤，雖鳴不緣身。","喑蟬終不鳴，有抱不列陳。","蛙黽鳴無謂，閤閤祗亂人。"]', '诗', 'shi', '', NULL, '雜詩四首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531a437b-02ea-4c51-b84f-d8ed49d83fce', '讀東方朔雜事', '读东方朔杂事', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["嚴嚴王母宮，下維萬仙家。","噫欠爲飄風，濯手大雨沱。","方朔乃豎子，驕不加禁訶。","偷入雷電室，輷輘掉狂車。","王母聞以笑，衛官助呀呀。","不知萬萬人，生身埋泥沙。","簸頓五山踣，流漂八維蹉。","曰吾兒可憎，奈此狡獪何。","方朔聞不喜，褫身絡蛟蛇。","瞻相北斗柄，兩手自相挼。","羣仙急乃言，百犯庸不科。","向觀睥睨處，事在不可赦。","欲不布露言，外口實諠譁。","王母不得已，顏嚬口齎嗟。","頷頭可其奏，送以紫玉珂。","方朔不懲創，挾恩更矜誇。","詆欺劉天子，正晝溺殿衙。","一旦不辭訣，攝身凌蒼霞。"]', '["嚴嚴王母宮，下維万仙家。","噫欠爲飄风，濯手大雨沱。","方朔乃豎子，驕不加禁訶。","偷入雷電室，輷輘掉狂车。","王母闻以笑，衛官助呀呀。","不知万万人，生身埋泥沙。","簸頓五山踣，流漂八維蹉。","曰吾兒可憎，奈此狡獪何。","方朔闻不喜，褫身絡蛟蛇。","瞻相北斗柄，兩手自相挼。","羣仙急乃言，百犯庸不科。","向观睥睨处，事在不可赦。","欲不布露言，外口實諠譁。","王母不得已，顏嚬口齎嗟。","頷头可其奏，送以紫玉珂。","方朔不懲創，挾恩更矜誇。","詆欺劉天子，正晝溺殿衙。","一旦不辞訣，攝身凌蒼霞。"]', '诗', 'shi', '', NULL, '讀東方朔雜事 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e04e92f-e561-401b-b645-d7da15568455', '譴瘧鬼', '譴瘧鬼', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["屑屑水帝魂，謝謝無餘輝。","如何不肖子，尚奮瘧鬼威。","乘秋作寒熱，翁嫗所駡譏。","求食歐泄間，不知臭穢非。","醫師加百毒，熏灌無停機。","灸師施艾炷，酷若獵火圍。","詛師毒口牙，舌作霹靂飛。","符師弄刀筆，丹墨交橫揮。","咨汝之胄出，門戶何巍巍。","祖軒而父頊，未沫於前徽。","不修其操行，賤薄似汝稀。","豈不忝厥祖，靦然不知歸。","湛湛江水情，歸居安汝妃。","清波爲裳衣，白石爲門畿。","呼吸明月光，手掉芙蓉旂。","降集隨九歌，飲芳而食菲。","贈汝以好辭，咄汝去莫違。"]', '["屑屑水帝魂，謝謝無餘輝。","如何不肖子，尚奮瘧鬼威。","乘秋作寒熱，翁嫗所駡譏。","求食歐泄间，不知臭穢非。","醫師加百毒，熏灌無停機。","灸師施艾炷，酷若獵火圍。","詛師毒口牙，舌作霹靂飞。","符師弄刀笔，丹墨交橫揮。","咨汝之胄出，门戶何巍巍。","祖軒而父頊，未沫於前徽。","不修其操行，賤薄似汝稀。","豈不忝厥祖，靦然不知归。","湛湛江水情，归居安汝妃。","清波爲裳衣，白石爲门畿。","呼吸明月光，手掉芙蓉旂。","降集隨九歌，饮芳而食菲。","贈汝以好辞，咄汝去莫違。"]', '诗', 'shi', '', NULL, '譴瘧鬼 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5895afcc-89a8-45f5-8257-3275ef3650d5', '示兒', '示兒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["始我來京師，止攜一束書。","辛勤三十年，以有此屋廬。","此屋豈爲華，於我自有餘。","中堂高且新，四時登牢蔬。","前榮饌賓親，冠婚之所於。","庭內無所有，高樹八九株。","有藤婁絡之，春華夏陰敷。","東堂坐見山，雲風相吹噓。","松果連南亭，外有瓜芋區。","西偏屋不多，槐榆翳空虛。","山鳥旦夕鳴，有類澗谷居。","主婦治北堂，膳服適戚疎。","恩封高平君，子孫從朝裾。","開門問誰來，無非卿大夫。","不知官高卑，玉帶懸金魚。","問客之所爲，峨冠講唐虞。","酒食罷無爲，棋槊以相娛。","凡此座中人，十九持鈞樞。","又問誰與頻，莫與張樊如。","來過亦無事，考評道精麤。","躚躚媚學子，牆屏日有徒。","以能問不能，其蔽豈可祛。","嗟我不修飾，事與庸人俱。","安能坐如此，比肩於朝儒。","詩以示兒曹，其無迷厥初。"]', '["始我来京師，止携一束书。","辛勤三十年，以有此屋廬。","此屋豈爲华，於我自有餘。","中堂高且新，四时登牢蔬。","前榮饌賓親，冠婚之所於。","庭內無所有，高樹八九株。","有藤婁絡之，春华夏陰敷。","东堂坐见山，云风相吹噓。","松果連南亭，外有瓜芋區。","西偏屋不多，槐榆翳空虛。","山鸟旦夕鳴，有類澗谷居。","主婦治北堂，膳服適戚疎。","恩封高平君，子孫從朝裾。","开门问誰来，無非卿大夫。","不知官高卑，玉带懸金鱼。","问客之所爲，峨冠講唐虞。","酒食罷無爲，棋槊以相娛。","凡此座中人，十九持鈞樞。","又问誰與頻，莫與張樊如。","来過亦無事，考評道精麤。","躚躚媚学子，牆屏日有徒。","以能问不能，其蔽豈可祛。","嗟我不修飾，事與庸人俱。","安能坐如此，比肩於朝儒。","诗以示兒曹，其無迷厥初。"]', '诗', 'shi', '', NULL, '示兒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f8e660-83be-456f-ae80-1afcc0cf63aa', '庭楸', '庭楸', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["庭楸止五株，共生十步間。","各有藤繞之，上各相鈎聯。","下葉各垂地，樹顛各雲連。","朝日出其東，我常坐西偏。","夕日在其西，我常坐東邊。","當晝日在上，我在中央間。","仰視何青青，上不見纖穿。","朝暮無日時，我且八九旋。","濯濯晨露香，明珠何聯聯。","夜月來照之，蒨蒨自生煙。","我已自頑鈍，重遭五楸牽。","客來尚不見，肯到權門前。","權門衆所趨，有客動百千。","九牛亡一毛，未在多少間。","往既無可顧，不往自可憐。"]', '["庭楸止五株，共生十步间。","各有藤繞之，上各相鈎聯。","下葉各垂地，樹顛各云連。","朝日出其东，我常坐西偏。","夕日在其西，我常坐东邊。","當晝日在上，我在中央间。","仰視何青青，上不见纖穿。","朝暮無日时，我且八九旋。","濯濯晨露香，明珠何聯聯。","夜月来照之，蒨蒨自生煙。","我已自頑鈍，重遭五楸牽。","客来尚不见，肯到權门前。","權门衆所趨，有客动百千。","九牛亡一毛，未在多少间。","往既無可顧，不往自可怜。"]', '诗', 'shi', '', NULL, '庭楸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d00831-5661-4ff2-894f-cd0f4951d6ba', '翫月喜張十八員外以王六秘書至', '翫月喜張十八員外以王六秘书至', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["前夕雖十五，月長未滿規。","君來晤我時，風露渺無涯。","浮雲散白石，天宇開青池。","孤質不自憚，中天爲君施。","翫翫夜遂久，亭亭曙將披。","況當今夕圓，又以嘉客隨。","惜無酒食樂，但用歌嘲爲。"]', '["前夕雖十五，月长未满規。","君来晤我时，风露渺無涯。","浮云散白石，天宇开青池。","孤質不自憚，中天爲君施。","翫翫夜遂久，亭亭曙將披。","況當今夕圓，又以嘉客隨。","惜無酒食乐，但用歌嘲爲。"]', '诗', 'shi', '', NULL, '翫月喜張十八員外以王六秘書至 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4434d99-ee2d-44b9-b4cb-99cb535043f1', '和李相公攝事南郊覽物興懷呈一二知舊', '和李相公攝事南郊覽物兴懷呈一二知旧', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["燦燦辰角曙，亭亭寒露朝。","川原共澄暎，雲日還浮飄。","上宰嚴祀事，清途振華鑣。","圓丘峻且坦，前對南山標。","村樹黃復綠，中田稼何饒。","顧瞻想巖谷，興歎倦塵囂。","惟彼顛瞑者，去公豈不遼。","爲仁朝自治，用靜兵以銷。","勿憚吐捉勤，可歌風雨調。","聖賢相遇少，功德今宣昭。"]', '["燦燦辰角曙，亭亭寒露朝。","川原共澄暎，云日還浮飄。","上宰嚴祀事，清途振华鑣。","圓丘峻且坦，前对南山標。","村樹黄复綠，中田稼何饒。","顧瞻想巖谷，兴歎倦塵囂。","惟彼顛瞑者，去公豈不遼。","爲仁朝自治，用静兵以銷。","勿憚吐捉勤，可歌风雨調。","聖賢相遇少，功德今宣昭。"]', '诗', 'shi', '', NULL, '和李相公攝事南郊覽物興懷呈一二知舊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d2c2e6-b8a4-4b02-b837-8101ecde8dfd', '和裴僕射相公假山十一韻', '和裴僕射相公假山十一韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["公乎真愛山，看山旦連夕。","猶嫌山在眼，不得着脚歷。","枉語山中人，匄我澗側石。","有來應公須，歸必載金帛。","當軒乍駢羅，隨勢忽開坼。","有洞若神剜，有巖類天劃。","終朝巖洞間，歌鼓燕賓戚。","孰謂衡霍期，近在王侯宅。","傅氏築已卑，磻溪釣何激。","逍遙功德下，不與事相摭。","樂我盛明朝，於焉傲今昔。"]', '["公乎真愛山，看山旦連夕。","猶嫌山在眼，不得着脚歷。","枉語山中人，匄我澗側石。","有来應公須，归必載金帛。","當軒乍駢羅，隨勢忽开坼。","有洞若神剜，有巖類天劃。","終朝巖洞间，歌鼓燕賓戚。","孰謂衡霍期，近在王侯宅。","傅氏築已卑，磻溪釣何激。","逍遙功德下，不與事相摭。","乐我盛明朝，於焉傲今昔。"]', '诗', 'shi', '', NULL, '和裴僕射相公假山十一韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82c880fc-b1f4-4249-997d-6710c1bd016c', '與張十八同效阮步兵一日復一夕', '與張十八同效阮步兵一日复一夕', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["一日復一日，一朝復一朝。","秖見有不如，不見有所超。","食作前日味，事作前日調。","不知久不死，憫憫尚誰要。","富貴自縶拘，貧賤亦煎焦。","俯仰未得所，一世已解鑣。","譬如籠中鶴，六翮無所搖。","譬如兔得蹄，安用東西跳。","還看古人書，復舉前人瓢。","未知所究竟，且作新詩謠。"]', '["一日复一日，一朝复一朝。","秖见有不如，不见有所超。","食作前日味，事作前日調。","不知久不死，憫憫尚誰要。","富貴自縶拘，貧賤亦煎焦。","俯仰未得所，一世已解鑣。","譬如籠中鹤，六翮無所搖。","譬如兔得蹄，安用东西跳。","還看古人书，复舉前人瓢。","未知所究竟，且作新诗謠。"]', '诗', 'shi', '', NULL, '與張十八同效阮步兵一日復一夕 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77c54d5-4723-40c8-bc09-d88eb1ff6aa9', '送諸葛覺往隨州讀書', '送諸葛覺往隨州读书', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["鄴侯家多書，插架三萬軸。","一一懸牙籤，新若手未觸。","爲人強記覽，過眼不再讀。","偉哉羣聖文，磊落載其腹。","行年五十餘，出守數已六。","京邑有舊廬，不容久食宿。","臺閣多官員，無地寄一足。","我雖官在朝，氣勢日局縮。","屢爲丞相言，雖懇不見錄。","送行過滻水，東望不轉目。","今子從之遊，學問得所欲。","入海觀龍魚，矯翮逐黃鵠。","勉爲新詩章，月寄三四幅。"]', '["鄴侯家多书，插架三万軸。","一一懸牙籤，新若手未觸。","爲人強記覽，過眼不再读。","偉哉羣聖文，磊落載其腹。","行年五十餘，出守數已六。","京邑有旧廬，不容久食宿。","台閣多官員，無地寄一足。","我雖官在朝，氣勢日局縮。","屢爲丞相言，雖懇不见錄。","送行過滻水，东望不轉目。","今子從之游，学问得所欲。","入海观龙鱼，矯翮逐黄鵠。","勉爲新诗章，月寄三四幅。"]', '诗', 'shi', '', NULL, '送諸葛覺往隨州讀書 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee595e38-1cc8-4833-bcae-8bea127dcd6f', '南溪始泛三首 一', '南溪始泛三首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["榜舟南山下，上上不得返。","幽事隨去多，孰能量近遠。","陰沈過連樹，藏昂抵橫坂。","石麤肆磨礪，波惡厭牽挽。","或倚偏岸漁，竟就平洲飯。","點點暮雨飄，梢梢新月偃。","餘年懍無幾，休日愴已晚。","自是病使然，非由取高蹇。"]', '["榜舟南山下，上上不得返。","幽事隨去多，孰能量近远。","陰沈過連樹，藏昂抵橫坂。","石麤肆磨礪，波惡厭牽挽。","或倚偏岸漁，竟就平洲飯。","点点暮雨飄，梢梢新月偃。","餘年懍無幾，休日愴已晚。","自是病使然，非由取高蹇。"]', '诗', 'shi', '', NULL, '南溪始泛三首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96480f47-9e04-41f4-865a-b836875cd349', '南溪始泛三首 二', '南溪始泛三首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南溪亦清駛，而無檝與舟。","山農驚見之，隨我觀不休。","不惟兒童輩，或有杖白頭。","饋我籠中瓜，勸我此淹留。","我云以病歸，此已頗自由。","幸有用餘俸，置居在西疇。","囷倉米穀滿，未有旦夕憂。","上去無得得，下來亦悠悠。","但恐煩里閭，時有緩急投。","願爲同社人，雞豚燕春秋。"]', '["南溪亦清駛，而無檝與舟。","山農驚见之，隨我观不休。","不惟兒童輩，或有杖白头。","饋我籠中瓜，勸我此淹留。","我云以病归，此已頗自由。","幸有用餘俸，置居在西疇。","囷倉米穀满，未有旦夕憂。","上去無得得，下来亦悠悠。","但恐煩里閭，时有緩急投。","願爲同社人，雞豚燕春秋。"]', '诗', 'shi', '', NULL, '南溪始泛三首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc1fab1-a86c-4c8d-af6a-292ee64aa7cb', '南溪始泛三首 三', '南溪始泛三首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["足弱不能步，自宜收朝蹟。","羸形可輿致，佳觀安事擲。","即此南坂下，久聞有水石。","拕舟入其間，溪流正清激。","隨波吾未能，峻瀨乍可刺。","鷺起若導吾，前飛數十尺。","亭亭柳帶沙，團團松冠壁。","歸時還盡夜，誰謂非事役。"]', '["足弱不能步，自宜收朝蹟。","羸形可輿致，佳观安事擲。","即此南坂下，久闻有水石。","拕舟入其间，溪流正清激。","隨波吾未能，峻瀨乍可刺。","鷺起若導吾，前飞數十尺。","亭亭柳带沙，團團松冠壁。","归时還尽夜，誰謂非事役。"]', '诗', 'shi', '', NULL, '南溪始泛三首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1e1ecd-b0e5-4527-8ecf-7188263e4d17', '題楚昭王廟', '題楚昭王廟', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["丘墳滿目衣冠盡，城闕連雲草樹荒。","猶有國人懷舊德，一間茅屋祭昭王。"]', '["丘墳满目衣冠尽，城闕連云草樹荒。","猶有国人懷旧德，一间茅屋祭昭王。"]', '诗', 'shi', '', NULL, '題楚昭王廟 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a10340-8b18-4b35-850d-ee23d7d2bd58', '宿龍宮灘', '宿龙宮灘', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["浩浩復湯湯，灘聲抑更揚。","奔流疑激電，驚浪似浮霜。","夢覺燈生暈，宵殘雨送涼。","如何連曉語，一半是思鄉。"]', '["浩浩复湯湯，灘声抑更揚。","奔流疑激電，驚浪似浮霜。","梦覺灯生暈，宵殘雨送涼。","如何連晓語，一半是思乡。"]', '诗', 'shi', '', NULL, '宿龍宮灘 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4236e09-94df-410d-aa17-b0d27cf0205e', '叉魚招張功曹', '叉鱼招張功曹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["叉魚春岸闊，此興在中宵。","大炬然如晝，長船縛似橋。","深窺沙可數，靜搒水無搖。","刃下那能脫，波間或自跳。","中鱗憐錦碎，當目訝珠銷。","迷火逃翻近，驚人去暫遙。","競多心轉細，得雋語時囂。","潭罄知存寡，舷平覺獲饒。","交頭疑湊餌，駢首類同條。","濡沫情雖密，登門事已遼。","盈車欺故事，飼犬驗今朝。","血浪凝猶沸，腥風遠更飄。","蓋江烟羃羃，拂棹影寥寥。","獺去愁無食，龍疑懼見燒。","如棠名既誤，釣渭日徒消。","文客驚先賦，篙工喜盡謠。","膾成思我友，觀樂憶吾僚。","自可捐憂累，何須強問鴞。"]', '["叉鱼春岸闊，此兴在中宵。","大炬然如晝，长船縛似橋。","深窺沙可數，静搒水無搖。","刃下那能脫，波间或自跳。","中鱗怜錦碎，當目訝珠銷。","迷火逃翻近，驚人去暫遙。","競多心轉細，得雋語时囂。","潭罄知存寡，舷平覺獲饒。","交头疑湊餌，駢首類同條。","濡沫情雖密，登门事已遼。","盈车欺故事，飼犬驗今朝。","血浪凝猶沸，腥风远更飄。","蓋江烟羃羃，拂棹影寥寥。","獺去愁無食，龙疑懼见燒。","如棠名既誤，釣渭日徒消。","文客驚先賦，篙工喜尽謠。","膾成思我友，观乐憶吾僚。","自可捐憂累，何須強问鴞。"]', '诗', 'shi', '', NULL, '叉魚招張功曹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c6556c5-ba74-473a-bb42-8fd55ade03b7', '李員外寄紙筆', '李員外寄紙笔', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["題是臨池後，分從起草餘。","兔尖針莫竝，繭淨雪難如。","莫怪殷勤謝，虞卿正著書。"]', '["題是臨池後，分從起草餘。","兔尖針莫竝，繭淨雪难如。","莫怪殷勤謝，虞卿正著书。"]', '诗', 'shi', '', NULL, '李員外寄紙筆 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9463fb8-d058-46d4-b14d-3cc1fe7337e7', '次同冠峽', '次同冠峽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["今日是何朝，天晴物色饒。","落英千尺墮，遊絲百丈飄。","泄乳交巖脉，懸流揭浪標。","無心思嶺北，猿鳥莫相撩。"]', '["今日是何朝，天晴物色饒。","落英千尺墮，游絲百丈飄。","泄乳交巖脉，懸流揭浪標。","無心思嶺北，猿鸟莫相撩。"]', '诗', 'shi', '', NULL, '次同冠峽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccb03d7-ae6f-4103-b4f3-e3b4f5c9e0b7', '答張十一功曹', '答張十一功曹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["山淨江空水見沙，哀猿啼處兩三家。","篔簹競長纖纖笋，躑躅閑開豔豔花。","未報恩波知死所，莫令炎瘴送生涯。","吟君詩罷看雙鬢，斗覺霜毛一半加。"]', '["山淨江空水见沙，哀猿啼处兩三家。","篔簹競长纖纖笋，躑躅闲开豔豔花。","未報恩波知死所，莫令炎瘴送生涯。","吟君诗罷看雙鬢，斗覺霜毛一半加。"]', '诗', 'shi', '', NULL, '答張十一功曹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf84775-3042-4ba1-964b-ab007504cf40', '郴州祈雨', '郴州祈雨', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["乞雨女郎魂，炰羞潔且繁。","廟開鼯鼠呌，神降越巫言。","旱氣期銷蕩，陰官想駿奔。","行看五馬入，蕭颯已隨軒。"]', '["乞雨女郎魂，炰羞潔且繁。","廟开鼯鼠呌，神降越巫言。","旱氣期銷蕩，陰官想駿奔。","行看五马入，蕭颯已隨軒。"]', '诗', 'shi', '', NULL, '郴州祈雨 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('783d570a-44b7-4d2e-82db-e6891538cd95', '湘中酬張十一功曹', '湘中酬張十一功曹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["休垂絕徼千行淚，共泛清湘一葉舟。","今日嶺猿兼越鳥，可憐同聽不知愁。"]', '["休垂絕徼千行泪，共泛清湘一葉舟。","今日嶺猿兼越鸟，可怜同听不知愁。"]', '诗', 'shi', '', NULL, '湘中酬張十一功曹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bf3efe-f55e-4ce4-babc-52bf38529b3e', '郴口又贈二首 一', '郴口又贈二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["山作劍攢江寫鏡，扁舟斗轉疾於飛。","回頭笑向張公子，終日思歸此日歸。"]', '["山作劍攢江寫镜，扁舟斗轉疾於飞。","回头笑向張公子，終日思归此日归。"]', '诗', 'shi', '', NULL, '郴口又贈二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a4a6ca-5a49-4fff-ac07-7e7e4e888fa3', '郴口又贈二首 二', '郴口又贈二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雪颭霜翻看不分，雷驚電激語難聞。","沿涯宛轉到深處，何限青天無片雲。"]', '["雪颭霜翻看不分，雷驚電激語难闻。","沿涯宛轉到深处，何限青天無片云。"]', '诗', 'shi', '', NULL, '郴口又贈二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61c8f59-fdd9-4c00-a75a-078c83959088', '題木居士二首 一', '題木居士二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["火透波穿不計春，根如頭面榦如身。","偶然題作木居士，便有無窮求福人。"]', '["火透波穿不計春，根如头面榦如身。","偶然題作木居士，便有無窮求福人。"]', '诗', 'shi', '', NULL, '題木居士二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf16b1e2-b2fd-4b7e-9431-3df231c95038', '題木居士二首 二', '題木居士二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["爲神詎比溝中斷，遇賞還同爨下餘。","朽蠹不勝刀鋸力，匠人雖巧欲何如。"]', '["爲神詎比溝中斷，遇賞還同爨下餘。","朽蠹不勝刀鋸力，匠人雖巧欲何如。"]', '诗', 'shi', '', NULL, '題木居士二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52478b93-6c8a-4b4e-80f1-6eebb40437cf', '晚泊江口', '晚泊江口', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["郡城朝解纜，江岸暮依村。","二女竹上淚，孤臣水底魂。","雙雙歸蜇燕，一一呌羣猿。","回首那聞語，空看別袖翻。"]', '["郡城朝解纜，江岸暮依村。","二女竹上泪，孤臣水底魂。","雙雙归蜇燕，一一呌羣猿。","回首那闻語，空看別袖翻。"]', '诗', 'shi', '', NULL, '晚泊江口 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('923e2f27-fc95-4649-9442-1aeeb083da91', '湘中', '湘中', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["猿愁魚踊水翻波，自古流傳是汨羅。","蘋藻滿盤無處奠，空聞漁父扣舷歌。"]', '["猿愁鱼踊水翻波，自古流傳是汨羅。","蘋藻满盤無处奠，空闻漁父扣舷歌。"]', '诗', 'shi', '', NULL, '湘中 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1bb2a42-9bb2-4c22-b16e-f86ac22a1a37', '別盈上人', '別盈上人', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["山僧愛山出無期，俗士牽俗來何時。","祝融峰下一回首，即是此生長別離。"]', '["山僧愛山出無期，俗士牽俗来何时。","祝融峰下一回首，即是此生长別離。"]', '诗', 'shi', '', NULL, '別盈上人 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6838a513-72e8-47ce-a665-273205ad5e8d', '喜雪獻裴尚書', '喜雪獻裴尚书', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["宿雲寒不卷，春雪墮如簁。","騁巧先投隙，潛光半入池。","喜深將策試，驚密仰簷窺。","自下何曾汙，增高未覺危。","比心明可燭，拂面愛還吹。","妬舞時飄袖，欺梅併壓枝。","地空迷界限，砌滿接高卑。","浩蕩乾坤合，霏微物象移。","爲祥矜大熟，布澤荷平施。","已分年華晚，猶憐曙色隨。","氣嚴當酒換，灑急聽窗知。","照曜臨初日，玲瓏滴晚澌。","聚庭看嶽聳，掃路見雲披。","陣勢魚麗遠，書文鳥篆奇。","縱歡羅豔黠，列賀擁熊螭。","履敝行偏冷，門扃臥更羸。","悲嘶聞病馬，浪走信嬌兒。","竈靜愁煙絕，絲繁念鬢衰。","擬鹽吟舊句，授簡慕前規。","捧贈同燕石，多慚失所宜。"]', '["宿云寒不卷，春雪墮如簁。","騁巧先投隙，潛光半入池。","喜深將策試，驚密仰簷窺。","自下何曾汙，增高未覺危。","比心明可燭，拂面愛還吹。","妬舞时飄袖，欺梅併壓枝。","地空迷界限，砌满接高卑。","浩蕩乾坤合，霏微物象移。","爲祥矜大熟，布澤荷平施。","已分年华晚，猶怜曙色隨。","氣嚴當酒換，灑急听窗知。","照曜臨初日，玲瓏滴晚澌。","聚庭看嶽聳，掃路见云披。","陣勢鱼丽远，书文鸟篆奇。","縱歡羅豔黠，列賀擁熊螭。","履敝行偏冷，门扃臥更羸。","悲嘶闻病马，浪走信嬌兒。","竈静愁煙絕，絲繁念鬢衰。","擬鹽吟旧句，授簡慕前規。","捧贈同燕石，多慚失所宜。"]', '诗', 'shi', '', NULL, '喜雪獻裴尚書 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af69bb7c-cfa9-4cfa-a341-d59331b53a2c', '春雪', '春雪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["看雪乘清旦，無人坐獨謠。","拂花輕尚起，落地煖初銷。","已訝陵歌扇，還來伴舞腰。","灑篁留密節，著柳送長條。","入鏡鸞窺沼，行天馬度橋。","徧堦憐可掬，滿樹戲成搖。","江浪迎濤日，風毛縱獵朝。","弄閑時細轉，爭急[忽]驚飄。","城險疑懸布，砧寒未擣綃。","莫愁陰景促，夜色自相饒。"]', '["看雪乘清旦，無人坐独謠。","拂花轻尚起，落地煖初銷。","已訝陵歌扇，還来伴舞腰。","灑篁留密節，著柳送长條。","入镜鸾窺沼，行天马度橋。","徧堦怜可掬，满樹戲成搖。","江浪迎濤日，风毛縱獵朝。","弄闲时細轉，爭急[忽]驚飄。","城險疑懸布，砧寒未擣綃。","莫愁陰景促，夜色自相饒。"]', '诗', 'shi', '', NULL, '春雪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cfff02d-2c43-4e77-867a-2d5101a05cc5', '聞梨花發贈劉師命', '闻梨花發贈劉師命', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["桃溪惆悵不能過，紅豔紛紛落地多。","聞道郭西千樹雪，欲將君去醉如何。"]', '["桃溪惆悵不能過，紅豔紛紛落地多。","闻道郭西千樹雪，欲將君去醉如何。"]', '诗', 'shi', '', NULL, '聞梨花發贈劉師命 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b13e5da-48ea-4213-9ede-dd8cec48c7c3', '春雪間早梅', '春雪间早梅', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["梅將雪共春，彩豔不相因。","逐吹能爭密，排枝巧妬新。","誰令香滿座，獨使淨無塵。","芳意饒呈瑞，寒光助照人。","𤫩瓏開已徧，點綴坐來頻。","那是俱疑似，須知兩逼真。","熒煌初亂眼，浩蕩忽迷神。","未許瓊華比，從將玉樹親。","先期迎獻歲，更伴占茲晨。","願得長輝暎，輕微敢自珍。"]', '["梅將雪共春，彩豔不相因。","逐吹能爭密，排枝巧妬新。","誰令香满座，独使淨無塵。","芳意饒呈瑞，寒光助照人。","𤫩瓏开已徧，点綴坐来頻。","那是俱疑似，須知兩逼真。","熒煌初亂眼，浩蕩忽迷神。","未許瓊华比，從將玉樹親。","先期迎獻歲，更伴占茲晨。","願得长輝暎，轻微敢自珍。"]', '诗', 'shi', '', NULL, '春雪間早梅 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0ce25a-d4e2-4338-8fa7-903aa92e6872', '早春雪中聞鶯', '早春雪中闻鶯', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["朝鶯雪裏新，雪樹眼前春。","帶澀先迎氣，侵寒已報人。","共矜初聽早，誰貴後聞頻。","暫囀那成曲，孤鳴豈及辰。","風霜徒自保，桃李詎相親。","寄謝幽棲友，辛勤不爲身。"]', '["朝鶯雪裏新，雪樹眼前春。","带澀先迎氣，侵寒已報人。","共矜初听早，誰貴後闻頻。","暫囀那成曲，孤鳴豈及辰。","风霜徒自保，桃李詎相親。","寄謝幽棲友，辛勤不爲身。"]', '诗', 'shi', '', NULL, '早春雪中聞鶯 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb3ec18-ec62-47b5-a65b-448018743e43', '梨花下贈劉師命', '梨花下贈劉師命', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["洛陽城外清明節，百花寥落梨花發。","今日相逢瘴海頭，共驚爛漫開正月。"]', '["洛陽城外清明節，百花寥落梨花發。","今日相逢瘴海头，共驚爛漫开正月。"]', '诗', 'shi', '', NULL, '梨花下贈劉師命 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34780f4c-c222-41ea-86f4-ed0869a20970', '和歸工部送僧約', '和归工部送僧約', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["早知皆是自拘囚，不學因循到白頭。","汝既出家還擾擾，何人更得死前休。"]', '["早知皆是自拘囚，不学因循到白头。","汝既出家還擾擾，何人更得死前休。"]', '诗', 'shi', '', NULL, '和歸工部送僧約 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe226f7b-e057-4298-b7d2-ba5a27feb1cf', '入關詠馬', '入关詠马', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["歲老豈能充上駟，力微當自慎前程。","不知何故翻驤首，牽過關門妄一鳴。"]', '["歲老豈能充上駟，力微當自慎前程。","不知何故翻驤首，牽過关门妄一鳴。"]', '诗', 'shi', '', NULL, '入關詠馬 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddc2755-a080-41e0-a99d-7d9399dd98ff', '木芙蓉', '木芙蓉', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["新開寒露叢，遠比水間紅。","豔色寧相妬，嘉名偶自同。","採江官渡晚，搴木古祠空。","願得勤來看，無令便逐風。"]', '["新开寒露叢，远比水间紅。","豔色寧相妬，嘉名偶自同。","採江官渡晚，搴木古祠空。","願得勤来看，無令便逐风。"]', '诗', 'shi', '', NULL, '木芙蓉 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4b06ea-a08a-4b6d-b09e-abba3ffa3db0', '題張十一旅舍三詠 榴花', '題張十一旅舍三詠 榴花', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["五月榴花照眼明，枝間時見子初成。","可憐此地無車馬，顛倒青苔落絳英。"]', '["五月榴花照眼明，枝间时见子初成。","可怜此地無车马，顛倒青苔落絳英。"]', '诗', 'shi', '', NULL, '題張十一旅舍三詠 榴花 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a0367f4-2ab9-4100-89f1-693f825b1809', '題張十一旅舍三詠 井', '題張十一旅舍三詠 井', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["賈誼宅中今始見，葛洪山下昔曾窺。","寒泉百尺空看影，正是行人渴死時。"]', '["賈誼宅中今始见，葛洪山下昔曾窺。","寒泉百尺空看影，正是行人渴死时。"]', '诗', 'shi', '', NULL, '題張十一旅舍三詠 井 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a80c62cf-8e3b-4f89-9476-d7273ea5dfa7', '題張十一旅舍三詠 蒲萄', '題張十一旅舍三詠 蒲萄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["新莖未徧半猶枯，高架支離倒復扶。","若欲滿盤堆馬乳，莫辭添竹引龍鬚。"]', '["新莖未徧半猶枯，高架支離倒复扶。","若欲满盤堆马乳，莫辞添竹引龙鬚。"]', '诗', 'shi', '', NULL, '題張十一旅舍三詠 蒲萄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8685806-6dd3-4162-8a41-2ac6ce62727d', '峽石西泉', '峽石西泉', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["居然鱗介不能容，石眼環環水一鍾。","聞說旱時求得雨，秖疑科斗是蛟龍。"]', '["居然鱗介不能容，石眼环环水一鍾。","闻说旱时求得雨，秖疑科斗是蛟龙。"]', '诗', 'shi', '', NULL, '峽石西泉 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949dc32c-20b2-48e4-959c-7db9910de93d', '梁國惠康公主挽歌二首 一', '梁国惠康公主挽歌二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["定諡芳聲遠，移封大國新。","巽宮尊長女，台室屬良人。","河漢重泉夜，梧桐半樹春。","龍[轜]非厭翟，還輾禁城塵。"]', '["定諡芳声远，移封大国新。","巽宮尊长女，台室屬良人。","河漢重泉夜，梧桐半樹春。","龙[轜]非厭翟，還輾禁城塵。"]', '诗', 'shi', '', NULL, '梁國惠康公主挽歌二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a07dcc-02d2-4188-902c-2f759d63f7ce', '梁國惠康公主挽歌二首 二', '梁国惠康公主挽歌二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秦地吹簫女，湘波鼓瑟妃。","佩蘭初應夢，奔月竟淪輝。","夫族迎魂去，宮官會葬歸。","從今沁園草，無復更芳菲。"]', '["秦地吹簫女，湘波鼓瑟妃。","佩蘭初應梦，奔月竟淪輝。","夫族迎魂去，宮官會葬归。","從今沁园草，無复更芳菲。"]', '诗', 'shi', '', NULL, '梁國惠康公主挽歌二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72c7a3d-05f3-4e87-bc13-b303d6756ef7', '和崔舍人詠月二十韻', '和崔舍人詠月二十韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["三秋端正月，今夜出東溟。","對日猶分勢，騰天漸吐靈。","未高烝遠氣，半上霽孤形。","赫奕當躔次，虛徐度杳冥。","長河晴散霧，列宿曙分螢。","浩蕩英華溢，蕭疎物象泠。","池邊臨倒照，簷際送橫經。","花樹參差見，臯禽斷續聆。","牖光窺寂寞，砧影伴娉婷。","幽坐看侵戶，閑吟愛滿庭。","輝斜通壁練，彩碎射沙星。","清潔雲間路，空涼水上亭。","淨堪分顧兔，細得數飄萍。","山翠相凝綠，林煙共冪青。","過隅驚桂側，當午覺輪停。","屬思摛霞錦，追歡罄縹缾。","郡樓何處望，隴笛此時聽。","右掖連台座，重門限禁扃。","風臺觀滉瀁，冰砌步青熒。","獨有虞庠客，無由拾落蓂。"]', '["三秋端正月，今夜出东溟。","对日猶分勢，腾天漸吐靈。","未高烝远氣，半上霽孤形。","赫奕當躔次，虛徐度杳冥。","长河晴散霧，列宿曙分螢。","浩蕩英华溢，蕭疎物象泠。","池邊臨倒照，簷際送橫經。","花樹參差见，臯禽斷續聆。","牖光窺寂寞，砧影伴娉婷。","幽坐看侵戶，闲吟愛满庭。","輝斜通壁練，彩碎射沙星。","清潔云间路，空涼水上亭。","淨堪分顧兔，細得數飄萍。","山翠相凝綠，林煙共冪青。","過隅驚桂側，當午覺輪停。","屬思摛霞錦，追歡罄縹缾。","郡楼何处望，隴笛此时听。","右掖連台座，重门限禁扃。","风台观滉瀁，冰砌步青熒。","独有虞庠客，無由拾落蓂。"]', '诗', 'shi', '', NULL, '和崔舍人詠月二十韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e56f04e5-09b6-49df-a7df-d67658a5d2e2', '詠雪贈張籍', '詠雪贈張籍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["只見縱橫落，寧知遠近來。","飄颻還自弄，歷亂竟誰催。","座暖銷那怪，池清失可猜。","坳中初蓋成，垤處遂成堆。","慢有先居後，輕多去却回。","度前鋪瓦隴，發本積牆隈。","穿細時雙透，乘危忽半摧。","舞深逢坎井，集早值層臺。","砧練終宜擣，階紈未暇裁。","城寒裝睥睨，樹凍裹莓苔。","片片勻如翦，紛紛碎若挼。","定非燖鵠鷺，真是屑瓊瑰。","緯繣觀朝萼，冥茫矚晚埃。","當窗恒凜凜，出戶即皚皚。","壓野榮芝菌，傾都委貨財。","娥嬉華蕩瀁，胥怒浪崔嵬。","磧迥疑浮地，雲平想輾雷。","隨車翻縞帶，逐馬散銀桮。","萬屋漫汗合，千株照曜開。","松篁遭搓抑，糞壤獲饒培。","隔絕門庭遽，擠排陛級纔。","豈堪裨嶽鎮，強欲效鹽梅。","隱匿瑕疵盡，包羅委瑣該。","誤雞宵呃喔，驚雀暗裴回。","浩浩過三暮，悠悠帀九垓。","鯨鯢陸死骨，玉石火炎灰。","厚慮填溟壑，高愁㨖斗魁。","日輪埋欲側，坤軸壓將頹。","岸類長蛇攪，陵猶巨象豗。","水官夸傑黠，木氣怯胚胎。","著地無由卷，連天不易推。","龍魚冷蟄苦，虎豹餓號哀。","巧借奢華便，專繩困約災。","威貪陵布被，光肯離金罍。","賞翫捐他事，歌謠放我才。","狂敎詩硉矹，興與酒陪鰓。","惟子能諳耳，諸人得語哉。","助留風作黨，勸坐火爲媒。","雕刻文刀利，搜求智網恢。","莫煩相屬和，傳示及提孩。"]', '["只见縱橫落，寧知远近来。","飄颻還自弄，歷亂竟誰催。","座暖銷那怪，池清失可猜。","坳中初蓋成，垤处遂成堆。","慢有先居後，轻多去却回。","度前鋪瓦隴，發本積牆隈。","穿細时雙透，乘危忽半摧。","舞深逢坎井，集早值層台。","砧練終宜擣，階紈未暇裁。","城寒裝睥睨，樹凍裹莓苔。","片片勻如翦，紛紛碎若挼。","定非燖鵠鷺，真是屑瓊瑰。","緯繣观朝萼，冥茫矚晚埃。","當窗恒凜凜，出戶即皚皚。","壓野榮芝菌，傾都委貨財。","娥嬉华蕩瀁，胥怒浪崔嵬。","磧迥疑浮地，云平想輾雷。","隨车翻縞带，逐马散銀桮。","万屋漫汗合，千株照曜开。","松篁遭搓抑，糞壤獲饒培。","隔絕门庭遽，擠排陛級纔。","豈堪裨嶽鎮，強欲效鹽梅。","隐匿瑕疵尽，包羅委瑣該。","誤雞宵呃喔，驚雀暗裴回。","浩浩過三暮，悠悠帀九垓。","鯨鯢陸死骨，玉石火炎灰。","厚慮填溟壑，高愁㨖斗魁。","日輪埋欲側，坤軸壓將頹。","岸類长蛇攪，陵猶巨象豗。","水官夸傑黠，木氣怯胚胎。","著地無由卷，連天不易推。","龙鱼冷蟄苦，虎豹餓號哀。","巧借奢华便，專繩困約災。","威貪陵布被，光肯離金罍。","賞翫捐他事，歌謠放我才。","狂敎诗硉矹，兴與酒陪鰓。","惟子能諳耳，諸人得語哉。","助留风作黨，勸坐火爲媒。","雕刻文刀利，搜求智網恢。","莫煩相屬和，傳示及提孩。"]', '诗', 'shi', '', NULL, '詠雪贈張籍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ba8902-b105-43de-9d1e-1ce7dc9ecbac', '酬王二十舍人雪中見寄', '酬王二十舍人雪中见寄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["三日柴門擁不開，階平庭滿白皚皚。","今朝蹋作瓊瑤跡，爲有詩從鳳沼來。"]', '["三日柴门擁不开，階平庭满白皚皚。","今朝蹋作瓊瑤跡，爲有诗從鳳沼来。"]', '诗', 'shi', '', NULL, '酬王二十舍人雪中見寄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99bdecd2-e80e-4559-85e7-f9ef036d1f5c', '送侯喜', '送侯喜', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["已作龍鍾後時者，懶於街裏蹋塵埃。","如今便別長官去，直到新年衙日來。"]', '["已作龙鍾後时者，懶於街裏蹋塵埃。","如今便別长官去，直到新年衙日来。"]', '诗', 'shi', '', NULL, '送侯喜 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5e4ab8-9181-4c44-8841-3fa737458123', '學諸進士作精衛銜石填海', '学諸進士作精衛銜石填海', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["鳥有償冤者，終年抱寸誠。","口銜山石細，心望海波平。","渺渺功難見，區區命已輕。","人皆譏造次，我獨賞專精。","豈計休無日，惟應盡此生。","何慙刺客傳，不著報讎名。"]', '["鸟有償冤者，終年抱寸誠。","口銜山石細，心望海波平。","渺渺功难见，區區命已轻。","人皆譏造次，我独賞專精。","豈計休無日，惟應尽此生。","何慙刺客傳，不著報讎名。"]', '诗', 'shi', '', NULL, '學諸進士作精衛銜石填海 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0a08b4-2c3e-4252-9e9e-0afcb4aee945', '奉酬振武胡十二丈大夫', '奉酬振武胡十二丈大夫', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["傾朝共羨寵光頻，半歲遷騰作虎臣。","戎斾暫停辭社樹，里門先下敬鄉人。","橫飛玉盞家山曉，遠蹀金珂塞草春。","自笑平生誇膽氣，不離文字鬢毛新。"]', '["傾朝共羨寵光頻，半歲遷腾作虎臣。","戎斾暫停辞社樹，里门先下敬乡人。","橫飞玉盞家山晓，远蹀金珂塞草春。","自笑平生誇膽氣，不離文字鬢毛新。"]', '诗', 'shi', '', NULL, '奉酬振武胡十二丈大夫 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f0319f-8116-449e-9f70-9076852f4146', '奉和庫部盧四兄曹長元日朝回', '奉和庫部盧四兄曹长元日朝回', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天仗宵嚴建羽旄，春雲送色曉雞號。","金爐香動螭頭暗，玉佩聲來雉尾高。","戎服上趨承北極，儒冠列侍暎東曹。","太平時節難身遇，郎署何須歎二毛。"]', '["天仗宵嚴建羽旄，春云送色晓雞號。","金爐香动螭头暗，玉佩声来雉尾高。","戎服上趨承北極，儒冠列侍暎东曹。","太平时節难身遇，郎署何須歎二毛。"]', '诗', 'shi', '', NULL, '奉和庫部盧四兄曹長元日朝回 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab4f85b4-93fc-4040-85e4-0c28552e2407', '寒食直歸遇雨', '寒食直归遇雨', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["寒食時看度，春遊事已違。","風光連日直，陰雨半朝歸。","不見紅毬上，那論綵索飛。","惟將新賜火，向曙著朝衣。"]', '["寒食时看度，春游事已違。","风光連日直，陰雨半朝归。","不见紅毬上，那論綵索飞。","惟將新賜火，向曙著朝衣。"]', '诗', 'shi', '', NULL, '寒食直歸遇雨 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c5aab1-a57d-492c-b43b-e03b9e1a72fc', '送李六協律歸荆南', '送李六協律归荆南', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["早日羈遊所，春風送客歸。","柳花還漠漠，江燕正飛飛。","歌舞知誰在，賓僚逐使非。","宋亭池水綠，莫忘蹋芳菲。"]', '["早日羈游所，春风送客归。","柳花還漠漠，江燕正飞飞。","歌舞知誰在，賓僚逐使非。","宋亭池水綠，莫忘蹋芳菲。"]', '诗', 'shi', '', NULL, '送李六協律歸荆南 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245660c4-0496-46cf-a7f5-ad6dfffe8db9', '題百葉桃花', '題百葉桃花', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["百葉雙桃晚更紅，窺窗暎竹見玲瓏。","應知侍史歸天上，故伴仙郎宿禁中。"]', '["百葉雙桃晚更紅，窺窗暎竹见玲瓏。","應知侍史归天上，故伴仙郎宿禁中。"]', '诗', 'shi', '', NULL, '題百葉桃花 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c13139-b250-4e7f-a708-3ec87d7be464', '春雪', '春雪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["新年都未有芳華，二月初驚見草芽。","白雪却嫌春色晚，故穿庭樹作飛花。"]', '["新年都未有芳华，二月初驚见草芽。","白雪却嫌春色晚，故穿庭樹作飞花。"]', '诗', 'shi', '', NULL, '春雪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3458aa79-b6e9-4ceb-96de-be31695a8156', '戲題牡丹', '戲題牡丹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["幸自同開俱隱約，何須相倚鬬輕盈。","陵晨併作新妝面，對客偏含不語情。","雙燕無機還拂掠，遊蜂多思正經營。","長年是事皆拋盡，今日欄邊暫眼明。"]', '["幸自同开俱隐約，何須相倚鬬轻盈。","陵晨併作新妝面，对客偏含不語情。","雙燕無機還拂掠，游蜂多思正經營。","长年是事皆拋尽，今日欄邊暫眼明。"]', '诗', 'shi', '', NULL, '戲題牡丹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c5e784-2d4c-4b27-a7f7-e67c23188e2f', '盆池五首 一', '盆池五首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["老翁真個似童兒，汲水埋盆作小池。","一夜青蛙鳴到曉，恰如方口釣魚時。"]', '["老翁真個似童兒，汲水埋盆作小池。","一夜青蛙鳴到晓，恰如方口釣鱼时。"]', '诗', 'shi', '', NULL, '盆池五首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000ed10b-40fb-43ce-be8c-e9809266398e', '盆池五首 二', '盆池五首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["莫道盆池作不成，藕稍初種已齊生。","從今有雨君須記，來聽蕭蕭打葉聲。"]', '["莫道盆池作不成，藕稍初種已齊生。","從今有雨君須記，来听蕭蕭打葉声。"]', '诗', 'shi', '', NULL, '盆池五首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de94c121-1576-46c2-a1e2-2a33b810038c', '盆池五首 三', '盆池五首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["瓦沼晨朝水自清，小蟲無數不知名。","忽然分散無蹤影，惟有魚兒作隊行。"]', '["瓦沼晨朝水自清，小蟲無數不知名。","忽然分散無蹤影，惟有鱼兒作隊行。"]', '诗', 'shi', '', NULL, '盆池五首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e817089-e63f-4174-be73-dc739ddcc6d2', '盆池五首 四', '盆池五首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["泥盆淺小詎成池，夜半青蛙聖得知。","一聽暗來將伴侶，不煩鳴喚鬬[雄雌]。"]', '["泥盆淺小詎成池，夜半青蛙聖得知。","一听暗来將伴侶，不煩鳴喚鬬[雄雌]。"]', '诗', 'shi', '', NULL, '盆池五首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2281075-39aa-469f-9a12-e27b951d2024', '盆池五首 五', '盆池五首 五', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["池光天影共青青，拍岸纔添水數缾。","且待夜深明月去，試看涵泳幾多星。"]', '["池光天影共青青，拍岸纔添水數缾。","且待夜深明月去，試看涵泳幾多星。"]', '诗', 'shi', '', NULL, '盆池五首 五 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c627b6-75cf-493f-b06f-2ed5fef037ad', '芍藥', '芍藥', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["浩態狂香昔未逢，紅燈爍爍綠盤籠。","覺來獨對情驚恐，身在僊宮第幾重。"]', '["浩態狂香昔未逢，紅灯爍爍綠盤籠。","覺来独对情驚恐，身在僊宮第幾重。"]', '诗', 'shi', '', NULL, '芍藥 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e9122d-09b7-4ac7-9f38-d529d486d607', '奉和虢州劉給事使君三堂新題二十一詠 新亭', '奉和虢州劉給事使君三堂新題二十一詠 新亭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["湖上新亭好，公來日出初。","水文浮枕簟，瓦影蔭龜魚。"]', '["湖上新亭好，公来日出初。","水文浮枕簟，瓦影蔭龟鱼。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 新亭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c0a45d-e396-4f44-a68b-9d8eaea52d33', '奉和虢州劉給事使君三堂新題二十一詠 流水', '奉和虢州劉給事使君三堂新題二十一詠 流水', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["汩汩幾時休，從春復到秋。","只言池未滿，池滿強交流。"]', '["汩汩幾时休，從春复到秋。","只言池未满，池满強交流。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 流水 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1575a1-37c9-4f20-8db2-219565b17e43', '奉和虢州劉給事使君三堂新題二十一詠 竹洞', '奉和虢州劉給事使君三堂新題二十一詠 竹洞', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["竹洞何年有，公初斫竹開。","洞門無鎖鑰，俗客不曾來。"]', '["竹洞何年有，公初斫竹开。","洞门無鎖鑰，俗客不曾来。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 竹洞 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a02a224-5cbb-4dd3-bd22-a4fe19ff1fab', '奉和虢州劉給事使君三堂新題二十一詠 月臺', '奉和虢州劉給事使君三堂新題二十一詠 月台', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南館城陰闊，東湖水氣多。","直須臺上看，始奈月明何。"]', '["南館城陰闊，东湖水氣多。","直須台上看，始奈月明何。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 月臺 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70f6084a-95fc-4be3-9c7e-26f03e4ecb1c', '奉和虢州劉給事使君三堂新題二十一詠 渚亭', '奉和虢州劉給事使君三堂新題二十一詠 渚亭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["自有人知處，那無步往蹤。","莫敎安四壁，面面看芙蓉。"]', '["自有人知处，那無步往蹤。","莫敎安四壁，面面看芙蓉。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 渚亭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb1f27f-af8a-4ed5-abd5-22f43cb845eb', '奉和虢州劉給事使君三堂新題二十一詠 竹溪', '奉和虢州劉給事使君三堂新題二十一詠 竹溪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["藹藹溪流慢，梢梢岸篠長。","穿沙碧簳淨，落水紫苞香。"]', '["藹藹溪流慢，梢梢岸篠长。","穿沙碧簳淨，落水紫苞香。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 竹溪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af68a89-61e9-444e-852c-d3e1d66af3e2', '奉和虢州劉給事使君三堂新題二十一詠 北湖', '奉和虢州劉給事使君三堂新題二十一詠 北湖', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["聞說游湖棹，尋常到此回。","應留醒心處，準擬醉時來。"]', '["闻说游湖棹，尋常到此回。","應留醒心处，準擬醉时来。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 北湖 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e37bd22-2e01-4e61-85d5-621ac1941b72', '奉和虢州劉給事使君三堂新題二十一詠 花島', '奉和虢州劉給事使君三堂新題二十一詠 花島', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蜂蝶去紛紛，香風隔岸聞。","欲知花島處，水上覓紅雲。"]', '["蜂蝶去紛紛，香风隔岸闻。","欲知花島处，水上覓紅云。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 花島 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eddc10d2-98b3-4dae-aa00-2683379da11b', '奉和虢州劉給事使君三堂新題二十一詠 柳溪', '奉和虢州劉給事使君三堂新題二十一詠 柳溪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["柳樹誰人種，行行夾岸高。","莫將條繫纜，著處有蟬號。"]', '["柳樹誰人種，行行夾岸高。","莫將條繫纜，著处有蟬號。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 柳溪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a3c4fd-ac69-4084-884b-887df01849f8', '奉和虢州劉給事使君三堂新題二十一詠 西山', '奉和虢州劉給事使君三堂新題二十一詠 西山', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["新月迎宵挂，晴雲到晚留。","爲遮西望眼，終是懶回頭。"]', '["新月迎宵挂，晴云到晚留。","爲遮西望眼，終是懶回头。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 西山 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f8d992-088f-4cdf-bef6-6690f55e6a8f', '奉和虢州劉給事使君三堂新題二十一詠 竹逕', '奉和虢州劉給事使君三堂新題二十一詠 竹逕', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["無塵從不掃，有鳥莫令彈。","若要添風月，應除數百竿。"]', '["無塵從不掃，有鸟莫令彈。","若要添风月，應除數百竿。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 竹逕 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c9f1f6-3a24-489d-a8c9-552711348736', '奉和虢州劉給事使君三堂新題二十一詠 荷池', '奉和虢州劉給事使君三堂新題二十一詠 荷池', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["風雨秋池上，高荷蓋水繁。","未諳鳴摵摵，那似卷翻翻。"]', '["风雨秋池上，高荷蓋水繁。","未諳鳴摵摵，那似卷翻翻。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 荷池 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155414a2-0f3e-4175-a08f-b962868a9be7', '奉和虢州劉給事使君三堂新題二十一詠 稻畦', '奉和虢州劉給事使君三堂新題二十一詠 稻畦', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["罫布畦堪數，枝分水莫尋。","魚肥知已秀，鶴沒覺初深。"]', '["罫布畦堪數，枝分水莫尋。","鱼肥知已秀，鹤沒覺初深。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 稻畦 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4f3148-3d1c-4b37-906d-aac309850c25', '奉和虢州劉給事使君三堂新題二十一詠 柳巷', '奉和虢州劉給事使君三堂新題二十一詠 柳巷', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["柳巷還飛絮，春餘幾許時。","吏人休報事，公作送春詩。"]', '["柳巷還飞絮，春餘幾許时。","吏人休報事，公作送春诗。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 柳巷 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c7f738-6ca4-4131-9662-a8ad13182422', '奉和虢州劉給事使君三堂新題二十一詠 花源', '奉和虢州劉給事使君三堂新題二十一詠 花源', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["源上花初發，公應日日來。","丁寧紅與紫，慎莫一時開。"]', '["源上花初發，公應日日来。","丁寧紅與紫，慎莫一时开。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 花源 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d659f265-3341-4969-862a-5b2ad242572c', '奉和虢州劉給事使君三堂新題二十一詠 北樓', '奉和虢州劉給事使君三堂新題二十一詠 北楼', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["郡樓乘曉上，盡日不能回。","晚色將秋至，長風送月來。"]', '["郡楼乘晓上，尽日不能回。","晚色將秋至，长风送月来。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 北樓 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75abd02e-afa5-4e41-986c-605a46b0a525', '奉和虢州劉給事使君三堂新題二十一詠 鏡潭', '奉和虢州劉給事使君三堂新題二十一詠 镜潭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["非鑄復非鎔，泓澄忽此逢。","魚鰕不用避，只是照蛟龍。"]', '["非鑄复非鎔，泓澄忽此逢。","鱼鰕不用避，只是照蛟龙。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 鏡潭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bdf539-2431-4980-9b85-09ccc6461824', '奉和虢州劉給事使君三堂新題二十一詠 孤嶼', '奉和虢州劉給事使君三堂新題二十一詠 孤嶼', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["朝遊孤嶼南，暮戲孤嶼北。","所以孤嶼鳥，與公盡相識。"]', '["朝游孤嶼南，暮戲孤嶼北。","所以孤嶼鸟，與公尽相識。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 孤嶼 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8d4b7d-45c0-439b-b1e2-b90a284e27a3', '奉和虢州劉給事使君三堂新題二十一詠 方橋', '奉和虢州劉給事使君三堂新題二十一詠 方橋', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["非閣復非船，可居兼可過。","君欲問方橋，方橋如此作。"]', '["非閣复非船，可居兼可過。","君欲问方橋，方橋如此作。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 方橋 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c07e4d69-ad6f-4c4a-a3d7-3bc9f14bf5bf', '奉和虢州劉給事使君三堂新題二十一詠 梯橋', '奉和虢州劉給事使君三堂新題二十一詠 梯橋', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["乍似上青冥，初疑躡菡萏。","自無飛仙骨，欲度何由敢。"]', '["乍似上青冥，初疑躡菡萏。","自無飞仙骨，欲度何由敢。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 梯橋 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a261570a-0dff-4b8e-bf08-cb39c7dcd9ea', '奉和虢州劉給事使君三堂新題二十一詠 月池', '奉和虢州劉給事使君三堂新題二十一詠 月池', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["寒池月下明，新月池邊曲。","若不妒清妍，却成相映燭。"]', '["寒池月下明，新月池邊曲。","若不妒清妍，却成相映燭。"]', '诗', 'shi', '', NULL, '奉和虢州劉給事使君三堂新題二十一詠 月池 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de458634-e334-4c79-9831-e38075501179', '遊城南十六首 賽神', '游城南十六首 賽神', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["白布長衫紫領巾，差科未動是閑人。","麥苗含穟桑生葚，共向田頭樂社神。"]', '["白布长衫紫領巾，差科未动是闲人。","麦苗含穟桑生葚，共向田头乐社神。"]', '诗', 'shi', '', NULL, '遊城南十六首 賽神 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6187a93e-9311-40dd-8243-c0fc9100aa26', '遊城南十六首 題于賓客莊', '游城南十六首 題于賓客莊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["榆莢車前蓋地皮，薔薇蘸水笋穿籬。","馬蹄無入朱門跡，縱使春歸可得知。"]', '["榆莢车前蓋地皮，薔薇蘸水笋穿籬。","马蹄無入朱门跡，縱使春归可得知。"]', '诗', 'shi', '', NULL, '遊城南十六首 題于賓客莊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45415d34-7f13-4fcb-9f66-cf2b5ae980ad', '遊城南十六首 晚春', '游城南十六首 晚春', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["草樹知春不久歸，百般紅紫鬬芳菲。","楊花榆莢無才思，惟解漫天作雪飛。"]', '["草樹知春不久归，百般紅紫鬬芳菲。","楊花榆莢無才思，惟解漫天作雪飞。"]', '诗', 'shi', '', NULL, '遊城南十六首 晚春 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1896dfac-ff83-497b-a90e-79dbf0fb17ca', '遊城南十六首 落花', '游城南十六首 落花', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["已分將身著地飛，那羞踐踏損光暉。","無端又被春風誤，吹落西家不得歸。"]', '["已分將身著地飞，那羞踐踏損光暉。","無端又被春风誤，吹落西家不得归。"]', '诗', 'shi', '', NULL, '遊城南十六首 落花 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f035b6a0-ad2b-4b45-9d29-c24794b5b05e', '遊城南十六首 楸樹二首 一', '游城南十六首 楸樹二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["幾歲生成爲大樹，一朝纏繞困長藤。","誰人與脫青羅帔，看吐高花萬萬層。"]', '["幾歲生成爲大樹，一朝纏繞困长藤。","誰人與脫青羅帔，看吐高花万万層。"]', '诗', 'shi', '', NULL, '遊城南十六首 楸樹二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d231d370-bc57-459b-bc6e-dd5278728d7e', '遊城南十六首 楸樹二首 二', '游城南十六首 楸樹二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["幸自枝條能樹立，可煩蘿蔓作交加。","傍人不解尋根本，却道新花勝舊花。"]', '["幸自枝條能樹立，可煩蘿蔓作交加。","傍人不解尋根本，却道新花勝旧花。"]', '诗', 'shi', '', NULL, '遊城南十六首 楸樹二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12f8b82-814e-45df-87b8-6062b29bd2a4', '遊城南十六首 風折花枝', '游城南十六首 风折花枝', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["浮豔侵天難就看，清香撲地只遙聞。","春風也是多情思，故揀繁枝折贈君。"]', '["浮豔侵天难就看，清香撲地只遙闻。","春风也是多情思，故揀繁枝折贈君。"]', '诗', 'shi', '', NULL, '遊城南十六首 風折花枝 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b3e7672-8d4b-4e9c-9768-82d7b3f5b758', '遊城南十六首 贈同遊', '游城南十六首 贈同游', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["喚起窗全曙，催歸日未西。","無心花裏鳥，更與盡情啼。"]', '["喚起窗全曙，催归日未西。","無心花裏鸟，更與尽情啼。"]', '诗', 'shi', '', NULL, '遊城南十六首 贈同遊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9cb51e-80f1-4766-89f1-20c35e804f3c', '遊城南十六首 贈張十八助敎', '游城南十六首 贈張十八助敎', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["喜君眸子重清朗，攜手城南歷舊遊。","忽見孟生題竹處，相看淚落不能收。"]', '["喜君眸子重清朗，携手城南歷旧游。","忽见孟生題竹处，相看泪落不能收。"]', '诗', 'shi', '', NULL, '遊城南十六首 贈張十八助敎 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf7afde3-6dc5-4fe0-bbb5-893fb5480453', '遊城南十六首 題韋氏莊', '游城南十六首 題韋氏莊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔者誰能比，今來事不同。","寂寥青草曲，散漫白榆風。","架倒藤全落，籬崩竹半空。","寧須惆悵立，翻覆本無窮。"]', '["昔者誰能比，今来事不同。","寂寥青草曲，散漫白榆风。","架倒藤全落，籬崩竹半空。","寧須惆悵立，翻覆本無窮。"]', '诗', 'shi', '', NULL, '遊城南十六首 題韋氏莊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6d23de-73bf-45a4-ac23-ae629b2312f1', '遊城南十六首 晚雨', '游城南十六首 晚雨', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["廉纖晚雨不能晴，池岸草間蚯蚓鳴。","投竿跨馬蹋歸路，纔到城門打鼓聲。"]', '["廉纖晚雨不能晴，池岸草间蚯蚓鳴。","投竿跨马蹋归路，纔到城门打鼓声。"]', '诗', 'shi', '', NULL, '遊城南十六首 晚雨 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be67cbc-90e8-484e-9b43-4cbbf935a398', '遊城南十六首 出城', '游城南十六首 出城', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["暫出城門蹋青草，遠於林下見春山。","應須韋杜家家到，祗有今朝一日閑。"]', '["暫出城门蹋青草，远於林下见春山。","應須韋杜家家到，祗有今朝一日闲。"]', '诗', 'shi', '', NULL, '遊城南十六首 出城 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('966c9bb0-6642-4c60-8183-67eb80ac71a2', '遊城南十六首 把酒', '游城南十六首 把酒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["擾擾馳名者，誰能一日閑。","我來無伴侶，把酒對南山。"]', '["擾擾驰名者，誰能一日闲。","我来無伴侶，把酒对南山。"]', '诗', 'shi', '', NULL, '遊城南十六首 把酒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed678f60-9e43-47f5-aa99-fc476753503e', '遊城南十六首 嘲少年', '游城南十六首 嘲少年', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["直把春償酒，都將命乞花。","祗知閑信馬，不覺誤隨車。"]', '["直把春償酒，都將命乞花。","祗知闲信马，不覺誤隨车。"]', '诗', 'shi', '', NULL, '遊城南十六首 嘲少年 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11185a07-9a7f-4091-a5f3-582b12a3c4ea', '遊城南十六首 楸樹', '游城南十六首 楸樹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["青幢紫蓋立童童，細雨浮煙作綵籠。","不得畫師來貌取，定知難見一生中。"]', '["青幢紫蓋立童童，細雨浮煙作綵籠。","不得畫師来貌取，定知难见一生中。"]', '诗', 'shi', '', NULL, '遊城南十六首 楸樹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd542cb4-430d-4d1b-a085-4eeb4db324e1', '遊城南十六首 遣興', '游城南十六首 遣兴', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["斷送一生惟有酒，尋思百計不如閑。","莫憂世事兼身事，須著人間比夢間。"]', '["斷送一生惟有酒，尋思百計不如闲。","莫憂世事兼身事，須著人间比梦间。"]', '诗', 'shi', '', NULL, '遊城南十六首 遣興 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c802975-63a9-416c-ac3e-cad1d8bb50ab', '送李尚書赴襄陽八韻得長字', '送李尚书赴襄陽八韻得长字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["帝憂南國切，改命付忠良。","壤畫星搖動，旗分獸簸揚。","五營兵轉肅，千里地還方。","控帶荆門遠，飄浮漢水長。","賜書寬屬郡，戰馬隔鄰疆。","縱獵雷霆迅，觀棊玉石忙。","風流峴首客，花豔大堤倡。","富貴由身致，誰敎不自強。"]', '["帝憂南国切，改命付忠良。","壤畫星搖动，旗分獸簸揚。","五營兵轉肅，千里地還方。","控带荆门远，飄浮漢水长。","賜书寬屬郡，戰马隔鄰疆。","縱獵雷霆迅，观棊玉石忙。","风流峴首客，花豔大堤倡。","富貴由身致，誰敎不自強。"]', '诗', 'shi', '', NULL, '送李尚書赴襄陽八韻得長字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b344b4-2f7a-48a0-97b1-50073a9263c8', '和席八十二韻', '和席八十二韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["絳闕銀河曙，東風右掖春。","官隨名共美，花與思俱新。","綺陌朝遊間，綾衾夜直頻。","橫門開日月，高閣切星辰。","庭變寒前草，天銷霽後塵。","溝聲通苑急，柳色壓城勻。","綸綍謀猷盛，丹青步武親。","芳菲含斧藻，光景暢形神。","傍砌看紅藥，巡池詠白蘋。","多情懷酒伴，餘事作詩人。","倚玉難藏拙，吹竽久混真。","坐慙空自老，江海未還身。"]', '["絳闕銀河曙，东风右掖春。","官隨名共美，花與思俱新。","綺陌朝游间，綾衾夜直頻。","橫门开日月，高閣切星辰。","庭变寒前草，天銷霽後塵。","溝声通苑急，柳色壓城勻。","綸綍謀猷盛，丹青步武親。","芳菲含斧藻，光景暢形神。","傍砌看紅藥，巡池詠白蘋。","多情懷酒伴，餘事作诗人。","倚玉难藏拙，吹竽久混真。","坐慙空自老，江海未還身。"]', '诗', 'shi', '', NULL, '和席八十二韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6f9692f-f0d6-4b32-8c0a-3dbbe3bc128a', '和武相公早春聞鶯', '和武相公早春闻鶯', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["早晚飛來入錦城，誰人敎解百般鳴。","春風紅樹驚眠處，似妬歌童作豔聲。"]', '["早晚飞来入錦城，誰人敎解百般鳴。","春风紅樹驚眠处，似妬歌童作豔声。"]', '诗', 'shi', '', NULL, '和武相公早春聞鶯 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b51078-7016-481f-9e1d-977a76361984', '遊太平公主山莊', '游太平公主山莊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["公主當年欲占春，故將臺榭押城闉。","欲知前面花多少，直到南山不屬人。"]', '["公主當年欲占春，故將台榭押城闉。","欲知前面花多少，直到南山不屬人。"]', '诗', 'shi', '', NULL, '遊太平公主山莊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b58be3-ba59-4df2-93a7-899916454dbf', '晚春', '晚春', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["誰收春色將歸去，慢綠妖紅半不存。","榆莢祗能隨柳絮，等閑撩亂走空園。"]', '["誰收春色將归去，慢綠妖紅半不存。","榆莢祗能隨柳絮，等闲撩亂走空园。"]', '诗', 'shi', '', NULL, '晚春 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91981995-3a0f-4aef-844e-288345da7d20', '大行皇太后挽歌詞三首 一', '大行皇太后挽歌词三首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["一紀尊名正，三時孝養榮。","高居朝聖主，厚德載羣生。","武帳虛中禁，玄堂掩太平。","秋天笳鼓歇，松柏徧山鳴。"]', '["一紀尊名正，三时孝養榮。","高居朝聖主，厚德載羣生。","武帳虛中禁，玄堂掩太平。","秋天笳鼓歇，松柏徧山鳴。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334ccae3-b3f8-4489-9d20-daf0cbd2e00a', '大行皇太后挽歌詞三首 二', '大行皇太后挽歌词三首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["威儀備吉凶，文物雜軍容。","配地行新祭，因山託故封。","鳳飛終不返，劒化會相從。","無復臨長樂，空聞報曉鐘。"]', '["威儀備吉凶，文物杂軍容。","配地行新祭，因山託故封。","鳳飞終不返，劒化會相從。","無复臨长乐，空闻報晓鐘。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b334a0c-3897-4322-ba26-20e1f343d730', '大行皇太后挽歌詞三首 三', '大行皇太后挽歌词三首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["追攀萬國來，警衛百神陪。","畫翣登秋殿，容衣入夜臺。","雲隨僊馭遠，風助聖情哀。","只有朝陵日，妝匳一暫開。"]', '["追攀万国来，警衛百神陪。","畫翣登秋殿，容衣入夜台。","云隨僊馭远，风助聖情哀。","只有朝陵日，妝匳一暫开。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cab9c089-686b-400b-b75f-b180869c9c55', '廣宣上人頻見過', '廣宣上人頻见過', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["三百六旬長擾擾，不衝風雨即塵埃。","久慙朝士無裨補，空愧高僧數往來。","學道窮年何所得，吟詩竟日未能廻。","天寒古寺遊人少，紅葉窗前有幾堆。"]', '["三百六旬长擾擾，不衝风雨即塵埃。","久慙朝士無裨補，空愧高僧數往来。","学道窮年何所得，吟诗竟日未能廻。","天寒古寺游人少，紅葉窗前有幾堆。"]', '诗', 'shi', '', NULL, '廣宣上人頻見過 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4cf3bfa-c6c8-4057-b0d0-f23700d69867', '閑遊二首 一', '闲游二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雨後來更好，繞池徧青青。","柳花閑度竹，菱葉故穿萍。","獨坐殊未厭，孤斟詎能醒。","持竿至日暮，幽詠欲誰聽。"]', '["雨後来更好，繞池徧青青。","柳花闲度竹，菱葉故穿萍。","独坐殊未厭，孤斟詎能醒。","持竿至日暮，幽詠欲誰听。"]', '诗', 'shi', '', NULL, '閑遊二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfe15f9-43c2-4d0e-9635-fe2e424cc29a', '閑遊二首 二', '闲游二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["茲遊苦不數，再到遂經旬。","萍蓋汙池淨，藤籠老樹新。","林烏鳴訝客，岸竹長遮鄰。","子雲祗自守，奚事九衢塵。"]', '["茲游苦不數，再到遂經旬。","萍蓋汙池淨，藤籠老樹新。","林烏鳴訝客，岸竹长遮鄰。","子云祗自守，奚事九衢塵。"]', '诗', 'shi', '', NULL, '閑遊二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee654644-02ba-487a-afbe-88c7f6e7bc62', '酬馬侍郎寄酒', '酬马侍郎寄酒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["一壺情所寄，四句意能多。","秋到無詩酒，其如月色何。"]', '["一壺情所寄，四句意能多。","秋到無诗酒，其如月色何。"]', '诗', 'shi', '', NULL, '酬馬侍郎寄酒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da3942e-f4e4-4d45-86de-c93a0fe8f411', '和侯協律詠笋', '和侯協律詠笋', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["竹亭人不到，新笋滿前軒。","乍出真堪賞，初多未覺煩。","成行齊婢僕，環立比兒孫。","驗長常攜尺，愁乾屢側盆。","對吟忘膳飲，偶坐變朝昏。","滯雨膏腴濕，驕陽氣候溫。","得時方張王，挾勢欲騰騫。","見角牛羊沒，看皮虎豹存。","攢生猶有隙，散布忽無垠。","詎可持籌算，誰能以理言。","縱橫公占地，羅列暗連根。","狂劇時穿壁，橫強幾觸藩。","深潛如避逐，遠去若追奔。","始訝妨人路，還驚入藥園。","萌芽防寖大，覆載莫偏恩。","已復侵危砌，非徒出短垣。","身寧虞瓦礫，計擬揜蘭蓀。","且歎高無數，庸知上幾番。","短長終不校，先後竟誰論。","外恨苞藏密，中仍節目繁。","暫須廻步履，要取助盤飧。","穰穰疑翻地，森森競塞門。","戈矛頭戢戢，蛇虺首掀掀。","婦懦咨料揀，兒癡謁盡髠。","侯生來慰我，詩句讀驚魂。","屬和才將竭，呻吟至日暾。"]', '["竹亭人不到，新笋满前軒。","乍出真堪賞，初多未覺煩。","成行齊婢僕，环立比兒孫。","驗长常携尺，愁乾屢側盆。","对吟忘膳饮，偶坐变朝昏。","滯雨膏腴濕，驕陽氣候溫。","得时方張王，挾勢欲腾騫。","见角牛羊沒，看皮虎豹存。","攢生猶有隙，散布忽無垠。","詎可持籌算，誰能以理言。","縱橫公占地，羅列暗連根。","狂劇时穿壁，橫強幾觸藩。","深潛如避逐，远去若追奔。","始訝妨人路，還驚入藥园。","萌芽防寖大，覆載莫偏恩。","已复侵危砌，非徒出短垣。","身寧虞瓦礫，計擬揜蘭蓀。","且歎高無數，庸知上幾番。","短长終不校，先後竟誰論。","外恨苞藏密，中仍節目繁。","暫須廻步履，要取助盤飧。","穰穰疑翻地，森森競塞门。","戈矛头戢戢，蛇虺首掀掀。","婦懦咨料揀，兒癡謁尽髠。","侯生来慰我，诗句读驚魂。","屬和才將竭，呻吟至日暾。"]', '诗', 'shi', '', NULL, '和侯協律詠笋 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446d1d2b-2cc4-4d3e-a1fa-508377745433', '過鴻溝', '過鴻溝', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["龍疲虎困割川原，億萬蒼生性命存。","誰勸君王回馬首，真成一擲賭乾坤。"]', '["龙疲虎困割川原，億万蒼生性命存。","誰勸君王回马首，真成一擲賭乾坤。"]', '诗', 'shi', '', NULL, '過鴻溝 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5be867-3dfd-4c4e-8392-f3e16405658a', '送張侍郎', '送張侍郎', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["司徒東鎮馳書謁，丞相西來走馬迎。","兩府元臣今轉密，一方逋寇不難平。"]', '["司徒东鎮驰书謁，丞相西来走马迎。","兩府元臣今轉密，一方逋寇不难平。"]', '诗', 'shi', '', NULL, '送張侍郎 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e34419-dc6c-41bf-8bf4-b1190d566711', '贈刑部馬侍郎', '贈刑部马侍郎', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["紅旗照海壓南荒，徵入中臺作侍郎。","暫從相公平小寇，便歸天闕致時康。"]', '["紅旗照海壓南荒，徵入中台作侍郎。","暫從相公平小寇，便归天闕致时康。"]', '诗', 'shi', '', NULL, '贈刑部馬侍郎 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e75ff2-c432-48b0-8543-20bcd4b7b3ed', '奉和裴相公東征途經女几山下作', '奉和裴相公东征途經女几山下作', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["旗穿曉日雲霞雜，山倚秋空劍戟明。","敢請相公平賊後，暫攜諸吏上崢嶸。"]', '["旗穿晓日云霞杂，山倚秋空劍戟明。","敢請相公平賊後，暫携諸吏上崢嶸。"]', '诗', 'shi', '', NULL, '奉和裴相公東征途經女几山下作 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c06400-81aa-4f73-be70-8f8426c9345b', '郾城晚飲奉贈副使馬侍郎及馮李二員外', '郾城晚饮奉贈副使马侍郎及馮李二員外', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["城上赤雲呈勝氣，眉間黃色見歸期。","幕中無事惟須飲，即是連鑣向闕時。"]', '["城上赤云呈勝氣，眉间黄色见归期。","幕中無事惟須饮，即是連鑣向闕时。"]', '诗', 'shi', '', NULL, '郾城晚飲奉贈副使馬侍郎及馮李二員外 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0925324-863d-4640-9fd9-3b8674bea909', '酬別留後侍郎', '酬別留後侍郎', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["爲文無出相如右，謀師難居卻縠先。","歸去雪銷溱洧動，西來旌斾拂晴天。"]', '["爲文無出相如右，謀師难居卻縠先。","归去雪銷溱洧动，西来旌斾拂晴天。"]', '诗', 'shi', '', NULL, '酬別留後侍郎 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ded1d1-ed42-47fb-b121-6c82304dfad4', '同李二十八夜次襄城', '同李二十八夜次襄城', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["周楚仍連接，川原乍屈盤。","雲垂天不暖，塵漲雪猶乾。","印綬歸台室，旌旗別將壇。","欲知迎候盛，騎火萬星攢。"]', '["周楚仍連接，川原乍屈盤。","云垂天不暖，塵漲雪猶乾。","印綬归台室，旌旗別將壇。","欲知迎候盛，騎火万星攢。"]', '诗', 'shi', '', NULL, '同李二十八夜次襄城 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c97944-064e-449b-8717-c7d4f0dad847', '同李二十八員外從裴相公野宿西界', '同李二十八員外從裴相公野宿西界', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["四面星辰著地明，散燒煙火宿天兵。","不關破賊須歸奏，自趂新年賀太平。"]', '["四面星辰著地明，散燒煙火宿天兵。","不关破賊須归奏，自趂新年賀太平。"]', '诗', 'shi', '', NULL, '同李二十八員外從裴相公野宿西界 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd38c1b-ca84-48f4-a731-d789a3c95176', '過襄城', '過襄城', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["郾城辭罷過襄城，潁水嵩山刮眼明。","已去蔡州三百里，家人不用遠來迎。"]', '["郾城辞罷過襄城，潁水嵩山刮眼明。","已去蔡州三百里，家人不用远来迎。"]', '诗', 'shi', '', NULL, '過襄城 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b768177b-5a26-4f53-b7e2-d2db2d362cbc', '宿神龜招李二十八馮十七', '宿神龟招李二十八馮十七', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["荒山野水照斜暉，啄雪寒鴉趂始飛。","夜宿驛亭愁不睡，幸來相就蓋征衣。"]', '["荒山野水照斜暉，啄雪寒鴉趂始飞。","夜宿驛亭愁不睡，幸来相就蓋征衣。"]', '诗', 'shi', '', NULL, '宿神龜招李二十八馮十七 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77d3ff20-d7a6-4e36-a7d4-008df44f2503', '次硤石', '次硤石', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["數日方離雪，今朝又出山。","試憑高處望，隱約見潼關。"]', '["數日方離雪，今朝又出山。","試憑高处望，隐約见潼关。"]', '诗', 'shi', '', NULL, '次硤石 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a94e28f-17a5-40a4-a690-b117747d78e4', '和李司勳過連昌宮', '和李司勳過連昌宮', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["夾道疎槐出老根，高甍巨桷壓山原。","宮前遺老來相問，今是開元幾葉孫。"]', '["夾道疎槐出老根，高甍巨桷壓山原。","宮前遺老来相问，今是开元幾葉孫。"]', '诗', 'shi', '', NULL, '和李司勳過連昌宮 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a8fb4e-999a-4497-ae52-40bc78359a58', '次潼關先寄張十二閣老使君', '次潼关先寄張十二閣老使君', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["荆山已去華山來，日出潼關四扇開。","刺史莫辭迎候遠，相公親破蔡州廻。"]', '["荆山已去华山来，日出潼关四扇开。","刺史莫辞迎候远，相公親破蔡州廻。"]', '诗', 'shi', '', NULL, '次潼關先寄張十二閣老使君 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef8452e-67c9-46c4-bd17-8edfd80a7676', '次潼關上都統相公', '次潼关上都統相公', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["暫辭堂印執兵權，盡管諸軍破賊年。","冠蓋相望催入相，待將功德格皇天。"]', '["暫辞堂印執兵權，尽管諸軍破賊年。","冠蓋相望催入相，待將功德格皇天。"]', '诗', 'shi', '', NULL, '次潼關上都統相公 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a154bf-36c4-49cf-8091-105f48c9ec09', '桃林夜賀晉公', '桃林夜賀晉公', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["西來騎火照山紅，夜宿桃林臘月中。","手把命珪兼相印，一時重疊賞元功。"]', '["西来騎火照山紅，夜宿桃林臘月中。","手把命珪兼相印，一时重叠賞元功。"]', '诗', 'shi', '', NULL, '桃林夜賀晉公 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23865eac-df6b-407d-acea-2544745a2611', '送李員外院長分司東都', '送李員外院长分司东都', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["去年秋露下，羇旅逐東征。","今歲春光動，驅馳別上京。","飲中相顧色，送後獨歸情。","兩地無千里，因風數寄聲。"]', '["去年秋露下，羇旅逐东征。","今歲春光动，驱驰別上京。","饮中相顧色，送後独归情。","兩地無千里，因风數寄声。"]', '诗', 'shi', '', NULL, '送李員外院長分司東都 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84de8581-250e-4a4e-9813-868067cc876a', '晉公破賊回重拜台司以詩示幕中賓客愈奉和', '晉公破賊回重拜台司以诗示幕中賓客愈奉和', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南伐旋師太華東，天書夜到冊元功。","將軍舊壓三司貴，相國新兼五等崇。","鵷鷺欲歸仙仗裏，熊羆還入禁營中。","長慙典午非材職，得就閑官即至公。"]', '["南伐旋師太华东，天书夜到冊元功。","將軍旧壓三司貴，相国新兼五等崇。","鵷鷺欲归仙仗裏，熊羆還入禁營中。","长慙典午非材職，得就闲官即至公。"]', '诗', 'shi', '', NULL, '晉公破賊回重拜台司以詩示幕中賓客愈奉和 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96ff7a1f-7b2a-4127-b407-d03cfdcac921', '獨釣四首 一', '独釣四首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["侯家林館勝，偶入得垂竿。","曲樹行藤角，平池散芡盤。","羽沈知食駛，緡細覺牽難。","聊取夸兒女，榆條繫從鞍。"]', '["侯家林館勝，偶入得垂竿。","曲樹行藤角，平池散芡盤。","羽沈知食駛，緡細覺牽难。","聊取夸兒女，榆條繫從鞍。"]', '诗', 'shi', '', NULL, '獨釣四首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b6328c-daa7-4137-bc4c-31789f6291ce', '獨釣四首 二', '独釣四首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["一逕向池斜，池搪野草花。","雨多添柳耳，水長減蒲芽。","坐厭親刑柄，偷來傍釣車。","太平公事少，吏隱詎相賒。"]', '["一逕向池斜，池搪野草花。","雨多添柳耳，水长減蒲芽。","坐厭親刑柄，偷来傍釣车。","太平公事少，吏隐詎相賒。"]', '诗', 'shi', '', NULL, '獨釣四首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddfa020-0ddc-46e9-b99d-df4088a2c418', '獨釣四首 三', '独釣四首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["獨往南塘上，秋晨景氣醒。","露排四岸草，風約半池萍。","鳥下見人寂，魚來聞餌馨。","所嗟無可召，不得倒吾缾。"]', '["独往南塘上，秋晨景氣醒。","露排四岸草，风約半池萍。","鸟下见人寂，鱼来闻餌馨。","所嗟無可召，不得倒吾缾。"]', '诗', 'shi', '', NULL, '獨釣四首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd92446-b46c-42e7-ab23-ce3ff3fe01a4', '獨釣四首 四', '独釣四首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋半百物變，溪魚去不來。","風能坼芡觜，露亦染梨腮。","遠岫重疊出，寒花散亂開。","所期終莫至，日暮與誰廻。"]', '["秋半百物变，溪鱼去不来。","风能坼芡觜，露亦染梨腮。","远岫重叠出，寒花散亂开。","所期終莫至，日暮與誰廻。"]', '诗', 'shi', '', NULL, '獨釣四首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7931bd8a-db01-4e8e-aec3-9fcd1d452798', '枯樹', '枯樹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["老樹無枝葉，風霜不復侵。","腹穿人可過，皮剝蟻還尋。","寄託惟朝菌，依投絕暮禽。","猶堪持改火，未肯但空心。"]', '["老樹無枝葉，风霜不复侵。","腹穿人可過，皮剝蟻還尋。","寄託惟朝菌，依投絕暮禽。","猶堪持改火，未肯但空心。"]', '诗', 'shi', '', NULL, '枯樹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e10c191-80af-40e3-b99b-7b4698c2dd0a', '元日酬蔡州馬十二尚書去年蔡州元日見寄之什', '元日酬蔡州马十二尚书去年蔡州元日见寄之什', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["元日新詩已去年，蔡州遙寄荷相憐。","今朝縱有誰人領，自是三峰不敢眠。"]', '["元日新诗已去年，蔡州遙寄荷相怜。","今朝縱有誰人領，自是三峰不敢眠。"]', '诗', 'shi', '', NULL, '元日酬蔡州馬十二尚書去年蔡州元日見寄之什 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0083cf89-9243-4765-8a97-a147ec34f3dd', '詠燈花同侯十一', '詠灯花同侯十一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["今夕知何夕，花然錦帳中。","自能當雪暖，那肯待春紅。","黃裏排金粟，釵頭綴玉蟲。","更煩將喜事，來報主人公。"]', '["今夕知何夕，花然錦帳中。","自能當雪暖，那肯待春紅。","黄裏排金粟，釵头綴玉蟲。","更煩將喜事，来報主人公。"]', '诗', 'shi', '', NULL, '詠燈花同侯十一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b86d0d78-6f25-4416-a0a5-0616535d4e9f', '祖席前字', '祖席前字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["祖席洛橋邊，親交共黯然。","野晴山簇簇，霜曉菊鮮鮮。","書寄相思處，桮銜欲別前。","淮陽知不薄，終願早廻船。"]', '["祖席洛橋邊，親交共黯然。","野晴山簇簇，霜晓菊鲜鲜。","书寄相思处，桮銜欲別前。","淮陽知不薄，終願早廻船。"]', '诗', 'shi', '', NULL, '祖席前字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231a4c73-c9df-482b-9980-caad78610d31', '秋字', '秋字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["淮南悲木落，而我亦傷秋。","況與故人別，那堪羇宦愁。","榮華今異路，風雨昔同憂。","莫以宜春遠，江山多勝遊。"]', '["淮南悲木落，而我亦傷秋。","況與故人別，那堪羇宦愁。","榮华今異路，风雨昔同憂。","莫以宜春远，江山多勝游。"]', '诗', 'shi', '', NULL, '秋字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eecadce0-6252-4216-aa60-df22b3b6c242', '送鄭尚書赴南海', '送鄭尚书赴南海', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["番禺軍府盛，欲說暫停桮。","蓋海旂幢出，連天觀閣開。","衙時龍戶集，上日馬人來。","風靜鶢鶋去，官廉蚌蛤廻。","貨通師子國，樂奏武王臺。","事事皆殊異，無嫌屈大才。"]', '["番禺軍府盛，欲说暫停桮。","蓋海旂幢出，連天观閣开。","衙时龙戶集，上日马人来。","风静鶢鶋去，官廉蚌蛤廻。","貨通師子国，乐奏武王台。","事事皆殊異，無嫌屈大才。"]', '诗', 'shi', '', NULL, '送鄭尚書赴南海 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b6621a9-58a8-44d1-a365-52e9feb3604f', '答道士寄樹雞', '答道士寄樹雞', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["軟濕青黃狀可猜，欲烹還喚木盤廻。","煩君自入華陽洞，直割乖龍左耳來。"]', '["軟濕青黄狀可猜，欲烹還喚木盤廻。","煩君自入华陽洞，直割乖龙左耳来。"]', '诗', 'shi', '', NULL, '答道士寄樹雞 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861aac3a-3c3d-480c-bdb0-d0c25b7fbf14', '左遷至藍關示姪孫湘', '左遷至藍关示姪孫湘', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["一封朝奏九重天，夕貶潮州路八千。","欲爲聖朝除弊事，肯將衰朽惜殘年。","雲橫秦嶺家何在，雪擁藍關馬不前。","知汝遠來應有意，好收吾骨瘴江邊。"]', '["一封朝奏九重天，夕貶潮州路八千。","欲爲聖朝除弊事，肯將衰朽惜殘年。","云橫秦嶺家何在，雪擁藍关马不前。","知汝远来應有意，好收吾骨瘴江邊。"]', '诗', 'shi', '', NULL, '左遷至藍關示姪孫湘 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e4e3e7-ab3d-4eeb-968c-440e97f99b03', '武關西逢配流吐蕃', '武关西逢配流吐蕃', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["嗟爾戎人莫慘然，湖南地近保生全。","我今罪重無歸望，直去長安路八千。"]', '["嗟爾戎人莫慘然，湖南地近保生全。","我今罪重無归望，直去长安路八千。"]', '诗', 'shi', '', NULL, '武關西逢配流吐蕃 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef12f5c-3640-49fb-9d44-669fb27f6ea5', '次鄧州界', '次鄧州界', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["潮陽南去倍長沙，戀闕那堪又憶家。","心訝愁來惟貯火，眼知別後自添花。","商顏暮雪逢人少，鄧鄙春泥見驛賒。","早晚王師收海嶽，普將雷雨發萌芽。"]', '["潮陽南去倍长沙，戀闕那堪又憶家。","心訝愁来惟貯火，眼知別後自添花。","商顏暮雪逢人少，鄧鄙春泥见驛賒。","早晚王師收海嶽，普將雷雨發萌芽。"]', '诗', 'shi', '', NULL, '次鄧州界 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c56658c-6928-42e3-ba7f-b2098a33453e', '題臨瀧寺', '題臨瀧寺', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["不覺離家已五千，仍將衰病入瀧船。","潮陽未到吾能說，海氣昏昏水拍天。"]', '["不覺離家已五千，仍將衰病入瀧船。","潮陽未到吾能说，海氣昏昏水拍天。"]', '诗', 'shi', '', NULL, '題臨瀧寺 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a501890-4994-4da6-9620-5a6f80f41b8f', '晚次宣溪辱韻州張端公使君惠書敘別酬以絕句二章 一', '晚次宣溪辱韻州張端公使君惠书敘別酬以絕句二章 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["韶州南去接宣溪，雲水蒼茫日向西。","客淚數行先自落，鷓鴣休傍耳邊啼。"]', '["韶州南去接宣溪，云水蒼茫日向西。","客泪數行先自落，鷓鴣休傍耳邊啼。"]', '诗', 'shi', '', NULL, '晚次宣溪辱韻州張端公使君惠書敘別酬以絕句二章 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939ab698-2ed2-4525-8577-45a8179cc842', '晚次宣溪辱韻州張端公使君惠書敘別酬以絕句二章 二', '晚次宣溪辱韻州張端公使君惠书敘別酬以絕句二章 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["兼金那足比清文，百首相隨媿使君。","俱是嶺南巡管內，莫欺荒僻斷知聞。"]', '["兼金那足比清文，百首相隨媿使君。","俱是嶺南巡管內，莫欺荒僻斷知闻。"]', '诗', 'shi', '', NULL, '晚次宣溪辱韻州張端公使君惠書敘別酬以絕句二章 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54b5e5c-f695-4bb7-8484-33650a82a1ab', '題秀禪師房', '題秀禪師房', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["橋夾水松行百步，竹牀莞席到僧家。","暫拳一手支頭臥，還把魚竿下釣沙。"]', '["橋夾水松行百步，竹牀莞席到僧家。","暫拳一手支头臥，還把鱼竿下釣沙。"]', '诗', 'shi', '', NULL, '題秀禪師房 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa73cd3-703f-46cf-9eb5-8f628eb69947', '將至韶州先寄張端公使君借圖經', '將至韶州先寄張端公使君借圖經', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["曲江山水聞來久，恐不知名訪倍難。","願借圖經將入界，每逢佳處便開看。"]', '["曲江山水闻来久，恐不知名訪倍难。","願借圖經將入界，每逢佳处便开看。"]', '诗', 'shi', '', NULL, '將至韶州先寄張端公使君借圖經 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982364ab-2766-490e-8b90-88d9169c2fb5', '過始興江口感懷', '過始兴江口感懷', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["憶作兒童隨伯氏，南來今只一身存。","目前百口還相逐，舊事無人可共論。"]', '["憶作兒童隨伯氏，南来今只一身存。","目前百口還相逐，旧事無人可共論。"]', '诗', 'shi', '', NULL, '過始興江口感懷 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691adfca-49d9-429b-95f1-d23eccc452b4', '韶州留別張端公使君', '韶州留別張端公使君', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["來往再逢梅柳新，別離一醉綺羅春。","久欽江總文才妙，自歎虞翻骨相屯。","鳴笛急吹爭落日，清歌緩送款行人。","已知奏課當徵拜，那復淹留詠白蘋。"]', '["来往再逢梅柳新，別離一醉綺羅春。","久欽江總文才妙，自歎虞翻骨相屯。","鳴笛急吹爭落日，清歌緩送款行人。","已知奏課當徵拜，那复淹留詠白蘋。"]', '诗', 'shi', '', NULL, '韶州留別張端公使君 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db93f1b-e79b-4322-9eef-4714a1b31681', '從潮州量移袁州張韶州端公以詩相賀因酬之', '從潮州量移袁州張韶州端公以诗相賀因酬之', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["明時遠逐事何如，遇赦移官罪未除。","北望詎令隨塞鴈，南遷纔免葬江魚。","將經貴郡煩留客，先惠高文謝起予。","暫欲繫船韶石下，上賓虞舜整冠裾。"]', '["明时远逐事何如，遇赦移官罪未除。","北望詎令隨塞鴈，南遷纔免葬江鱼。","將經貴郡煩留客，先惠高文謝起予。","暫欲繫船韶石下，上賓虞舜整冠裾。"]', '诗', 'shi', '', NULL, '從潮州量移袁州張韶州端公以詩相賀因酬之 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f47b2d-ed9b-456c-9877-908f5f85e7dc', '次石頭驛寄江西王十中丞閣老', '次石头驛寄江西王十中丞閣老', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["憑高試廻首，一望豫章城。","人由戀德泣，馬亦別羣鳴。","寒日夕始照，風江遠漸平。","默然都不語，應識此時情。"]', '["憑高試廻首，一望豫章城。","人由戀德泣，马亦別羣鳴。","寒日夕始照，风江远漸平。","默然都不語，應識此时情。"]', '诗', 'shi', '', NULL, '次石頭驛寄江西王十中丞閣老 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f96ba9-eb8f-4293-9d1a-47bd07855c14', '遊西林寺題蕭二兄郎中舊堂', '游西林寺題蕭二兄郎中旧堂', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["中郎有女能傳業，伯道無兒可保家。","偶到匡山曾住處，幾行衰淚落煙霞。"]', '["中郎有女能傳業，伯道無兒可保家。","偶到匡山曾住处，幾行衰泪落煙霞。"]', '诗', 'shi', '', NULL, '遊西林寺題蕭二兄郎中舊堂 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e8a421-af5d-4785-af7d-443cdbfab7e9', '自袁州還京行次安陸先寄隨州周員外', '自袁州還京行次安陸先寄隨州周員外', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["行行指漢東，暫喜笑言同。","雨雪離江上，蒹葭出夢中。","面猶含瘴色，眼已見華風。","歲暮難相值，酣歌未可終。"]', '["行行指漢东，暫喜笑言同。","雨雪離江上，蒹葭出梦中。","面猶含瘴色，眼已见华风。","歲暮难相值，酣歌未可終。"]', '诗', 'shi', '', NULL, '自袁州還京行次安陸先寄隨州周員外 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d978fb59-bb80-4d6c-a2e0-3beb10b68525', '題廣昌館', '題廣昌館', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["白水龍飛已幾春，偶逢遺跡問耕人。","丘墳發掘當官路，何處南陽有近親。"]', '["白水龙飞已幾春，偶逢遺跡问耕人。","丘墳發掘當官路，何处南陽有近親。"]', '诗', 'shi', '', NULL, '題廣昌館 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57db46c4-7375-4705-ab9e-0c07e71b8cb2', '寄隨州周員外', '寄隨州周員外', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["陸孟丘楊久作塵，同時存者更誰人。","金丹別後知傳得，乞取刀圭救病身。"]', '["陸孟丘楊久作塵，同时存者更誰人。","金丹別後知傳得，乞取刀圭救病身。"]', '诗', 'shi', '', NULL, '寄隨州周員外 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7dc40f-abeb-4bbf-bc8f-6be1b25a4854', '酒中留上襄陽李相公', '酒中留上襄陽李相公', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["濁水汙泥清路塵，還曾同制掌絲綸。","眼穿長訝雙魚斷，耳熱何辭數爵頻。","銀燭未銷窗送曙，金釵半醉座添春。","知公不久歸鈞軸，應許閑官寄病身。"]', '["濁水汙泥清路塵，還曾同制掌絲綸。","眼穿长訝雙鱼斷，耳熱何辞數爵頻。","銀燭未銷窗送曙，金釵半醉座添春。","知公不久归鈞軸，應許闲官寄病身。"]', '诗', 'shi', '', NULL, '酒中留上襄陽李相公 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b7830c-2095-461d-ab54-97dff0c25a20', '去歲自刑部侍郎以罪貶潮州刺史乘驛赴任其後家亦譴逐小女道死殯之層峰驛旁山下蒙恩還朝過其墓留題驛梁', '去歲自刑部侍郎以罪貶潮州刺史乘驛赴任其後家亦譴逐小女道死殯之層峰驛旁山下蒙恩還朝過其墓留題驛梁', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["數條藤束木皮棺，草殯荒山白骨寒。","驚恐入心身已病，扶舁沿路衆知難。","繞墳不暇號三帀，設祭惟聞飯一盤。","致汝無辜由我罪，百年慙痛淚闌干。"]', '["數條藤束木皮棺，草殯荒山白骨寒。","驚恐入心身已病，扶舁沿路衆知难。","繞墳不暇號三帀，設祭惟闻飯一盤。","致汝無辜由我罪，百年慙痛泪闌干。"]', '诗', 'shi', '', NULL, '去歲自刑部侍郎以罪貶潮州刺史乘驛赴任其後家亦譴逐小女道死殯之層峰驛旁山下蒙恩還朝過其墓留題驛梁 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9604f42-9a59-48ac-9978-5c66dce7922d', '賀張十八秘書得裴司空馬', '賀張十八秘书得裴司空马', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["司空遠寄養初成，毛色桃花眼鏡明。","落日已曾交轡語，春風還擬竝鞍行。","長令奴僕知飢渴，須着賢良待性情。","旦夕公歸伸拜謝，免勞騎去逐雙旌。"]', '["司空远寄養初成，毛色桃花眼镜明。","落日已曾交轡語，春风還擬竝鞍行。","长令奴僕知飢渴，須着賢良待性情。","旦夕公归伸拜謝，免勞騎去逐雙旌。"]', '诗', 'shi', '', NULL, '賀張十八秘書得裴司空馬 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94b341b-494b-447d-a668-8bdd9193a338', '杏園送張徹侍御歸使', '杏园送張徹侍御归使', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["東風花樹下，送爾出京城。","久抱傷春意，新添惜別情。","歸來身已病，相見眼還明。","更遣將詩酒，誰家逐後生。"]', '["东风花樹下，送爾出京城。","久抱傷春意，新添惜別情。","归来身已病，相见眼還明。","更遣將诗酒，誰家逐後生。"]', '诗', 'shi', '', NULL, '杏園送張徹侍御歸使 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa54743c-d0e4-4112-893c-ca39716ea2ca', '雨中寄張博士籍侯主簿喜', '雨中寄張博士籍侯主簿喜', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["放朝還不報，半路蹋泥歸。","雨慣曾無節，雷頻自失威。","見牆生菌徧，憂麥作蛾飛。","歲晚偏蕭索，誰當救晉饑。"]', '["放朝還不報，半路蹋泥归。","雨慣曾無節，雷頻自失威。","见牆生菌徧，憂麦作蛾飞。","歲晚偏蕭索，誰當救晉饑。"]', '诗', 'shi', '', NULL, '雨中寄張博士籍侯主簿喜 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795a1848-1768-460c-9ccb-082ee70bb11a', '奉和兵部張侍郎酬鄆州馬尚書祗召途中見寄開緘之日馬帥已再領鄆州之作', '奉和兵部張侍郎酬鄆州马尚书祗召途中见寄开緘之日马帥已再領鄆州之作', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["來朝當路日，承詔改轅時。","再領須句國，仍遷少昊司。","暖風抽宿麥，清雨卷歸旗。","賴寄新珠玉，長吟慰我思。"]', '["来朝當路日，承詔改轅时。","再領須句国，仍遷少昊司。","暖风抽宿麦，清雨卷归旗。","賴寄新珠玉，长吟慰我思。"]', '诗', 'shi', '', NULL, '奉和兵部張侍郎酬鄆州馬尚書祗召途中見寄開緘之日馬帥已再領鄆州之作 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dab9bf3-9d50-404f-a75c-04648fbcb9be', '早春與張十八博士籍遊楊尚書林亭寄第三閣老兼呈白馮二閣老', '早春與張十八博士籍游楊尚书林亭寄第三閣老兼呈白馮二閣老', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["牆下春渠入禁溝，渠冰初破滿渠浮。","鳳池近日長先暖，流到池時更不流。"]', '["牆下春渠入禁溝，渠冰初破满渠浮。","鳳池近日长先暖，流到池时更不流。"]', '诗', 'shi', '', NULL, '早春與張十八博士籍遊楊尚書林亭寄第三閣老兼呈白馮二閣老 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7187c16a-ee57-472a-8a26-5fb3675ed3ed', '奉使常山早次太原呈副使吳郎中', '奉使常山早次太原呈副使吳郎中', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["朗朗聞街鼓，晨起似朝時。","翻翻走驛馬，春盡是歸期。","地失嘉禾處，風存蟋蟀辭。","暮齒良多感，無事涕垂頤。"]', '["朗朗闻街鼓，晨起似朝时。","翻翻走驛马，春尽是归期。","地失嘉禾处，风存蟋蟀辞。","暮齒良多感，無事涕垂頤。"]', '诗', 'shi', '', NULL, '奉使常山早次太原呈副使吳郎中 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd20e8ed-c177-4ea6-b751-1fd9515969a6', '夕次壽陽驛題吳郎中詩後', '夕次壽陽驛題吳郎中诗後', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["風光欲動別長安，春半城邊特地寒。","不見園花兼巷柳，馬頭惟有月團團。"]', '["风光欲动別长安，春半城邊特地寒。","不见园花兼巷柳，马头惟有月團團。"]', '诗', 'shi', '', NULL, '夕次壽陽驛題吳郎中詩後 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c5ec1ac-b70f-44cf-a41e-c5ebf6231b27', '鎮州初歸', '鎮州初归', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["別來楊柳街頭樹，擺弄春風只欲飛。","還有小園桃李在，留花不發待郎歸。"]', '["別来楊柳街头樹，擺弄春风只欲飞。","還有小园桃李在，留花不發待郎归。"]', '诗', 'shi', '', NULL, '鎮州初歸 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ad2115-65fa-4d8f-9d32-008443003d5d', '同水部張員外籍曲江春遊寄白二十二舍人', '同水部張員外籍曲江春游寄白二十二舍人', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["漠漠輕陰晚自開，青天白日映樓臺。","曲江水滿花千樹，有底忙時不肯來。"]', '["漠漠轻陰晚自开，青天白日映楼台。","曲江水满花千樹，有底忙时不肯来。"]', '诗', 'shi', '', NULL, '同水部張員外籍曲江春遊寄白二十二舍人 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7b65471-38e0-4be2-b932-87655d3edbfd', '和水部張員外宣政衙賜百官櫻桃詩', '和水部張員外宣政衙賜百官櫻桃诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["漢家舊種明光殿，炎帝還書本草經。","豈似滿朝承雨露，共看傳賜出青冥。","香隨翠籠擎初到，色暎銀盤寫未停。","食罷自知無所報，空然慙汗仰皇扃。"]', '["漢家旧種明光殿，炎帝還书本草經。","豈似满朝承雨露，共看傳賜出青冥。","香隨翠籠擎初到，色暎銀盤寫未停。","食罷自知無所報，空然慙汗仰皇扃。"]', '诗', 'shi', '', NULL, '和水部張員外宣政衙賜百官櫻桃詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7cb4244-143b-403b-8599-b10c6763d032', '早春呈水部張十八員外二首 一', '早春呈水部張十八員外二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天街小雨潤如酥，草色遙看近却無。","最是一年春好處，絕勝煙柳滿皇都。"]', '["天街小雨潤如酥，草色遙看近却無。","最是一年春好处，絕勝煙柳满皇都。"]', '诗', 'shi', '', NULL, '早春呈水部張十八員外二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e522ba0-45e7-431c-84d0-07342a614318', '早春呈水部張十八員外二首 二', '早春呈水部張十八員外二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["莫道官忙身老大，即無年少逐春心。","憑君先到江頭看，柳色如今深未深。"]', '["莫道官忙身老大，即無年少逐春心。","憑君先到江头看，柳色如今深未深。"]', '诗', 'shi', '', NULL, '早春呈水部張十八員外二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('556900c5-7e75-4b5f-8c52-e32693953396', '送桂州嚴大夫同用南字', '送桂州嚴大夫同用南字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蒼蒼森八桂，茲地在湘南。","江作青羅帶，山如碧玉篸。","戶多輸翠羽，家自種黃甘。","遠勝登僊去，飛鸞不假驂。"]', '["蒼蒼森八桂，茲地在湘南。","江作青羅带，山如碧玉篸。","戶多輸翠羽，家自種黄甘。","远勝登僊去，飞鸾不假驂。"]', '诗', 'shi', '', NULL, '送桂州嚴大夫同用南字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263cca89-a600-405f-a0a8-d778ac99e5b8', '奉酬天平馬十二僕射暇日言懷見寄之作', '奉酬天平马十二僕射暇日言懷见寄之作', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天平篇什外，政事亦無雙。","威令加徐土，儒風被魯邦。","清爲公論重，寬得士心降。","歲晏偏相憶，長謠坐北窗。"]', '["天平篇什外，政事亦無雙。","威令加徐土，儒风被魯邦。","清爲公論重，寬得士心降。","歲晏偏相憶，长謠坐北窗。"]', '诗', 'shi', '', NULL, '奉酬天平馬十二僕射暇日言懷見寄之作 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531d9020-6b63-4b14-8605-9a779b2d2579', '奉使鎮州行次承天行營奉酬裴司空', '奉使鎮州行次承天行營奉酬裴司空', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["竄逐三年海上歸，逢公復此著征衣。","旋吟佳句還鞭馬，恨不身先去鳥飛。"]', '["竄逐三年海上归，逢公复此著征衣。","旋吟佳句還鞭马，恨不身先去鸟飞。"]', '诗', 'shi', '', NULL, '奉使鎮州行次承天行營奉酬裴司空 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e871e4a-9c45-4b79-93c6-a12e91f8ad34', '鎮州路上謹酬裴司空相公重見寄', '鎮州路上謹酬裴司空相公重见寄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["銜命山東撫亂師，日馳三百自嫌遲。","風霜滿面無人識，何處如今更有詩。"]', '["銜命山东撫亂師，日驰三百自嫌遲。","风霜满面無人識，何处如今更有诗。"]', '诗', 'shi', '', NULL, '鎮州路上謹酬裴司空相公重見寄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5641c747-b437-4c50-b073-812cf05aec0e', '奉和僕射裴相公感跨恩言志', '奉和僕射裴相公感跨恩言志', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["文武功成後，居爲百辟師。","林園窮勝事，鐘鼓樂清時。","擺落遺高論，雕鐫出小詩。","自然無不可，范蠡爾其誰。"]', '["文武功成後，居爲百辟師。","林园窮勝事，鐘鼓乐清时。","擺落遺高論，雕鐫出小诗。","自然無不可，范蠡爾其誰。"]', '诗', 'shi', '', NULL, '奉和僕射裴相公感跨恩言志 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a639502-2c63-4bd7-86d7-01edca3c50f6', '和僕射相公朝廻見寄', '和僕射相公朝廻见寄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["盡瘁年將久，公今始暫閑。","事隨憂共減，詩與酒俱還。","放意機衡外，收身矢石間。","秋臺風日迥，正好看前山。"]', '["尽瘁年將久，公今始暫闲。","事隨憂共減，诗與酒俱還。","放意機衡外，收身矢石间。","秋台风日迥，正好看前山。"]', '诗', 'shi', '', NULL, '和僕射相公朝廻見寄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d878ef-3122-49aa-a5e9-311d5442c8d4', '奉和李相公題蕭家林亭', '奉和李相公題蕭家林亭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["山公自是林園主，歎惜前賢造作時。","巖洞幽深門盡鎖，不因丞相幾人知。"]', '["山公自是林园主，歎惜前賢造作时。","巖洞幽深门尽鎖，不因丞相幾人知。"]', '诗', 'shi', '', NULL, '奉和李相公題蕭家林亭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('736572d1-f38d-46aa-ba3d-8b895cf81011', '奉和杜相公太清宮紀事陳誠上李相公十六韻', '奉和杜相公太清宮紀事陳誠上李相公十六韻', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["耒耜興姬國，輴欙建夏家。","在功誠可尚，於道詎爲華。","象帝威容大，僊宗寶曆賒。","衛門羅戟槊，圖壁雜龍蛇。","禮樂追尊盛，乾坤降福遐。","四真皆齒列，二聖亦肩差。","陽月時之首，陰泉氣未牙。","殿階鋪水碧，庭炬坼金葩。","紫極觀忘倦，青詞奏不譁。","噌吰宮夜闢，嘈囐鼓晨撾。","褻味陳奚取，名香薦孔嘉。","垂祥紛可錄，俾壽浩無涯。","貴相山瞻峻，清文玉絕瑕。","代工聲問遠，攝事敬恭加。","皎潔當天月，葳蕤捧日霞。","唱妍酬亦麗，俛仰但稱嗟。"]', '["耒耜兴姬国，輴欙建夏家。","在功誠可尚，於道詎爲华。","象帝威容大，僊宗寶曆賒。","衛门羅戟槊，圖壁杂龙蛇。","禮乐追尊盛，乾坤降福遐。","四真皆齒列，二聖亦肩差。","陽月时之首，陰泉氣未牙。","殿階鋪水碧，庭炬坼金葩。","紫極观忘倦，青词奏不譁。","噌吰宮夜闢，嘈囐鼓晨撾。","褻味陳奚取，名香薦孔嘉。","垂祥紛可錄，俾壽浩無涯。","貴相山瞻峻，清文玉絕瑕。","代工声问远，攝事敬恭加。","皎潔當天月，葳蕤捧日霞。","唱妍酬亦丽，俛仰但稱嗟。"]', '诗', 'shi', '', NULL, '奉和杜相公太清宮紀事陳誠上李相公十六韻 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9763af12-4206-43f2-ba3c-1dd4265b713e', '鄆州谿堂詩', '鄆州谿堂诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["帝奠九廛，有葉有年。","有荒不條，河岱之間。","及我憲考，一收正之。","視邦選侯，以公來尸。","公來尸之，人始未信。","公不飲食，以訓以徇。","孰飢無食，孰呻孰歎。","孰冤不問，不得分願。","孰爲邦蟊，節根之螟。","羊很狼貪，以口覆城。","吹之喣之，摩手拊之。","箴之石之，膊而磔之。","凡公四封，既富以彊。","謂公吾父，孰違公令。","可以師征，不寧守邦。","公作谿堂，播播流水。","淺有蒲蓮，深有葭葦。","公以賓燕，其鼓駭駭。","公燕谿堂，賓校醉飽。","流有跳魚，岸有集鳥。","既歌以舞，其鼓考考。","公在谿堂，公御琴瑟。","公暨賓贊，稽經諏律。","施用不差，人用不屈。","谿有薲苽，有龜有魚。","公在中流，右詩左書。","無我斁遺，此邦是庥。"]', '["帝奠九廛，有葉有年。","有荒不條，河岱之间。","及我憲考，一收正之。","視邦選侯，以公来尸。","公来尸之，人始未信。","公不饮食，以訓以徇。","孰飢無食，孰呻孰歎。","孰冤不问，不得分願。","孰爲邦蟊，節根之螟。","羊很狼貪，以口覆城。","吹之喣之，摩手拊之。","箴之石之，膊而磔之。","凡公四封，既富以彊。","謂公吾父，孰違公令。","可以師征，不寧守邦。","公作谿堂，播播流水。","淺有蒲蓮，深有葭葦。","公以賓燕，其鼓駭駭。","公燕谿堂，賓校醉飽。","流有跳鱼，岸有集鸟。","既歌以舞，其鼓考考。","公在谿堂，公御琴瑟。","公暨賓贊，稽經諏律。","施用不差，人用不屈。","谿有薲苽，有龟有鱼。","公在中流，右诗左书。","無我斁遺，此邦是庥。"]', '诗', 'shi', '', NULL, '鄆州谿堂詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fbeeb1-832d-4c6d-a461-d06da393a4bf', '送張道士', '送張道士', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["大匠無棄材，尋尺各有施。","況當營都邑，杞梓用不疑。","張侯嵩高來，面有熊豹姿。","開口論利害，劒鋒白差差。","恨無一尺捶，爲國笞羌夷。","詣闕三上書，臣非黃冠師。","臣有膽與氣，不忍死茅茨。","又不媚笑語，不能伴兒嬉。","乃著道士服，衆人莫臣知。","臣有平賊策，狂童不難治。","其言簡且要，陛下幸聽之。","天空日月高，下照理不遺。","或是章奏繁，裁擇未及斯。","寧當不竢報，歸袖風披披。","答我事不爾，吾親屬吾思。","昨宵夢倚門，手取連環持。","今日有書至，又言歸何時。","霜天熟柿栗，收拾不可遲。","嶺北梁可構，寒魚下清伊。","既非公家用，且復還其私。","從容進退間，無一不合宜。","時有利不利，雖賢欲奚爲。","但當勵前操，富貴非公誰。"]', '["大匠無棄材，尋尺各有施。","況當營都邑，杞梓用不疑。","張侯嵩高来，面有熊豹姿。","开口論利害，劒鋒白差差。","恨無一尺捶，爲国笞羌夷。","詣闕三上书，臣非黄冠師。","臣有膽與氣，不忍死茅茨。","又不媚笑語，不能伴兒嬉。","乃著道士服，衆人莫臣知。","臣有平賊策，狂童不难治。","其言簡且要，陛下幸听之。","天空日月高，下照理不遺。","或是章奏繁，裁擇未及斯。","寧當不竢報，归袖风披披。","答我事不爾，吾親屬吾思。","昨宵梦倚门，手取連环持。","今日有书至，又言归何时。","霜天熟柿栗，收拾不可遲。","嶺北梁可構，寒鱼下清伊。","既非公家用，且复還其私。","從容進退间，無一不合宜。","时有利不利，雖賢欲奚爲。","但當勵前操，富貴非公誰。"]', '诗', 'shi', '', NULL, '送張道士 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837ee663-d797-49f4-93b8-923d4baac950', '送鄭十校理得洛字', '送鄭十校理得洛字', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["相公倦台鼎，分正新邑洛。","才子富文華，校讐天祿閣。","壽觴佳節過，歸騎春衫薄。","鳥哢正交加，楊花共紛泊。","親交誰不羨，去去翔寥廓。"]', '["相公倦台鼎，分正新邑洛。","才子富文华，校讐天祿閣。","壽觴佳節過，归騎春衫薄。","鸟哢正交加，楊花共紛泊。","親交誰不羨，去去翔寥廓。"]', '诗', 'shi', '', NULL, '送鄭十校理得洛字 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4196d48d-8b3d-4b74-b28c-1cecaa9f32fa', '送陸歙州傪', '送陸歙州傪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我衣之華兮，我佩之光。","陸君之去兮，誰與翺翔。","斂此大惠兮，施於一州。","今其去矣，胡不爲留。","我作此詩，歌於遠道。","無疾其驅，天子有詔。"]', '["我衣之华兮，我佩之光。","陸君之去兮，誰與翺翔。","斂此大惠兮，施於一州。","今其去矣，胡不爲留。","我作此诗，歌於远道。","無疾其驱，天子有詔。"]', '诗', 'shi', '', NULL, '送陸歙州傪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f3bc50-8a7f-4445-995e-1d1af406ae26', '送汴州監軍俱文珍', '送汴州監軍俱文珍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["奉使羌池靜，臨戎汴水安。","沖天鵬翅闊，報國劒鋩寒。","曉日驅征騎，春風詠采蘭。","誰言臣子道，忠孝兩全難。"]', '["奉使羌池静，臨戎汴水安。","沖天鵬翅闊，報国劒鋩寒。","晓日驱征騎，春风詠采蘭。","誰言臣子道，忠孝兩全难。"]', '诗', 'shi', '', NULL, '送汴州監軍俱文珍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616dfb51-66c5-483f-b2a9-134e151c5009', '贈崔立之', '贈崔立之', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔年十日雨，子桑苦寒飢。","哀歌坐空室，不怨但自悲。","其友名子輿，忽然憂且思。","搴裳觸泥水，裹飯往食之。","入門相對語，天命良不疑。","好事漆園吏，書之存雄詞。","千年事已遠，二子情可推。","我讀此篇日，正當寒雪時。","吾身固已困，吾友復何爲。","薄粥不足裹，深泥諒難馳。","曾無子輿事，空賦子桑詩。"]', '["昔年十日雨，子桑苦寒飢。","哀歌坐空室，不怨但自悲。","其友名子輿，忽然憂且思。","搴裳觸泥水，裹飯往食之。","入门相对語，天命良不疑。","好事漆园吏，书之存雄词。","千年事已远，二子情可推。","我读此篇日，正當寒雪时。","吾身固已困，吾友复何爲。","薄粥不足裹，深泥諒难驰。","曾無子輿事，空賦子桑诗。"]', '诗', 'shi', '', NULL, '贈崔立之 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c77b837-3be7-4296-b952-ce99dff4f622', '海水', '海水', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["海水非不廣，鄧林豈無枝。","風波一蕩薄，魚鳥不可依。","海水饒大波，鄧林多驚風。","豈無魚與鳥，巨細各不同。","海有吞舟鯨，鄧有垂天鵬。","苟非鱗羽大，蕩薄不可能。","我鱗不盈寸，我羽不盈尺。","一木有餘陰，一泉有餘澤。","我將辭海水，濯鱗清冷池。","我將辭鄧林，刷羽蒙籠枝。","海水非愛廣，鄧林非愛枝。","風波亦常事，鱗魚自不宜。","我鱗日已大，我羽日已修。","風波無所苦，還作鯨鵬遊。"]', '["海水非不廣，鄧林豈無枝。","风波一蕩薄，鱼鸟不可依。","海水饒大波，鄧林多驚风。","豈無鱼與鸟，巨細各不同。","海有吞舟鯨，鄧有垂天鵬。","苟非鱗羽大，蕩薄不可能。","我鱗不盈寸，我羽不盈尺。","一木有餘陰，一泉有餘澤。","我將辞海水，濯鱗清冷池。","我將辞鄧林，刷羽蒙籠枝。","海水非愛廣，鄧林非愛枝。","风波亦常事，鱗鱼自不宜。","我鱗日已大，我羽日已修。","风波無所苦，還作鯨鵬游。"]', '诗', 'shi', '', NULL, '海水 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28106f1b-3e27-4774-a357-7f4dba9cb7ca', '贈河陽李大夫', '贈河陽李大夫', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["四海失巢穴，兩都困塵埃。","感恩由未報，惆悵空一來。","裘破氣不暖，馬羸鳴且哀。","主人情更重，空使劒鋒摧。"]', '["四海失巢穴，兩都困塵埃。","感恩由未報，惆悵空一来。","裘破氣不暖，马羸鳴且哀。","主人情更重，空使劒鋒摧。"]', '诗', 'shi', '', NULL, '贈河陽李大夫 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13931b8a-688a-4ebb-9354-b15490ba70c2', '苦寒歌', '苦寒歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["黃昏苦寒歌，夜半不能休。","豈不有陽春，節歲聿其周。","君何愛重裘，兼味養大賢。","冰食葛製神所憐，填窗塞戶慎勿出，暄風暖景明年日。"]', '["黄昏苦寒歌，夜半不能休。","豈不有陽春，節歲聿其周。","君何愛重裘，兼味養大賢。","冰食葛製神所怜，填窗塞戶慎勿出，暄风暖景明年日。"]', '诗', 'shi', '', NULL, '苦寒歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe4cef65-5782-4d2d-ba9e-7e956b2f0d55', '芍藥歌', '芍藥歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["丈人庭中開好花，更無凡木爭春華。","翠莖紅蘂天力與，此恩不屬黃鍾家。","溫馨熟美鮮香起，似笑無言習君子。","霜刀翦汝天女勞，何事低頭學桃李。","嬌癡婢子無靈性，競挽春衫來比並。","欲將雙頰一晞紅，綠窗磨徧青銅鏡。","一尊春酒甘若飴，丈人此樂無人知。","花前醉倒歌者誰，楚狂小子韓退之。"]', '["丈人庭中开好花，更無凡木爭春华。","翠莖紅蘂天力與，此恩不屬黄鍾家。","溫馨熟美鲜香起，似笑無言習君子。","霜刀翦汝天女勞，何事低头学桃李。","嬌癡婢子無靈性，競挽春衫来比並。","欲將雙頰一晞紅，綠窗磨徧青銅镜。","一尊春酒甘若飴，丈人此乐無人知。","花前醉倒歌者誰，楚狂小子韓退之。"]', '诗', 'shi', '', NULL, '芍藥歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce64707-a533-438a-9d36-deb8520b13f7', '贈徐州族姪', '贈徐州族姪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我年十八九，壯氣起胸中。","作書獻雲闕，辭家逐秋蓬。","歲時易遷次，身命多厄窮。","一名雖云就，片祿不足充。","今者復何事，卑棲寄徐戎。","蕭條資用盡，濩落門巷空。","朝眠未能起，遠懷方鬱悰。","擊門者誰子，問言乃吾宗。","自云有奇術，探妙知天工。","既往悵何及，將來喜還通。","期我語非佞，當爲佐時雍。"]', '["我年十八九，壯氣起胸中。","作书獻云闕，辞家逐秋蓬。","歲时易遷次，身命多厄窮。","一名雖云就，片祿不足充。","今者复何事，卑棲寄徐戎。","蕭條資用尽，濩落门巷空。","朝眠未能起，远懷方鬱悰。","擊门者誰子，问言乃吾宗。","自云有奇術，探妙知天工。","既往悵何及，將来喜還通。","期我語非佞，當爲佐时雍。"]', '诗', 'shi', '', NULL, '贈徐州族姪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee63cab-0d90-4fd0-b35f-116d0edede51', '嘲鼾睡', '嘲鼾睡', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["澹師晝睡時，聲氣一何猥。","頑飆吹肥脂，坑谷相嵬磊。","雄哮乍咽絕，每發壯益倍。","有如阿鼻尸，長喚忍衆罪。","馬牛驚不食，百鬼聚相待。","木枕十字裂，鏡面生痱癗。","鐵佛聞皺眉，石人戰搖腿。","孰云天地仁，吾欲責真宰。","幽尋虱搜耳，猛作濤翻海。","太陽不忍明，飛御皆惰怠。","乍如彭與黥，呼冤受葅醢。","又如圈中虎，號瘡兼吼餒。","雖令伶倫吹，苦韻難可改。","雖令巫咸招，魂爽難復在。","何山有靈藥，療此願與採。"]', '["澹師晝睡时，声氣一何猥。","頑飆吹肥脂，坑谷相嵬磊。","雄哮乍咽絕，每發壯益倍。","有如阿鼻尸，长喚忍衆罪。","马牛驚不食，百鬼聚相待。","木枕十字裂，镜面生痱癗。","鐵佛闻皺眉，石人戰搖腿。","孰云天地仁，吾欲責真宰。","幽尋虱搜耳，猛作濤翻海。","太陽不忍明，飞御皆惰怠。","乍如彭與黥，呼冤受葅醢。","又如圈中虎，號瘡兼吼餒。","雖令伶倫吹，苦韻难可改。","雖令巫咸招，魂爽难复在。","何山有靈藥，療此願與採。"]', '诗', 'shi', '', NULL, '嘲鼾睡 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780ee4b9-16db-4039-ae3c-2f393b1281ef', '嘲鼾睡 二', '嘲鼾睡 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["澹公坐臥時，長睡無不穩。","吾嘗聞其聲，深慮五藏損。","黃河弄濆薄，梗澀連拙鮌。","南帝初舊槌，鑿竅洩混沌。","迥然忽長引，萬丈不可忖。","謂言絕於斯，繼出方袞袞。","幽幽寸喉中，草木森苯䔿。","盜賊雖狡獪，亡魂敢窺閫。","鴻蒙總合雜，詭譎騁戾很。","乍如鬬呶呶，忽若怨懇懇。","賦形苦不同，無路尋根本。","何能堙其源，惟有土一畚。"]', '["澹公坐臥时，长睡無不穩。","吾嘗闻其声，深慮五藏損。","黄河弄濆薄，梗澀連拙鮌。","南帝初旧槌，鑿竅洩混沌。","迥然忽长引，万丈不可忖。","謂言絕於斯，繼出方袞袞。","幽幽寸喉中，草木森苯䔿。","盜賊雖狡獪，亡魂敢窺閫。","鴻蒙總合杂，詭譎騁戾很。","乍如鬬呶呶，忽若怨懇懇。","賦形苦不同，無路尋根本。","何能堙其源，惟有土一畚。"]', '诗', 'shi', '', NULL, '嘲鼾睡 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff42e14b-b52e-42f4-99f5-271350ce688a', '晝月', '晝月', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["玉盌不磨著泥土，青天孔出白石補。","兔入臼藏蛙縮肚，桂樹枯株女閉戶。","陰爲陽羞固自古，嗟汝下民或敢侮，戲嘲盜視汝目瞽。"]', '["玉盌不磨著泥土，青天孔出白石補。","兔入臼藏蛙縮肚，桂樹枯株女閉戶。","陰爲陽羞固自古，嗟汝下民或敢侮，戲嘲盜視汝目瞽。"]', '诗', 'shi', '', NULL, '晝月 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6c694c-c2d2-476c-a1ff-a43def1eede7', '贈張徐州莫辭酒', '贈張徐州莫辞酒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["莫辭酒，此會固難同。","請看女工機上帛，半作軍人旗上紅。","莫辭酒，誰爲君王之爪牙。","春雷三月不作響，戰士豈得來還家。"]', '["莫辞酒，此會固难同。","請看女工機上帛，半作軍人旗上紅。","莫辞酒，誰爲君王之爪牙。","春雷三月不作响，戰士豈得来還家。"]', '诗', 'shi', '', NULL, '贈張徐州莫辭酒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbb3f85-f8bd-4e6c-8077-f7153f0b13f7', '辭唱歌', '辞唱歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["抑逼敎唱歌，不解看豔詞。","坐中把酒人，豈有歡樂姿。","幸有伶者婦，腰身如柳枝。","但令送君酒，如醉如憨癡。","聲自肉中出，使人能逶隨。","復遣慳恡者，贈金不皺眉。","豈有長直夫，喉中聲雌雌。","君心豈無恥，君豈是女兒。","君敎發直言，大聲無休時。","君敎哭古恨，不肯復吞悲。","乍可阻君意，豔歌難可爲。"]', '["抑逼敎唱歌，不解看豔词。","坐中把酒人，豈有歡乐姿。","幸有伶者婦，腰身如柳枝。","但令送君酒，如醉如憨癡。","声自肉中出，使人能逶隨。","复遣慳恡者，贈金不皺眉。","豈有长直夫，喉中声雌雌。","君心豈無恥，君豈是女兒。","君敎發直言，大声無休时。","君敎哭古恨，不肯复吞悲。","乍可阻君意，豔歌难可爲。"]', '诗', 'shi', '', NULL, '辭唱歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd60767-2951-4ad1-993d-cf1ff770aede', '知音者誠希', '知音者誠希', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["知音者誠希，念子不能別。","行行天未曉，攜酒踏明月。"]', '["知音者誠希，念子不能別。","行行天未晓，携酒踏明月。"]', '诗', 'shi', '', NULL, '知音者誠希 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f900f9e-1045-42bf-a4e2-57e644560bc3', '同竇韋尋劉尊師不遇', '同竇韋尋劉尊師不遇', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秦客何年駐，仙源此地深。","還隨躡鳧騎，來訪馭風襟。","院閉青霞入，松高老鶴尋。","猶疑隱形坐，敢起竊桃心。"]', '["秦客何年駐，仙源此地深。","還隨躡鳧騎，来訪馭风襟。","院閉青霞入，松高老鹤尋。","猶疑隐形坐，敢起竊桃心。"]', '诗', 'shi', '', NULL, '同竇韋尋劉尊師不遇 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b995b0e-aaf5-4332-9f95-ade8ac6d14ef', '春雪', '春雪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["片片驅鴻急，紛紛逐吹斜。","到江還作水，著樹漸成花。","越喜飛排瘴，胡愁厚蓋砂。","兼雲封洞口，助月照天涯。","暝見迷巢鳥，朝逢失轍車。","呈豐盡相賀，寧止力耕家。"]', '["片片驱鴻急，紛紛逐吹斜。","到江還作水，著樹漸成花。","越喜飞排瘴，胡愁厚蓋砂。","兼云封洞口，助月照天涯。","暝见迷巢鸟，朝逢失轍车。","呈豐尽相賀，寧止力耕家。"]', '诗', 'shi', '', NULL, '春雪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4824b743-c097-468f-8df4-3990f966d05f', '酬藍田崔丞立之詠雪見寄', '酬藍田崔丞立之詠雪见寄', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["京城數尺雪，寒氣倍常年。","泯泯都無地，茫茫豈是天。","崩奔驚亂射，揮霍訝相纏。","不覺侵堂陛，方應折屋椽。","出門愁落道，上馬恐平韉。","朝鼓矜凌起，山齋酩酊眠。","吾方嗟此役，君乃詠其妍。","冰玉清顏隔，波濤盛句傳。","朝飧思共飯，夜宿憶同氈。","舉目無非白，雄文乃獨玄。"]', '["京城數尺雪，寒氣倍常年。","泯泯都無地，茫茫豈是天。","崩奔驚亂射，揮霍訝相纏。","不覺侵堂陛，方應折屋椽。","出门愁落道，上马恐平韉。","朝鼓矜凌起，山斋酩酊眠。","吾方嗟此役，君乃詠其妍。","冰玉清顏隔，波濤盛句傳。","朝飧思共飯，夜宿憶同氈。","舉目無非白，雄文乃独玄。"]', '诗', 'shi', '', NULL, '酬藍田崔丞立之詠雪見寄 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb024e5-a471-4caf-8a56-6607196b8776', '潭州泊船呈諸公', '潭州泊船呈諸公', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["夜寒眠半覺，鼓笛鬧嘈嘈。","暗浪舂樓堞，驚風破竹篙。","主人看使範，客子讀離騷。","聞道松醪賤，何須恡錯刀。"]', '["夜寒眠半覺，鼓笛鬧嘈嘈。","暗浪舂楼堞，驚风破竹篙。","主人看使範，客子读離騷。","闻道松醪賤，何須恡錯刀。"]', '诗', 'shi', '', NULL, '潭州泊船呈諸公 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b92f553-d6d8-46c7-898c-e441ffcf7192', '飲城南道邊古墓上逢中丞過贈禮部衛員外少室張道士', '饮城南道邊古墓上逢中丞過贈禮部衛員外少室張道士', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["偶上城南土骨堆，共傾春酒三五桮。","爲逢桃樹相料理，不覺中丞喝道來。"]', '["偶上城南土骨堆，共傾春酒三五桮。","爲逢桃樹相料理，不覺中丞喝道来。"]', '诗', 'shi', '', NULL, '飲城南道邊古墓上逢中丞過贈禮部衛員外少室張道士 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81454da0-d4c8-43a7-84e2-0224ebc041ef', '池上絮', '池上絮', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["池上無風有落暉，楊花晴後自飛飛。","爲將纖質凌清鏡，濕却無窮不得歸。"]', '["池上無风有落暉，楊花晴後自飞飞。","爲將纖質凌清镜，濕却無窮不得归。"]', '诗', 'shi', '', NULL, '池上絮 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5006eea-d3d2-4f5e-8cf7-f4eb89758fb0', '贈賈島', '贈賈島', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["孟郊死葬北邙山，從此風雲得暫閑。","天恐文章渾斷絕，更生賈島着人間。"]', '["孟郊死葬北邙山，從此风云得暫闲。","天恐文章渾斷絕，更生賈島着人间。"]', '诗', 'shi', '', NULL, '贈賈島 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ed33f4-ad7a-4498-9554-f2a993b55868', '贈賈島', '贈賈島', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["孟郊死葬北邙山，從此風雲得暫閑。","世上不教才子絶，更生賈島着人間。"]', '["孟郊死葬北邙山，從此风云得暫闲。","世上不教才子絶，更生賈島着人间。"]', '诗', 'shi', '', NULL, '贈賈島 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9a731e-dbf1-4b4b-acae-f6b3b18646a4', '贈譯經僧', '贈譯經僧', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["萬里休言道路賒，有誰敎汝度流沙。","只今中國方多事，不用無端更亂華。"]', '["万里休言道路賒，有誰敎汝度流沙。","只今中国方多事，不用無端更亂华。"]', '诗', 'shi', '', NULL, '贈譯經僧 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafc4c1f-228d-4615-b3a2-0d634ac19607', '享惠昭太子廟樂章', '享惠昭太子廟乐章', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["威儀畢陳，備樂將闋。","苞茅酒縮，膋蕭香徹。","宮臣展事，肅雍在列。","迎精送往，厥鑒昭晰。"]', '["威儀畢陳，備乐將闋。","苞茅酒縮，膋蕭香徹。","宮臣展事，肅雍在列。","迎精送往，厥鑒昭晰。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee0b55c-e436-41ab-980c-c6b609790ce5', '望禁門松雪', '望禁门松雪', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["宿雲開霽景，佳氣此時濃。","瑞雪凝清禁，祥煙冪小松。","依稀鴛瓦出，隱映鳳樓重。","金闕晴光照，瓊枝瑞色封。","葉鋪全類玉，柯偃乍疑龍。","詎比寒山上，風霜老昔容。"]', '["宿云开霽景，佳氣此时濃。","瑞雪凝清禁，祥煙冪小松。","依稀鴛瓦出，隐映鳳楼重。","金闕晴光照，瓊枝瑞色封。","葉鋪全類玉，柯偃乍疑龙。","詎比寒山上，风霜老昔容。"]', '诗', 'shi', '', NULL, '望禁門松雪 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5eacd94-ff51-4cca-af84-dce680383b0a', '廣宣上人以詩賀放榜和謝', '廣宣上人以诗賀放榜和謝', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["延英面奉入春闈，亦選功夫亦選奇。","在冶只求金不耗，用心空學秤無私。","龍門變化人皆望，鶯谷飛鳴自有時。","獨喜至公誰是證，彌天上人與新詩。"]', '["延英面奉入春闈，亦選功夫亦選奇。","在冶只求金不耗，用心空学秤無私。","龙门变化人皆望，鶯谷飞鳴自有时。","独喜至公誰是證，彌天上人與新诗。"]', '诗', 'shi', '', NULL, '廣宣上人以詩賀放榜和謝 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5d0bbe-5783-4352-84e2-56e01c1b3b4a', '九月九日勤政樓下觀百僚獻壽', '九月九日勤政楼下观百僚獻壽', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["御氣黃花節，臨軒紫陌頭。","早陽生綵仗，霽色入仙樓。","獻壽皆鵷鷺，瞻天盡冕旒。","菊樽過九日，鳳曆肇千秋。","樂奏薰風起，盃酣瑞影收。","年年歌舞度，此地慶皇休。"]', '["御氣黄花節，臨軒紫陌头。","早陽生綵仗，霽色入仙楼。","獻壽皆鵷鷺，瞻天尽冕旒。","菊樽過九日，鳳曆肇千秋。","乐奏薰风起，盃酣瑞影收。","年年歌舞度，此地慶皇休。"]', '诗', 'shi', '', NULL, '九月九日勤政樓下觀百僚獻壽 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55efc4cb-6eb0-46b4-babc-4caea0dba170', '春遊曲二首 一', '春游曲二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["萬樹江邊杏，新開一夜風。","滿園深淺色，照在綠波中。"]', '["万樹江邊杏，新开一夜风。","满园深淺色，照在綠波中。"]', '诗', 'shi', '', NULL, '春遊曲二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c5aa16-1dd4-4958-b8f1-c813ccfd8022', '春遊曲二首 二', '春游曲二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["上苑何窮樹，花間次第新。","香車與絲騎，風靜亦生塵。"]', '["上苑何窮樹，花间次第新。","香车與絲騎，风静亦生塵。"]', '诗', 'shi', '', NULL, '春遊曲二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70889241-0c17-4d61-af05-f7e9d3ca1936', '太平詞', '太平词', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["風俗今和厚，君王在穆清。","行看采華曲，盡是泰階平。"]', '["风俗今和厚，君王在穆清。","行看采华曲，尽是泰階平。"]', '诗', 'shi', '', NULL, '太平詞 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9910755c-0c3d-4b6d-bb66-ee175ed1d911', '送春詞', '送春词', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["日日人空老，年年春更歸。","相歡在尊酒，不用惜花飛。"]', '["日日人空老，年年春更归。","相歡在尊酒，不用惜花飞。"]', '诗', 'shi', '', NULL, '送春詞 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5099ed5-7f3a-44af-85fb-e2dde9286b3e', '塞上曲二首 一', '塞上曲二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["天驕遠塞行，出鞘寶刀鳴。","定是酬恩日，今朝覺命輕。"]', '["天驕远塞行，出鞘寶刀鳴。","定是酬恩日，今朝覺命轻。"]', '诗', 'shi', '', NULL, '塞上曲二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ea7318-bbea-409d-8efb-9b47e6d277a1', '塞上曲二首 二', '塞上曲二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["塞虜常爲敵，邊風已報秋。","平生多志氣，箭底覓封侯。"]', '["塞虜常爲敵，邊风已報秋。","平生多志氣，箭底覓封侯。"]', '诗', 'shi', '', NULL, '塞上曲二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a4b793-07df-4a30-993d-fb6fe576feab', '隴上行', '隴上行', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["負羽到邊州，鳴笳度隴頭。","雲黃知塞近，草白見邊秋。"]', '["負羽到邊州，鳴笳度隴头。","云黄知塞近，草白见邊秋。"]', '诗', 'shi', '', NULL, '隴上行 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c256a4bd-24ad-41cf-a750-6619b87c8954', '思君恩', '思君恩', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["雞鳴天漢曉，鶯語禁林春。","誰入巫山夢，唯應洛水神。"]', '["雞鳴天漢晓，鶯語禁林春。","誰入巫山梦，唯應洛水神。"]', '诗', 'shi', '', NULL, '思君恩 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e31a8dc-5ff5-4c8a-a147-ba7522847298', '春閨思', '春閨思', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["雪盡萱抽葉，風輕水變苔。","玉關音信斷，又見發庭梅。"]', '["雪尽萱抽葉，风轻水变苔。","玉关音信斷，又见發庭梅。"]', '诗', 'shi', '', NULL, '春閨思 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7081f4-71d3-4bd6-a190-749e3d272ae2', '春江曲', '春江曲', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["搖漾越江春，相將采白蘋。","歸時不覺夜，出浦月隨人。"]', '["搖漾越江春，相將采白蘋。","归时不覺夜，出浦月隨人。"]', '诗', 'shi', '', NULL, '春江曲 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e8eb3b-b379-4f52-becc-c128dfabd4fd', '閨人贈遠五首 一', '閨人贈远五首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["花明綺陌春，柳拂御溝新。","爲報遼陽客，流芳不待人。"]', '["花明綺陌春，柳拂御溝新。","爲報遼陽客，流芳不待人。"]', '诗', 'shi', '', NULL, '閨人贈遠五首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67b7d02-22c8-4304-9194-64ac25bb6523', '閨人贈遠五首 二', '閨人贈远五首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["遠戍功名薄，幽閨年貌傷。","妝成對春樹，不語淚千行。"]', '["远戍功名薄，幽閨年貌傷。","妝成对春樹，不語泪千行。"]', '诗', 'shi', '', NULL, '閨人贈遠五首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db545213-177e-446c-84ae-f5c9630132eb', '閨人贈遠五首 三', '閨人贈远五首 三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["形影一朝別，煙波千里分。","君看望君處，祗是起行雲。"]', '["形影一朝別，煙波千里分。","君看望君处，祗是起行云。"]', '诗', 'shi', '', NULL, '閨人贈遠五首 三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c8c58e-4b0e-413e-bdc6-5b3509e80d0d', '閨人贈遠五首 四', '閨人贈远五首 四', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["啼鶯綠樹深，語燕雕梁晚。","不省出門行，沙場知近遠。"]', '["啼鶯綠樹深，語燕雕梁晚。","不省出门行，沙場知近远。"]', '诗', 'shi', '', NULL, '閨人贈遠五首 四 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e937a7-e3f1-4fed-949e-24d1d15bf71e', '閨人贈遠五首 五', '閨人贈远五首 五', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["洞房今夜月，如練復如霜。","爲照離人恨，亭亭到曉光。"]', '["洞房今夜月，如練复如霜。","爲照離人恨，亭亭到晓光。"]', '诗', 'shi', '', NULL, '閨人贈遠五首 五 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e1e10b-a2e0-46b6-9f3e-d389972ea4b5', '從軍詞三首 一', '從軍词三首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["戈甲從軍久，風雲識陣難。","今朝拜韓信，計日斬成安。"]', '["戈甲從軍久，风云識陣难。","今朝拜韓信，計日斬成安。"]', '诗', 'shi', '', NULL, '從軍詞三首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198bac3e-2bb0-4fd1-bd41-60b80b10bebd', '從軍詞三首 二', '從軍词三首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["燕頷多奇相，狼頭敢犯邊。","寄言班定遠，正是立功年。"]', '["燕頷多奇相，狼头敢犯邊。","寄言班定远，正是立功年。"]', '诗', 'shi', '', NULL, '從軍詞三首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628b303b-4725-47e9-b676-dd017de3787d', '從軍詞三首 三', '從軍词三首 三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["旄頭夜落捷書飛，來奏金門著賜衣。","白馬將軍頻破敵，黃龍戍卒幾時歸。"]', '["旄头夜落捷书飞，来奏金门著賜衣。","白马將軍頻破敵，黄龙戍卒幾时归。"]', '诗', 'shi', '', NULL, '從軍詞三首 三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18cd25f-f291-411b-9f7c-22cf9013a11a', '塞下曲二首 一', '塞下曲二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["辛勤幾出黃花戍，迢遰初隨細柳營。","塞晚每愁殘月苦，邊愁更逐斷篷驚。"]', '["辛勤幾出黄花戍，迢遰初隨細柳營。","塞晚每愁殘月苦，邊愁更逐斷篷驚。"]', '诗', 'shi', '', NULL, '塞下曲二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85077c6f-9548-43fd-82e7-726a9cfd759d', '塞下曲二首 二', '塞下曲二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["年少辭家從冠軍，金妝寶劒去邀勳。","不知馬骨傷寒水，唯見龍城起暮雲。"]', '["年少辞家從冠軍，金妝寶劒去邀勳。","不知马骨傷寒水，唯见龙城起暮云。"]', '诗', 'shi', '', NULL, '塞下曲二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7a8f95-8421-45b7-837b-e7465157a3c7', '平戎辭', '平戎辞', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["太白秋高助發兵，長風夜卷虜塵清。","男兒解却腰間劒，喜見從王道化平。"]', '["太白秋高助發兵，长风夜卷虜塵清。","男兒解却腰间劒，喜见從王道化平。"]', '诗', 'shi', '', NULL, '平戎辭 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c6f457-bb8f-40c6-95e6-8490c0ab5601', '遊春詞二首 一', '游春词二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["曲江綠柳變煙條，寒谷冰隨暖氣銷。","纔見春光生綺陌，已聞清樂動雲韶。"]', '["曲江綠柳变煙條，寒谷冰隨暖氣銷。","纔见春光生綺陌，已闻清乐动云韶。"]', '诗', 'shi', '', NULL, '遊春詞二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4564c76-9a91-41da-93bb-ed8fcc28bb55', '遊春詞二首 二', '游春词二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["經過柳陌與桃蹊，尋逐春光著處迷。","鳥度時時衝絮起，花繁衮衮壓枝低。"]', '["經過柳陌與桃蹊，尋逐春光著处迷。","鸟度时时衝絮起，花繁衮衮壓枝低。"]', '诗', 'shi', '', NULL, '遊春詞二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524dd709-b9fd-494f-9496-60e7bec43c83', '秋思二首 一', '秋思二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["網軒涼吹動輕衣，夜聽更長玉漏稀。","月度天河光轉濕，鵲驚秋樹葉頻飛。"]', '["網軒涼吹动轻衣，夜听更长玉漏稀。","月度天河光轉濕，鵲驚秋樹葉頻飞。"]', '诗', 'shi', '', NULL, '秋思二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4dcbde6-84cd-47d8-886f-578b3af77234', '秋思二首 二', '秋思二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["宮連太液見滄波，暑氣微消秋意多。","一夜清風蘋末起，露珠翻盡滿池荷。"]', '["宮連太液见滄波，暑氣微消秋意多。","一夜清风蘋末起，露珠翻尽满池荷。"]', '诗', 'shi', '', NULL, '秋思二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40aaaddc-20eb-4b3d-8e71-d5402e0065d8', '漢苑行', '漢苑行', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["二月春風遍柳條，九天仙樂奏雲韶。","蓬萊殿後花如錦，紫閣階前雪未銷。"]', '["二月春风遍柳條，九天仙乐奏云韶。","蓬萊殿後花如錦，紫閣階前雪未銷。"]', '诗', 'shi', '', NULL, '漢苑行 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0055db4e-e8d3-41a0-b201-0e3b970e27b6', '秋夜曲', '秋夜曲', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["桂魄初生秋露微，輕羅已薄未更衣。","銀箏夜久殷勤弄，心怯空房不忍歸。"]', '["桂魄初生秋露微，轻羅已薄未更衣。","銀箏夜久殷勤弄，心怯空房不忍归。"]', '诗', 'shi', '', NULL, '秋夜曲 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c67e23-39cb-460d-9bc6-695ba45f788f', '獻壽辭', '獻壽辞', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["宮殿參差列九重，祥雲瑞氣捧堦濃。","微臣欲獻唐堯壽，遙指南山對衮龍。"]', '["宮殿參差列九重，祥云瑞氣捧堦濃。","微臣欲獻唐堯壽，遙指南山对衮龙。"]', '诗', 'shi', '', NULL, '獻壽辭 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44d4faf2-cb8d-42b6-94e5-2fd74bb867b8', '秋思贈遠二首 一', '秋思贈远二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["當年只自守空帷，夢裏關山覺別離。","不見鄉書傳鴈足，唯看新月吐蛾眉。"]', '["當年只自守空帷，梦裏关山覺別離。","不见乡书傳鴈足，唯看新月吐蛾眉。"]', '诗', 'shi', '', NULL, '秋思贈遠二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0097454e-92da-4f1c-8ebf-47033b154acc', '秋思贈遠二首 二', '秋思贈远二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["厭攀楊柳臨清閣，閑採芙蕖傍碧潭。","走馬臺邊人不見，拂雲堆畔戰初酣。"]', '["厭攀楊柳臨清閣，闲採芙蕖傍碧潭。","走马台邊人不见，拂云堆畔戰初酣。"]', '诗', 'shi', '', NULL, '秋思贈遠二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7ab732-9f98-4c1d-a764-a2ad1aa96b85', '春閨思', '春閨思', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["愁見遊空百尺絲，春風挽斷更傷離。","閑花落盡青苔地，盡日無人誰得知。"]', '["愁见游空百尺絲，春风挽斷更傷離。","闲花落尽青苔地，尽日無人誰得知。"]', '诗', 'shi', '', NULL, '春閨思 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7d4559-82fb-449b-9e1f-92132d57ecf5', '宮詞三十首 一', '宮词三十首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["白人宜著紫衣裳，冠子梳頭雙眼長。","新睡起來思舊夢，見人忘却道勝常。"]', '["白人宜著紫衣裳，冠子梳头雙眼长。","新睡起来思旧梦，见人忘却道勝常。"]', '诗', 'shi', '', NULL, '宮詞三十首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c8e6bd-0445-4780-9d4f-35dc471988fa', '宮詞三十首 二', '宮词三十首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["春來新插翠雲釵，尚著雲頭踏殿鞋。","欲得君王回一顧，爭扶玉輦下金階。"]', '["春来新插翠云釵，尚著云头踏殿鞋。","欲得君王回一顧，爭扶玉輦下金階。"]', '诗', 'shi', '', NULL, '宮詞三十首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfdd4693-19a7-4d06-b33a-00226c9f79ab', '宮詞三十首 三', '宮词三十首 三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["五更初起覺風寒，香炷燒來夜已殘。","欲卷珠簾驚雪滿，自將紅燭上樓看。"]', '["五更初起覺风寒，香炷燒来夜已殘。","欲卷珠簾驚雪满，自將紅燭上楼看。"]', '诗', 'shi', '', NULL, '宮詞三十首 三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e96a64-452f-4a18-8a2f-3067f8be55c1', '宮詞三十首 四', '宮词三十首 四', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["各將金鎖鎖宮門，院院青娥侍至尊。","頭白監門掌來去，問頻多是最承恩。"]', '["各將金鎖鎖宮门，院院青娥侍至尊。","头白監门掌来去，问頻多是最承恩。"]', '诗', 'shi', '', NULL, '宮詞三十首 四 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2427ecc-d485-4877-8259-c70380cd5a59', '宮詞三十首 五', '宮词三十首 五', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["夜久盤中蠟滴稀，金刀剪起盡霏霏。","傳聲總是君王喚，紅燭臺前著舞衣。"]', '["夜久盤中蠟滴稀，金刀剪起尽霏霏。","傳声總是君王喚，紅燭台前著舞衣。"]', '诗', 'shi', '', NULL, '宮詞三十首 五 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ff849a-0304-4e57-92c4-f6f50a5ed13a', '宮詞三十首 六', '宮词三十首 六', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["箏翻禁曲覺聲難，玉柱皆非舊處安。","記得君王曾道好，長因下輦得先彈。"]', '["箏翻禁曲覺声难，玉柱皆非旧处安。","記得君王曾道好，长因下輦得先彈。"]', '诗', 'shi', '', NULL, '宮詞三十首 六 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767b2bcf-9e3f-4495-aa26-6e5262c3a642', '宮詞三十首 七', '宮词三十首 七', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["一叢高鬢綠雲光，官樣輕輕淡淡黃。","爲看九天公主貴，外邊爭學內家裝。"]', '["一叢高鬢綠云光，官樣轻轻淡淡黄。","爲看九天公主貴，外邊爭学內家裝。"]', '诗', 'shi', '', NULL, '宮詞三十首 七 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42055772-ae3a-4db4-89db-2a662b9f1fef', '宮詞三十首 八', '宮词三十首 八', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["宜春院裏駐仙輿，夜宴笙歌總不如。","傳索金箋提寵號，鐙前御筆與親書。"]', '["宜春院裏駐仙輿，夜宴笙歌總不如。","傳索金箋提寵號，鐙前御笔與親书。"]', '诗', 'shi', '', NULL, '宮詞三十首 八 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1ccbdd2-2eb0-483e-b08e-e38013c5dc39', '宮詞三十首 九', '宮词三十首 九', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["永巷重門漸半開，宮官著鎖隔門回。","誰知曾笑他人處，今日將身自入來。"]', '["永巷重门漸半开，宮官著鎖隔门回。","誰知曾笑他人处，今日將身自入来。"]', '诗', 'shi', '', NULL, '宮詞三十首 九 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d41a6e-0790-450f-ab53-35690819654b', '宮詞三十首 十', '宮词三十首 十', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["春風簾裏舊青娥，無奈新人奪寵何。","寒食禁花開滿樹，玉堂終日閉時多。"]', '["春风簾裏旧青娥，無奈新人奪寵何。","寒食禁花开满樹，玉堂終日閉时多。"]', '诗', 'shi', '', NULL, '宮詞三十首 十 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2fafa3-097a-4a45-880f-51b913f86d8f', '宮詞三十首 十一', '宮词三十首 十一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["碧繡簷前柳散垂，守門宮女欲攀時。","曾經玉輦從容處，不敢臨風折一枝。"]', '["碧繡簷前柳散垂，守门宮女欲攀时。","曾經玉輦從容处，不敢臨风折一枝。"]', '诗', 'shi', '', NULL, '宮詞三十首 十一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b1cddc9-35cd-42ce-b48a-ff61e71cd93a', '宮詞三十首 十二', '宮词三十首 十二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["鴉飛深在禁城牆，多繞重樓複殿傍。","時向春簷瓦溝上，散開朝翅占朝光。"]', '["鴉飞深在禁城牆，多繞重楼複殿傍。","时向春簷瓦溝上，散开朝翅占朝光。"]', '诗', 'shi', '', NULL, '宮詞三十首 十二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5077ea-e80c-4898-b9fe-b6845edf22a7', '宮詞三十首 十三', '宮词三十首 十三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["白雪猧兒拂地行，慣眠紅毯不曾驚。","深宮更有何人到，只曉金階吠晚螢。"]', '["白雪猧兒拂地行，慣眠紅毯不曾驚。","深宮更有何人到，只晓金階吠晚螢。"]', '诗', 'shi', '', NULL, '宮詞三十首 十三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01b4f20-e797-4b44-88a4-2268bfef4330', '宮詞三十首 十四', '宮词三十首 十四', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["百尺仙梯倚閣邊，內人爭下擲金錢。","風來競看銅烏轉，遙指朱干在半天。"]', '["百尺仙梯倚閣邊，內人爭下擲金錢。","风来競看銅烏轉，遙指朱干在半天。"]', '诗', 'shi', '', NULL, '宮詞三十首 十四 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36474bb0-4b71-4a44-8ec9-40ab9280e34c', '宮詞三十首 十五', '宮词三十首 十五', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["春風擺蕩禁花枝，寒食鞦韆滿地時。","又落深宮石渠裏，盡隨流水入龍池。"]', '["春风擺蕩禁花枝，寒食鞦韆满地时。","又落深宮石渠裏，尽隨流水入龙池。"]', '诗', 'shi', '', NULL, '宮詞三十首 十五 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73bea1b1-961a-4774-b78b-9123a9a17136', '宮詞三十首 十六', '宮词三十首 十六', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["牆牆不斷接宮城，金榜皆書殿院名。","萬轉千回相隔處，各調弦管對聞聲。"]', '["牆牆不斷接宮城，金榜皆书殿院名。","万轉千回相隔处，各調弦管对闻声。"]', '诗', 'shi', '', NULL, '宮詞三十首 十六 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6fb581-65bb-4a7d-beda-0f5c94a93c11', '宮詞三十首 十七', '宮词三十首 十七', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["霏霏春雨九重天，漸暖龍池御柳煙。","玉輦遊時應不避，千廊萬屋自相連。"]', '["霏霏春雨九重天，漸暖龙池御柳煙。","玉輦游时應不避，千廊万屋自相連。"]', '诗', 'shi', '', NULL, '宮詞三十首 十七 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49304717-3975-4599-aa06-a88e82169958', '宮詞三十首 十八', '宮词三十首 十八', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["禁門煙起紫沉沉，樓閣當中複道深。","長入暮天凝不散，掖庭宮裏動秋砧。"]', '["禁门煙起紫沉沉，楼閣當中複道深。","长入暮天凝不散，掖庭宮裏动秋砧。"]', '诗', 'shi', '', NULL, '宮詞三十首 十八 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3a53c3d-5cd2-4a9d-918f-e7052d9dcadc', '宮詞三十首 十九', '宮词三十首 十九', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["炎炎夏日滿天時，桐葉交加覆玉墀。","向晚移鐙上銀簟，叢叢綠鬢坐彈棋。"]', '["炎炎夏日满天时，桐葉交加覆玉墀。","向晚移鐙上銀簟，叢叢綠鬢坐彈棋。"]', '诗', 'shi', '', NULL, '宮詞三十首 十九 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c89fc398-d01c-4d20-a847-88a6428b8c15', '宮詞三十首 二十', '宮词三十首 二十', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["瞳瞳日出大明宮，天樂遙聞在碧空。","禁樹無風正和暖，玉樓金殿曉光中。"]', '["瞳瞳日出大明宮，天乐遙闻在碧空。","禁樹無风正和暖，玉楼金殿晓光中。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c57fb0-4d0e-47f6-95a6-ef1769ddb878', '宮詞三十首 二十一', '宮词三十首 二十一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["迥出芙蓉閣上頭，九天懸處正當秋。","年年七夕晴光裏，宮女穿針盡上樓。"]', '["迥出芙蓉閣上头，九天懸处正當秋。","年年七夕晴光裏，宮女穿針尽上楼。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a752946-4b1b-4cfb-ac10-e86155e27a52', '宮詞三十首 二十二', '宮词三十首 二十二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["教來鸚鵡語初成，久閉金籠慣認名。","總向春園看花去，獨於深院笑人聲。"]', '["教来鸚鵡語初成，久閉金籠慣認名。","總向春园看花去，独於深院笑人声。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a421b9-e9aa-4bef-be8a-9def1dfc0442', '宮詞三十首 二十三', '宮词三十首 二十三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["銀瓶瀉水欲朝妝，燭焰紅高粉壁光。","共怪滿衣珠翠冷，黃花瓦上有新霜。"]', '["銀瓶瀉水欲朝妝，燭焰紅高粉壁光。","共怪满衣珠翠冷，黄花瓦上有新霜。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d1c087-8884-44bd-96c1-6c970e86c3b1', '宮詞三十首 二十四', '宮词三十首 二十四', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["迎風殿裏罷雲和，起聽新蟬布淺莎。","爲愛九天和露滴，萬年枝上最聲多。"]', '["迎风殿裏罷云和，起听新蟬布淺莎。","爲愛九天和露滴，万年枝上最声多。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十四 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d130481-5efe-4c51-b80d-a7a9cd1eba20', '宮詞三十首 二十五', '宮词三十首 二十五', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["御果收時屬內官，傍簷低壓玉闌干。","明朝摘向金華殿，盡日枝邊次第看。"]', '["御果收时屬內官，傍簷低壓玉闌干。","明朝摘向金华殿，尽日枝邊次第看。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十五 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ee5b8e-aa3e-4270-aec0-adca994e1d39', '宮詞三十首 二十六', '宮词三十首 二十六', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["內裏松香滿殿聞，四行階下暖氤氳。","春深欲取黃金粉，繞樹宮娥著絳裙。"]', '["內裏松香满殿闻，四行階下暖氤氳。","春深欲取黄金粉，繞樹宮娥著絳裙。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十六 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143b2241-60ea-42f9-ba42-b6d267dd3438', '宮詞三十首 二十七', '宮词三十首 二十七', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["禁樹傳聲在九霄，內中殘火獨遙遙。","千官待取門猶閉，未到宮前下馬橋。"]', '["禁樹傳声在九霄，內中殘火独遙遙。","千官待取门猶閉，未到宮前下马橋。"]', '诗', 'shi', '', NULL, '宮詞三十首 二十七 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ec394c-fd55-41fd-a677-c683c1fcb166', '御溝新柳', '御溝新柳', '6e792860-1248-4b2b-b305-81f3abdf41a8', '唐', '["御苑陽和早，章溝柳色新。","託根偏近日，布葉乍迎春。","秀質方含翠，清陰欲庇人。","輕雲度斜景，多露滴行塵。","褭褭堪離贈，依依獨望頻。","王孫如可賞，攀折在芳辰。"]', '["御苑陽和早，章溝柳色新。","託根偏近日，布葉乍迎春。","秀質方含翠，清陰欲庇人。","轻云度斜景，多露滴行塵。","褭褭堪離贈，依依独望頻。","王孫如可賞，攀折在芳辰。"]', '诗', 'shi', '', NULL, '御溝新柳 賈稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92cfdebd-aee0-4974-8a58-7471eec4f11e', '御溝新柳', '御溝新柳', 'd8e3f764-96ef-4edb-a123-b79113743273', '唐', '["韶光先禁柳，幾處覆溝新。","映水疑分翠，含煙欲占春。","悠悠遲日晚，褭褭好風頻。","吐節茸猶嫩，通條澤稍均。","遠和瑤草色，暗拂玉樓塵。","願假騫飛便，歸棲及此辰。"]', '["韶光先禁柳，幾处覆溝新。","映水疑分翠，含煙欲占春。","悠悠遲日晚，褭褭好风頻。","吐節茸猶嫩，通條澤稍均。","远和瑤草色，暗拂玉楼塵。","願假騫飞便，归棲及此辰。"]', '诗', 'shi', '', NULL, '御溝新柳 劉遵古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2fb093-b148-4321-9a22-dcc07ff38680', '洛陽清明日雨霽', '洛陽清明日雨霽', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["曉日清明天，夜來嵩少雨。","千門尚煙火，九陌無塵土。","酒綠河橋春，漏閑宮殿午。","遊人戀芳草，半犯嚴城鼓。"]', '["晓日清明天，夜来嵩少雨。","千门尚煙火，九陌無塵土。","酒綠河橋春，漏闲宮殿午。","游人戀芳草，半犯嚴城鼓。"]', '诗', 'shi', '', NULL, '洛陽清明日雨霽 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1956d4c-ddf4-4319-be2c-0d5bd34e84b4', '詠露', '詠露', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["霏霏靈液重，雲表無聲落。","霑樹急玄蟬，灑池棲皓鶴。","流塵清遠陌，飛月澄高閣。","宵潤玉堂簾，曙寒金井索。","佳人比珠淚，坐感紅綃薄。"]', '["霏霏靈液重，云表無声落。","霑樹急玄蟬，灑池棲皓鹤。","流塵清远陌，飞月澄高閣。","宵潤玉堂簾，曙寒金井索。","佳人比珠泪，坐感紅綃薄。"]', '诗', 'shi', '', NULL, '詠露 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c89814-2b61-4d20-be11-98ba356bf244', '夏遊招隱寺暴雨晚晴', '夏游招隐寺暴雨晚晴', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["竹柏風雨過，蕭疎臺殿涼。","石渠寫奔溜，金剎照頹陽。","鶴飛巖煙碧，鹿鳴澗草香。","山僧引清梵，幡蓋繞迴廊。"]', '["竹柏风雨過，蕭疎台殿涼。","石渠寫奔溜，金剎照頹陽。","鹤飞巖煙碧，鹿鳴澗草香。","山僧引清梵，幡蓋繞迴廊。"]', '诗', 'shi', '', NULL, '夏遊招隱寺暴雨晚晴 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df4bc9cb-7d7b-45d7-96f4-ad157f39ac3a', '禪門寺暮鐘', '禪门寺暮鐘', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["簨𥲤高懸于闐鐘，黃昏發地殷龍宮。","遊人憶到嵩山夜，疊閣連樓倚太空。"]', '["簨𥲤高懸于闐鐘，黄昏發地殷龙宮。","游人憶到嵩山夜，叠閣連楼倚太空。"]', '诗', 'shi', '', NULL, '禪門寺暮鐘 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e76f468-b3a7-49ce-8d15-d9c83f589209', '貢院樓北新栽小松', '貢院楼北新栽小松', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["青蒼初得地，華省植來新。","尚帶山中色，猶含洞裏春。","近樓依北戶，隱砌淨遊塵。","鶴壽應成蓋，龍形未有鱗。","爲梁資大廈，封爵恥嬴秦。","幸此觀光日，清風屢得親。"]', '["青蒼初得地，华省植来新。","尚带山中色，猶含洞裏春。","近楼依北戶，隐砌淨游塵。","鹤壽應成蓋，龙形未有鱗。","爲梁資大廈，封爵恥嬴秦。","幸此观光日，清风屢得親。"]', '诗', 'shi', '', NULL, '貢院樓北新栽小松 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2252b33d-7087-4c95-a17c-df14bb749eb4', '南至隔仗望含元殿香爐', '南至隔仗望含元殿香爐', 'f447ffab-973f-42ba-ac41-e8fcc647ffdb', '唐', '["千官望長至，萬國拜含元。","隔仗爐光出，浮霜煙氣翻。","飄飄縈內殿，漠漠澹前軒。","聖日開如捧，卿雲近欲渾。","輪囷灑宮闕，蕭索散乾坤。","願倚天風便，披香奉至尊。"]', '["千官望长至，万国拜含元。","隔仗爐光出，浮霜煙氣翻。","飄飄縈內殿，漠漠澹前軒。","聖日开如捧，卿云近欲渾。","輪囷灑宮闕，蕭索散乾坤。","願倚天风便，披香奉至尊。"]', '诗', 'shi', '', NULL, '南至隔仗望含元殿香爐 崔立之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9ed607-5da1-4d4f-beef-3bb225f92093', '曲池潔寒流', '曲池潔寒流', 'f447ffab-973f-42ba-ac41-e8fcc647ffdb', '唐', '["閑尋欹岸步，因向曲池看。","透底何澄徹，迴流乍屈盤。","稍隨高樹古，迥與遠天寒。","月入鏡華轉，星臨珠影攢。","纖鱗時蔽石，轉吹或生瀾。","願假涓微效，來濡拙筆端。"]', '["闲尋欹岸步，因向曲池看。","透底何澄徹，迴流乍屈盤。","稍隨高樹古，迥與远天寒。","月入镜华轉，星臨珠影攢。","纖鱗时蔽石，轉吹或生瀾。","願假涓微效，来濡拙笔端。"]', '诗', 'shi', '', NULL, '曲池潔寒流 崔立之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f4ea24-e884-46cd-9ed3-4e738e28eb92', '賦得春風扇微和', '賦得春风扇微和', 'f447ffab-973f-42ba-ac41-e8fcc647ffdb', '唐', '["時令忽已變，年光俄又春。","高低惠風入，遠近芳氣新。","靡靡纔偃草，泠泠不動塵。","溫和乍扇物，煦嫗偏感人。","去出桂林漫，來過蕙圃頻。","晨輝正澹蕩，披拂長相親。"]', '["时令忽已变，年光俄又春。","高低惠风入，远近芳氣新。","靡靡纔偃草，泠泠不动塵。","溫和乍扇物，煦嫗偏感人。","去出桂林漫，来過蕙圃頻。","晨輝正澹蕩，披拂长相親。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 崔立之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b82e073-dbfd-4e9c-bc7a-f187032b9304', '南至日隔仗望含元殿香爐', '南至日隔仗望含元殿香爐', 'c5a42ffd-c3f0-4fff-b42e-05e6c650d3dc', '唐', '["冕旒親負扆，卉服盡朝天。","暘谷移初日，金爐出御煙。","芬馨流遠近，散漫入貂蟬。","霜仗凝逾白，朱欄映轉鮮。","如看浮闕在，稍覺逐風遷。","爲沐皇家慶，來瞻羽衛前。"]', '["冕旒親負扆，卉服尽朝天。","暘谷移初日，金爐出御煙。","芬馨流远近，散漫入貂蟬。","霜仗凝逾白，朱欄映轉鲜。","如看浮闕在，稍覺逐风遷。","爲沐皇家慶，来瞻羽衛前。"]', '诗', 'shi', '', NULL, '南至日隔仗望含元殿香爐 郭遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ffd773-6a24-46b5-b689-be27ea626d02', '賦得春風扇微和', '賦得春风扇微和', 'c5a42ffd-c3f0-4fff-b42e-05e6c650d3dc', '唐', '["微風飄淑氣，散漫及茲晨。","習習何處至，熙熙與春親。","曖空看早辨，映日度逾頻。","高拂非煙雜，低垂衆卉新。","霽天輕有靄，綺陌盡無塵。","還似登臺意，元和欲煦人。"]', '["微风飄淑氣，散漫及茲晨。","習習何处至，熙熙與春親。","曖空看早辨，映日度逾頻。","高拂非煙杂，低垂衆卉新。","霽天轻有靄，綺陌尽無塵。","還似登台意，元和欲煦人。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 郭遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7d1083-d5c9-425f-9b47-b89acfd2ef9c', '賦得風動萬年枝', '賦得风动万年枝', 'a8ada4e9-f4fe-4193-84f1-d11c90ca2286', '唐', '["嘉名標萬祀，擢秀出深宮。","嫩葉含煙靄，芳柯振惠風。","參差搖翠色，綺靡舞晴空。","氣稟禎祥異，榮霑雨露同。","天年方未極，聖壽比應崇。","幸列華林裏，知殊衆木中。"]', '["嘉名標万祀，擢秀出深宮。","嫩葉含煙靄，芳柯振惠风。","參差搖翠色，綺靡舞晴空。","氣稟禎祥異，榮霑雨露同。","天年方未極，聖壽比應崇。","幸列华林裏，知殊衆木中。"]', '诗', 'shi', '', NULL, '賦得風動萬年枝 韋紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a5ee012-5f28-4729-9ce8-0825ffdfb77f', '賦得風動萬年枝', '賦得风动万年枝', '2ce25822-aecf-4620-b0c3-cf62f7191ecb', '唐', '["珍木羅前殿，乘春任好風。","振柯方褭褭，舒葉乍濛濛。","影動丹墀上，聲傳紫禁中。","離披偏向日，凌亂半分空。","輕拂祥煙散，低搖翠色同。","長令占天眷，四氣借全功。"]', '["珍木羅前殿，乘春任好风。","振柯方褭褭，舒葉乍濛濛。","影动丹墀上，声傳紫禁中。","離披偏向日，凌亂半分空。","轻拂祥煙散，低搖翠色同。","长令占天眷，四氣借全功。"]', '诗', 'shi', '', NULL, '賦得風動萬年枝 樊陽源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4980291e-c2e1-4813-ac37-2ef1d7783be8', '賦得風動萬年枝', '賦得风动万年枝', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["瓊樹偏春早，光飛處處宜。","曉浮三殿日，暗度萬年枝。","婀娜搖仙禁，繽翻映玉池。","含芳煙乍和，拂砌影初移。","爲近韶陽煦，皆先衆卉垂。","成陰知可待，不與衆芳隨。"]', '["瓊樹偏春早，光飞处处宜。","晓浮三殿日，暗度万年枝。","婀娜搖仙禁，繽翻映玉池。","含芳煙乍和，拂砌影初移。","爲近韶陽煦，皆先衆卉垂。","成陰知可待，不與衆芳隨。"]', '诗', 'shi', '', NULL, '賦得風動萬年枝 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1f05e4-cb3d-4102-bc6b-712bbdd45261', '閏月定四時', '閏月定四时', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["玉律窮三紀，推爲積閏期。","月餘因妙算，歲遍自成時。","乍覺年華改，翻憐物候遲。","六旬知不惑，四氣本無欺。","月桂虧還正，階蓂落復滋。","從斯分曆象，共仰定毫釐。"]', '["玉律窮三紀，推爲積閏期。","月餘因妙算，歲遍自成时。","乍覺年华改，翻怜物候遲。","六旬知不惑，四氣本無欺。","月桂虧還正，階蓂落复滋。","從斯分曆象，共仰定毫釐。"]', '诗', 'shi', '', NULL, '閏月定四時 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37913ab2-eb18-4641-ad0d-482c67481b1d', '謝真人還舊山', '謝真人還旧山', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["麾蓋從仙府，笙歌入舊山。","水流丹竈缺，雲起草堂關。","白鹿行爲衛，青鸞舞自閑。","種松鱗未立，移石蘚仍斑。","望路煙霞外，迴輿巖岫間。","豈唯遼海鶴，空歎令威還。"]', '["麾蓋從仙府，笙歌入旧山。","水流丹竈缺，云起草堂关。","白鹿行爲衛，青鸾舞自闲。","種松鱗未立，移石蘚仍斑。","望路煙霞外，迴輿巖岫间。","豈唯遼海鹤，空歎令威還。"]', '诗', 'shi', '', NULL, '謝真人還舊山 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0742d32-6da9-436e-993c-1b6bda3211bf', '范成君撃洞陰磬', '范成君撃洞陰磬', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["歷歷聞金奏，微微下玉京。","爲祥家諜久，偏識洞陰名。","澹佇人聞聽，鏗鏘古曲成。","何須百獸舞，自暢九天情。","注目看無見，留心記未精。","雲霄如可托，借鶴向層城。"]', '["歷歷闻金奏，微微下玉京。","爲祥家諜久，偏識洞陰名。","澹佇人闻听，鏗鏘古曲成。","何須百獸舞，自暢九天情。","注目看無见，留心記未精。","云霄如可托，借鹤向層城。"]', '诗', 'shi', '', NULL, '范成君撃洞陰磬 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7154a5db-41bc-4df9-922b-e904b3bbafc2', '賦得春風扇微和', '賦得春风扇微和', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["曖曖當遲日，微微扇好風。","吹搖新葉上，光動淺花中。","澹蕩凝清晝，氤氳曖碧空。","稍看生綠水，已覺散芳叢。","徙倚情偏適，裴回賞未窮。","妍華不可狀，竟夕氣融融。"]', '["曖曖當遲日，微微扇好风。","吹搖新葉上，光动淺花中。","澹蕩凝清晝，氤氳曖碧空。","稍看生綠水，已覺散芳叢。","徙倚情偏適，裴回賞未窮。","妍华不可狀，竟夕氣融融。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b287e0db-32ab-4568-b439-41640dc329ae', '賦得春風扇微和', '賦得春风扇微和', 'c4ee8c48-1899-4966-89ab-545d4730b26f', '唐', '["春晴生縹緲，軟吹和初徧。","池影動淵淪，山容發蔥蒨。","遲遲入綺閣，習習流芳甸。","樹杪颺鶯啼，階前落花片。","韶光恐閑放，旭日宜游宴。","文客拂塵衣，仁風願迴扇。"]', '["春晴生縹緲，軟吹和初徧。","池影动淵淪，山容發蔥蒨。","遲遲入綺閣，習習流芳甸。","樹杪颺鶯啼，階前落花片。","韶光恐闲放，旭日宜游宴。","文客拂塵衣，仁风願迴扇。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 豆盧榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d631b56a-25d8-4561-8bf3-25cfbc823e4a', '賦得春風扇微和', '賦得春风扇微和', '40cfb9de-afe9-4308-a2a7-6dbfe8d9cccf', '唐', '["微風扇和氣，韶景共芳晨。","始見郊原綠，旋過御苑春。","三條開廣陌，八水泛通津。","煙動花間葉，香流馬上人。","逶迤雲彩曙，嘹唳鳥聲頻。","爲報東堂客，明朝桂樹新。"]', '["微风扇和氣，韶景共芳晨。","始见郊原綠，旋過御苑春。","三條开廣陌，八水泛通津。","煙动花间葉，香流马上人。","逶迤云彩曙，嘹唳鸟声頻。","爲報东堂客，明朝桂樹新。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 邵偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c79dfa-3ac9-4afc-ba7a-4655ce481c89', '賦得春風扇微和', '賦得春风扇微和', 'c985e263-7a03-4770-9634-eeb733ffafe3', '唐', '["青陽初入律，淑氣應春風。","始辨梅花裏，俄分柳色中。","依微開夕照，澹蕩媚晴空。","拂水生蘋末，經巖觸桂叢。","稍抽蘭葉紫，微吐杏花紅。","願逐仁風布，將俾生植功。"]', '["青陽初入律，淑氣應春风。","始辨梅花裏，俄分柳色中。","依微开夕照，澹蕩媚晴空。","拂水生蘋末，經巖觸桂叢。","稍抽蘭葉紫，微吐杏花紅。","願逐仁风布，將俾生植功。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 柳道倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adece3fe-ce58-4106-b748-37624f2c1d5b', '賦得春風扇微和', '賦得春风扇微和', '69312cf0-f120-4a58-8f85-9047c29a8e17', '唐', '["喜見陽和至，遙知橐籥功。","遲遲散南陌，褭褭逐東風。","暗入芳園裏，潛吹草木中。","蘭蓀纔有綠，桃杏未成紅。","已覺寒光盡，還看淑氣通。","由來榮與悴，今日發應同。"]', '["喜见陽和至，遙知橐籥功。","遲遲散南陌，褭褭逐东风。","暗入芳园裏，潛吹草木中。","蘭蓀纔有綠，桃杏未成紅。","已覺寒光尽，還看淑氣通。","由来榮與悴，今日發應同。"]', '诗', 'shi', '', NULL, '賦得春風扇微和 陳九流 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf23ee0-203d-453f-867b-84ded73ac2e0', '謝真人仙駕還舊山', '謝真人仙駕還旧山', '75132b51-8f4d-4721-ae3c-93f1fa4995c9', '唐', '["何年成道去，綽約化童顏。","天上辭仙侶，人間憶舊山。","滄桑今已變，蘿蔓尚堪攀。","雲覆瑤壇淨，苔生丹竈閑。","逍遙堪白石，寂寞閉玄關。","應是悲塵世，思將羽駕還。"]', '["何年成道去，綽約化童顏。","天上辞仙侶，人间憶旧山。","滄桑今已变，蘿蔓尚堪攀。","云覆瑤壇淨，苔生丹竈闲。","逍遙堪白石，寂寞閉玄关。","應是悲塵世，思將羽駕還。"]', '诗', 'shi', '', NULL, '謝真人仙駕還舊山 夏方慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3a0afc-c631-45ef-b15e-096d5c9cd40b', '公子行', '公子行', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["金羈白面郎，何處蹋青來。","馬嬌郎半醉，躞蹀望樓臺。","似見樓上人，玲瓏窗戶開。","隔花聞一笑，落日不知回。"]', '["金羈白面郎，何处蹋青来。","马嬌郎半醉，躞蹀望楼台。","似见楼上人，玲瓏窗戶开。","隔花闻一笑，落日不知回。"]', '诗', 'shi', '', NULL, '公子行 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72e2e68-150e-486e-a538-38dd5a66f2aa', '古意', '古意', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["十三學繡羅衣裳，自憐紅袖聞馨香。","人言此是嫁時服，含笑不刺雙鴛鴦。","郎年十九髭未生，拜官天下聞郎名。","車馬駢闐賀門館，自然不失爲公卿。","是時妾家猶未貧，兄弟出入雙車輪。","繁華全盛兩相敵，與郎年少爲婚姻。","郎家居近御溝水，豪門客盡躡珠履。","雕盤酒器常不干，曉入中廚妾先起。","姑嫜嚴肅有規矩，小姑嬌憨意難取。","朝參暮拜白玉堂，繡衣著盡黃金縷。","妾貌漸衰郎漸薄，時時強笑意索寞。","知郎本來無歲寒，幾回掩淚看花落。","妾年四十絲滿頭，郎年五十封公侯。","男兒全盛日忘舊，銀牀羽帳空颼飀。","庭花紅遍蝴蝶飛，看郎佩玉下朝時。","歸來略略不相顧，却令侍婢生光輝。","郎恨婦人易衰老，妾亦恨深不忍道。","看郎強健能幾時，年過六十還枯[槁]。"]', '["十三学繡羅衣裳，自怜紅袖闻馨香。","人言此是嫁时服，含笑不刺雙鴛鴦。","郎年十九髭未生，拜官天下闻郎名。","车马駢闐賀门館，自然不失爲公卿。","是时妾家猶未貧，兄弟出入雙车輪。","繁华全盛兩相敵，與郎年少爲婚姻。","郎家居近御溝水，豪门客尽躡珠履。","雕盤酒器常不干，晓入中廚妾先起。","姑嫜嚴肅有規矩，小姑嬌憨意难取。","朝參暮拜白玉堂，繡衣著尽黄金縷。","妾貌漸衰郎漸薄，时时強笑意索寞。","知郎本来無歲寒，幾回掩泪看花落。","妾年四十絲满头，郎年五十封公侯。","男兒全盛日忘旧，銀牀羽帳空颼飀。","庭花紅遍蝴蝶飞，看郎佩玉下朝时。","归来略略不相顧，却令侍婢生光輝。","郎恨婦人易衰老，妾亦恨深不忍道。","看郎強健能幾时，年過六十還枯[槁]。"]', '诗', 'shi', '', NULL, '古意 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2af986-90f5-4aa2-a182-4ca643dc9649', '長相思', '长相思', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["相思長相思，相思無限極。","相思苦相思，相思損容色。","容色真可惜，相思不可徹。","日日長相思，相思腸斷絕。","腸斷絕，淚還續，閑人莫作相思曲。"]', '["相思长相思，相思無限極。","相思苦相思，相思損容色。","容色真可惜，相思不可徹。","日日长相思，相思腸斷絕。","腸斷絕，泪還續，闲人莫作相思曲。"]', '诗', 'shi', '', NULL, '長相思 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1270c8-1e48-4402-8221-804a30a8f444', '送戴端公赴容州', '送戴端公赴容州', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["分命諸侯重，葳蕤繡服香。","八蠻治險阻，千騎蹋繁霜。","山斷旌旗出，天晴劒珮光。","還將小戴禮，遠出化南方。"]', '["分命諸侯重，葳蕤繡服香。","八蠻治險阻，千騎蹋繁霜。","山斷旌旗出，天晴劒珮光。","還將小戴禮，远出化南方。"]', '诗', 'shi', '', NULL, '送戴端公赴容州 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a43df9d-01dc-4b80-8e23-8753b717b151', '送殷華之洪州', '送殷华之洪州', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["離堂悲楚調，君奏豫章行。","愁處雪花白，夢中江水清。","扣船歌月色，避浪宿猨聲。","還作經年別，相思湖草生。"]', '["離堂悲楚調，君奏豫章行。","愁处雪花白，梦中江水清。","扣船歌月色，避浪宿猨声。","還作經年別，相思湖草生。"]', '诗', 'shi', '', NULL, '送殷華之洪州 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae70026-7725-46c4-b055-52e65929534d', '春日晴原野望', '春日晴原野望', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["東風吹煖氣，消散入晴天。","漸變池塘色，欲生楊柳煙。","蒙茸花向月，潦倒客經年。","鄉思應愁望，江湖春水連。"]', '["东风吹煖氣，消散入晴天。","漸变池塘色，欲生楊柳煙。","蒙茸花向月，潦倒客經年。","乡思應愁望，江湖春水連。"]', '诗', 'shi', '', NULL, '春日晴原野望 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56cf6555-4f70-4397-a1eb-237e0c3ce4f6', '湘妃怨', '湘妃怨', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["舜欲省蠻陬，南巡非逸游。","九山沈白日，二女泣滄洲。","目極楚雲斷，恨連湘水流。","至今聞鼓瑟，咽絕不勝愁。"]', '["舜欲省蠻陬，南巡非逸游。","九山沈白日，二女泣滄洲。","目極楚云斷，恨連湘水流。","至今闻鼓瑟，咽絕不勝愁。"]', '诗', 'shi', '', NULL, '湘妃怨 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22efc969-6c59-4708-a2f7-3d91fd7a9ab6', '冬晚送友人使西蕃', '冬晚送友人使西蕃', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["驛使向天西，巡羌復入氐。","玉關晴有雪，砂磧雨無泥。","落淚軍中笛，驚眠塞上雞。","逢春鄉思苦，萬里草萋萋。"]', '["驛使向天西，巡羌复入氐。","玉关晴有雪，砂磧雨無泥。","落泪軍中笛，驚眠塞上雞。","逢春乡思苦，万里草萋萋。"]', '诗', 'shi', '', NULL, '冬晚送友人使西蕃 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8063912-f95b-43d2-b92a-4940991cac94', '春園即事', '春园即事', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["水隔羣物遠，夜深風起頻。","霜中千樹橘，月下五湖人。","聽鶴忽忘寢，見山如得鄰。","明年還到此，共看洞庭春。"]', '["水隔羣物远，夜深风起頻。","霜中千樹橘，月下五湖人。","听鹤忽忘寢，见山如得鄰。","明年還到此，共看洞庭春。"]', '诗', 'shi', '', NULL, '春園即事 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79290dfd-c53b-4dae-8064-9b94a007ddae', '送友人及第歸江東', '送友人及第归江东', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["五陵春色泛花枝，心醉花前遠別離。","落羽耻爲關右客，成名空羨里中兒。","都門雨歇愁分處，山店燈殘夢到時。","家住洞庭多釣伴，因來相賀話相思。"]', '["五陵春色泛花枝，心醉花前远別離。","落羽耻爲关右客，成名空羨里中兒。","都门雨歇愁分处，山店灯殘梦到时。","家住洞庭多釣伴，因来相賀話相思。"]', '诗', 'shi', '', NULL, '送友人及第歸江東 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c4819b-d884-485c-b1fa-03d5717c8d9a', '梓州與溫商夜別', '梓州與溫商夜別', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["鳳皇城裏花時別，客舍莫辭先買酒，相門曾忝共登龍。","迎風騷屑千家竹，隔水悠揚午夜鐘。","明日又行西蜀路，不堪天際遠山重。"]', '["鳳皇城裏花时別，客舍莫辞先買酒，相门曾忝共登龙。","迎风騷屑千家竹，隔水悠揚午夜鐘。","明日又行西蜀路，不堪天際远山重。"]', '诗', 'shi', '', NULL, '梓州與溫商夜別 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b5b719-f5cd-49f1-b533-6d28299b3534', '長安臥病秋夜言懷', '长安臥病秋夜言懷', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["九重門鎖禁城秋，月過南宮漸映樓。","紫陌夜深槐露滴，碧空雲盡火星流。","風清刻漏傳三殿，甲第歌鐘樂五侯。","楚客病來鄉思苦，寂寥燈下不勝愁。"]', '["九重门鎖禁城秋，月過南宮漸映楼。","紫陌夜深槐露滴，碧空云尽火星流。","风清刻漏傳三殿，甲第歌鐘乐五侯。","楚客病来乡思苦，寂寥灯下不勝愁。"]', '诗', 'shi', '', NULL, '長安臥病秋夜言懷 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b9e9b5-d633-40f2-b865-9c5cbb339550', '喜雪上竇相公', '喜雪上竇相公', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["千門萬戶雪花浮，點點無聲落瓦溝。","全似玉塵銷更積，半成冰水結還流。","光添曙色連天遠，平地已沾盈尺潤，年豐須荷富人侯。"]', '["千门万戶雪花浮，点点無声落瓦溝。","全似玉塵銷更積，半成冰水結還流。","光添曙色連天远，平地已沾盈尺潤，年豐須荷富人侯。"]', '诗', 'shi', '', NULL, '喜雪上竇相公 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3fed01c-2525-4489-a7c4-dd9739239efb', '宴楊駙馬山亭', '宴楊駙马山亭', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["垂楊拂岸草茸茸，繡戶窗前花影重。","鱠下玉盤紅縷細，酒開金甕綠醅醲。","中朝附馬何平叔，南國詞人陸士龍。","落日泛舟同醉處，迴潭百丈映千峯。"]', '["垂楊拂岸草茸茸，繡戶窗前花影重。","鱠下玉盤紅縷細，酒开金甕綠醅醲。","中朝附马何平叔，南国词人陸士龙。","落日泛舟同醉处，迴潭百丈映千峯。"]', '诗', 'shi', '', NULL, '宴楊駙馬山亭 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9bf1fcf-9377-47b0-b837-81e9c1d1c0f7', '西蜀送許中庸歸秦赴舉', '西蜀送許中庸归秦赴舉', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["春色華陽國，秦人此別離。","驛樓橫水影，鄉路入花枝。","日暖鶯飛好，山晴馬去遲。","劒門當石隘，棧閣入雲危。","獨鶴心千里，貧交酒一巵。","桂條攀偃蹇，蘭葉藉參差。","旅夢驚蝴蝶，殘芳怨子規。","碧霄今夜月，惆悵上峨嵋。"]', '["春色华陽国，秦人此別離。","驛楼橫水影，乡路入花枝。","日暖鶯飞好，山晴马去遲。","劒门當石隘，棧閣入云危。","独鹤心千里，貧交酒一巵。","桂條攀偃蹇，蘭葉藉參差。","旅梦驚蝴蝶，殘芳怨子規。","碧霄今夜月，惆悵上峨嵋。"]', '诗', 'shi', '', NULL, '西蜀送許中庸歸秦赴舉 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7bd85f-5a12-4ede-9bcf-12fe909e7405', '小苑春望宮池柳色', '小苑春望宮池柳色', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["宛宛如絲柳，含黃一望新。","未成溝上暗，且向日邊春。","嫋娜方遮水，低迷欲醉人。","託空芳鬱鬱，逐溜影鱗鱗。","弄水滋宵露，垂枝染夕塵。","夾堤連太液，還似映天津。"]', '["宛宛如絲柳，含黄一望新。","未成溝上暗，且向日邊春。","嫋娜方遮水，低迷欲醉人。","託空芳鬱鬱，逐溜影鱗鱗。","弄水滋宵露，垂枝染夕塵。","夾堤連太液，還似映天津。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db8d3e0-6dba-4d3f-93e1-5597b9c971b1', '中秋夜臨鏡湖望月', '中秋夜臨镜湖望月', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["鏡裏秋宵望，湖平月彩深。","圓光珠入浦，浮照鵲驚林。","澹動光還碎，嬋娟影不沈。","遠時生岸曲，空處落波心。","逈徹輪初滿，孤明魄未侵。","桂枝如可折，何惜夜登臨。"]', '["镜裏秋宵望，湖平月彩深。","圓光珠入浦，浮照鵲驚林。","澹动光還碎，嬋娟影不沈。","远时生岸曲，空处落波心。","逈徹輪初满，孤明魄未侵。","桂枝如可折，何惜夜登臨。"]', '诗', 'shi', '', NULL, '中秋夜臨鏡湖望月 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a953cb5-26cf-4e66-847b-c3b1e867afdc', '江上愁思二首 一', '江上愁思二首 一', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["江上翁開門，開門向衰草。","只知愁子孫，不覺生涯老。"]', '["江上翁开门，开门向衰草。","只知愁子孫，不覺生涯老。"]', '诗', 'shi', '', NULL, '江上愁思二首 一 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('665ce408-8b52-4d03-babc-416e522be0fd', '江上愁思二首 二', '江上愁思二首 二', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["江上草莖枯，莖枯葉復焦。","那堪芳意盡，夜夜沒寒潮。"]', '["江上草莖枯，莖枯葉复焦。","那堪芳意尽，夜夜沒寒潮。"]', '诗', 'shi', '', NULL, '江上愁思二首 二 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e03011-2685-4e63-89f6-df489e1fca0f', '梁城老人怨', '梁城老人怨', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["朝爲耕種人，暮作刀槍鬼。","相看父子血，共染城濠水。"]', '["朝爲耕種人，暮作刀槍鬼。","相看父子血，共染城濠水。"]', '诗', 'shi', '', NULL, '梁城老人怨 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81408fc9-9fb4-42c8-a956-b8a5ac3ea9b0', '送靈一上人', '送靈一上人', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["十年勞遠別，一笑喜相逢。","又上青山去，青山千萬重。"]', '["十年勞远別，一笑喜相逢。","又上青山去，青山千万重。"]', '诗', 'shi', '', NULL, '送靈一上人 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f03c2e9-b5da-4437-9db7-6d93d9fb104f', '經夫差廟', '經夫差廟', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["姑蘇城畔千年木，刻作夫差廟裏神。","冠蓋寂寥塵滿室，不知簫鼓樂何人。"]', '["姑蘇城畔千年木，刻作夫差廟裏神。","冠蓋寂寥塵满室，不知簫鼓乐何人。"]', '诗', 'shi', '', NULL, '經夫差廟 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1258066e-c005-43f1-807c-91c5de1cce61', '九月十日即事', '九月十日即事', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["漢江天外東流去，巴塞連山萬里秋。","節過重陽人病起，一枝殘菊不勝愁。"]', '["漢江天外东流去，巴塞連山万里秋。","節過重陽人病起，一枝殘菊不勝愁。"]', '诗', 'shi', '', NULL, '九月十日即事 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a194cf22-2ec6-4dae-80d1-369fd2cf83b4', '夏日讌九華池贈主人', '夏日讌九华池贈主人', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["池上涼臺五月涼，百花開盡水芝香。","黃金買酒邀詩客，醉倒檐前青玉牀。"]', '["池上涼台五月涼，百花开尽水芝香。","黄金買酒邀诗客，醉倒檐前青玉牀。"]', '诗', 'shi', '', NULL, '夏日讌九華池贈主人 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a94796e-39fc-4799-a98c-0070900ac25b', '長安早春言志', '长安早春言志', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["九衢日暖樹蒼蒼，萬里吳人憶水鄉。","漢主未曾親羽獵，不知將底諫君王。"]', '["九衢日暖樹蒼蒼，万里吳人憶水乡。","漢主未曾親羽獵，不知將底諫君王。"]', '诗', 'shi', '', NULL, '長安早春言志 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('230d114f-9f9d-4993-b1bb-affb2f1a0941', '讀蘇屬國傳', '读蘇屬国傳', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["天山西北居延海，沙塞重重不見春。","腸斷帝鄉遙望日，節旄零落漢家臣。"]', '["天山西北居延海，沙塞重重不见春。","腸斷帝乡遙望日，節旄零落漢家臣。"]', '诗', 'shi', '', NULL, '讀蘇屬國傳 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48100fde-672c-4a27-a6ef-ee8461a1a907', '吳城覽古', '吳城覽古', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["吳王舊國水煙空，香徑無人蘭葉紅。","春色似憐歌舞地，年年先發館娃宮。"]', '["吳王旧国水煙空，香徑無人蘭葉紅。","春色似怜歌舞地，年年先發館娃宮。"]', '诗', 'shi', '', NULL, '吳城覽古 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa02b064-d182-4403-b0bc-18dda2fc0a8a', '犍爲城下夜泊聞夷歌', '犍爲城下夜泊闻夷歌', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["犍爲城下牂牁路，空冢灘西賈客舟。","此夜可憐江上月，夷歌銅鼓不勝愁。"]', '["犍爲城下牂牁路，空冢灘西賈客舟。","此夜可怜江上月，夷歌銅鼓不勝愁。"]', '诗', 'shi', '', NULL, '犍爲城下夜泊聞夷歌 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ee2518c-583b-4124-abe9-9ff8b9f708d2', '和王中丞使君春日過高評事幽居', '和王中丞使君春日過高評事幽居', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["風光滿路旗旛出，林下高人待使君。","笑藉紫蘭相向醉，野花千樹落紛紛。"]', '["风光满路旗旛出，林下高人待使君。","笑藉紫蘭相向醉，野花千樹落紛紛。"]', '诗', 'shi', '', NULL, '和王中丞使君春日過高評事幽居 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('081fd5e7-8e05-4fe8-ad1e-82857bc17613', '和王中丞中和日', '和王中丞中和日', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["節應中和天地晴，繁弦疊鼓動高城。","漢家分刺諸侯貴，一曲陽春江水清。"]', '["節應中和天地晴，繁弦叠鼓动高城。","漢家分刺諸侯貴，一曲陽春江水清。"]', '诗', 'shi', '', NULL, '和王中丞中和日 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67715f49-df41-4375-b1f1-148780e32e07', '同韋中丞花下夜飲贈歌人', '同韋中丞花下夜饮贈歌人', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["銀燭煌煌半醉人，嬌歌宛轉動朱脣。","繁花落盡春風裏，繡被郎官不負春。"]', '["銀燭煌煌半醉人，嬌歌宛轉动朱脣。","繁花落尽春风裏，繡被郎官不負春。"]', '诗', 'shi', '', NULL, '同韋中丞花下夜飲贈歌人 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401da5a6-f506-4a31-86f5-8ac780cd84d6', '若耶溪逢陸澧', '若耶溪逢陸澧', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["溪上春晴聊看竹，誰言驛使此相逢。","擔簦躡屐仍多病，笑殺雲間陸士龍。"]', '["溪上春晴聊看竹，誰言驛使此相逢。","擔簦躡屐仍多病，笑殺云间陸士龙。"]', '诗', 'shi', '', NULL, '若耶溪逢陸澧 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdddde1-10b7-4ead-9c84-649bf6bb3bdc', '夜泊荆溪', '夜泊荆溪', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["小雪已晴蘆葉暗，長波乍急鶴聲嘶。","孤舟一夜宿流水，眼看山頭月落溪。"]', '["小雪已晴蘆葉暗，长波乍急鹤声嘶。","孤舟一夜宿流水，眼看山头月落溪。"]', '诗', 'shi', '', NULL, '夜泊荆溪 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d53cea-56b6-4fec-9798-3b88133562b5', '南山別僧', '南山別僧', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["惆悵人間多別離，梅花滿眼獨行時。","無家度日多爲客，欲共山僧何處期。"]', '["惆悵人间多別離，梅花满眼独行时。","無家度日多爲客，欲共山僧何处期。"]', '诗', 'shi', '', NULL, '南山別僧 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dece1bbc-2959-43a1-93e2-cb34a168865e', '戲題山居二首 一', '戲題山居二首 一', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["雲蓋秋松幽洞近，水穿危石亂山深。","門前自有千竿竹，免向人家看竹林。"]', '["云蓋秋松幽洞近，水穿危石亂山深。","门前自有千竿竹，免向人家看竹林。"]', '诗', 'shi', '', NULL, '戲題山居二首 一 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d4891b-ebb7-45c4-aa7c-2ae11329e972', '戲題山居二首 二', '戲題山居二首 二', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["雖有柴門長不關，片雲高木共身閑。","猶嫌住久人知處，見欲移居更上山。"]', '["雖有柴门长不关，片云高木共身闲。","猶嫌住久人知处，见欲移居更上山。"]', '诗', 'shi', '', NULL, '戲題山居二首 二 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9853d70-f4eb-4b7a-9f01-23903dcbb5c5', '山中秋夜喜周士閑見過', '山中秋夜喜周士闲见過', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["青山高處上不易，白雲深處行亦難。","留君不宿對秋月，莫厭山空泉石寒。"]', '["青山高处上不易，白云深处行亦难。","留君不宿对秋月，莫厭山空泉石寒。"]', '诗', 'shi', '', NULL, '山中秋夜喜周士閑見過 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f98f94-f282-40b1-89a9-3518493fd3de', '過櫟陽山谿', '過櫟陽山谿', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["衆草穿沙芳色齊，蹋莎行草過春谿。","閑雲相引上山去，人到山頭雲却低。"]', '["衆草穿沙芳色齊，蹋莎行草過春谿。","闲云相引上山去，人到山头云却低。"]', '诗', 'shi', '', NULL, '過櫟陽山谿 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb8b33d-fcba-425b-bc93-30668dfd2836', '姑蘇臺懷古', '姑蘇台懷古', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["憶昔吳王爭霸日，歌鐘滿地上高臺。","三千宮女看花處，人盡臺崩花自開。"]', '["憶昔吳王爭霸日，歌鐘满地上高台。","三千宮女看花处，人尽台崩花自开。"]', '诗', 'shi', '', NULL, '姑蘇臺懷古 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8017660e-e1f1-401a-9821-9bf18198c29a', '將歸舊山留別', '將归旧山留別', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["相共遊梁今獨還，異鄉搖落憶空山。","信陵死後無公子，徒向夷門學抱關。"]', '["相共游梁今独還，異乡搖落憶空山。","信陵死後無公子，徒向夷门学抱关。"]', '诗', 'shi', '', NULL, '將歸舊山留別 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c979a6c-3eba-42d1-96a7-940be7220b77', '遊洞靈觀', '游洞靈观', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["初訪西城禮少君，獨行深入洞天雲。","風吹青桂寒花落，香繞仙壇處處聞。"]', '["初訪西城禮少君，独行深入洞天云。","风吹青桂寒花落，香繞仙壇处处闻。"]', '诗', 'shi', '', NULL, '遊洞靈觀 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d520e6-37ab-4d6f-a027-6cc092080c5d', '旅次沔陽聞克復而用師者窮兵黷武因書簡之', '旅次沔陽闻克复而用師者窮兵黷武因书簡之', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["江上煙消漢水清，王師大破綠林兵。","干戈用盡人成血，韓信空傳壯士名。"]', '["江上煙消漢水清，王師大破綠林兵。","干戈用尽人成血，韓信空傳壯士名。"]', '诗', 'shi', '', NULL, '旅次沔陽聞克復而用師者窮兵黷武因書簡之 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403fbd38-35c0-4c27-828a-bf6d8185ca4d', '湘君祠', '湘君祠', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["二妃怨處雲沈沈，二妃哭處湘水深。","商人酒滴廟前草，蕭索風生斑竹林。"]', '["二妃怨处云沈沈，二妃哭处湘水深。","商人酒滴廟前草，蕭索风生斑竹林。"]', '诗', 'shi', '', NULL, '湘君祠 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1692c313-e03e-4371-a5ce-29d96d95eed0', '送辛吉甫常州覲省', '送辛吉甫常州覲省', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["西去蘭陵家不遠，到家還及採蘭時。","新年送客我爲客，惆悵門前黃柳絲。"]', '["西去蘭陵家不远，到家還及採蘭时。","新年送客我爲客，惆悵门前黄柳絲。"]', '诗', 'shi', '', NULL, '送辛吉甫常州覲省 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8300d33-c1ec-4f8b-82c2-2b700aa3e8ba', '題舞花山大師遺居', '題舞花山大師遺居', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["西過流沙歸路長，一生遺迹在東方。","空堂寂寞閉燈影，風動四山松柏香。"]', '["西過流沙归路长，一生遺迹在东方。","空堂寂寞閉灯影，风动四山松柏香。"]', '诗', 'shi', '', NULL, '題舞花山大師遺居 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3806408c-e43f-4f4f-8fc2-8a539d74e807', '廣陵秋夜對月即事', '廣陵秋夜对月即事', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["霜落寒空月上樓，月中歌吹滿揚州。","相看醉舞倡樓月，不覺隋家陵樹秋。"]', '["霜落寒空月上楼，月中歌吹满揚州。","相看醉舞倡楼月，不覺隋家陵樹秋。"]', '诗', 'shi', '', NULL, '廣陵秋夜對月即事 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61e274f-b073-4b6a-a725-ce6072c15c95', '早秋滻水送人歸越', '早秋滻水送人归越', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["涼葉蕭蕭生遠風，曉鵶飛度望春宮。","越人歸去一搖首，腸斷馬嘶秋水東。"]', '["涼葉蕭蕭生远风，晓鵶飞度望春宮。","越人归去一搖首，腸斷马嘶秋水东。"]', '诗', 'shi', '', NULL, '早秋滻水送人歸越 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a642b1-e1a8-488a-9ac3-32b20223be4d', '小江驛送陸侍御歸湖上山', '小江驛送陸侍御归湖上山', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["鶴唳天邊秋水空，荻花蘆葉起西風。","今夜渡江何處宿，會稽山在月明中。"]', '["鹤唳天邊秋水空，荻花蘆葉起西风。","今夜渡江何处宿，會稽山在月明中。"]', '诗', 'shi', '', NULL, '小江驛送陸侍御歸湖上山 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd88f76-3872-4096-9f64-6da254cb8884', '送李德輿歸穿石洞山居', '送李德輿归穿石洞山居', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["烏巾年少歸何處，一片綵霞仙洞中。","惆悵別時花似雪，行人不肯醉春風。"]', '["烏巾年少归何处，一片綵霞仙洞中。","惆悵別时花似雪，行人不肯醉春风。"]', '诗', 'shi', '', NULL, '送李德輿歸穿石洞山居 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb68b3c-4906-4031-953f-750c2e5cc628', '酬幽居閑上人喜及第後見贈', '酬幽居闲上人喜及第後见贈', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["九霄心在勞相問，四十年間豈足驚。","風動自然雲出岫，高僧不用笑浮生。"]', '["九霄心在勞相问，四十年间豈足驚。","风动自然云出岫，高僧不用笑浮生。"]', '诗', 'shi', '', NULL, '酬幽居閑上人喜及第後見贈 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2736836a-f50b-4d37-a606-2b30d5a9a9fe', '洛下贈徹公', '洛下贈徹公', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["天竺沙門洛下逢，請爲同社笑相容。","支頤忽望碧雲裏，心愛嵩山第幾重。"]', '["天竺沙门洛下逢，請爲同社笑相容。","支頤忽望碧云裏，心愛嵩山第幾重。"]', '诗', 'shi', '', NULL, '洛下贈徹公 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595c57cc-e61d-4076-8ead-42dad5de4670', '觀朱舍人歸葬吳中', '观朱舍人归葬吳中', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["翩翩絳旐寒流上，行引東歸萬里魂。","幾處州人臨水哭，共看遺草有王言。"]', '["翩翩絳旐寒流上，行引东归万里魂。","幾处州人臨水哭，共看遺草有王言。"]', '诗', 'shi', '', NULL, '觀朱舍人歸葬吳中 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b54bf578-45b3-4473-8512-a08804c9e63c', '題清鏡寺留別', '題清镜寺留別', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["路入千山愁自知，雪花撩亂壓松枝。","世人並道離別苦，誰信山僧輕別離。"]', '["路入千山愁自知，雪花撩亂壓松枝。","世人並道離別苦，誰信山僧轻別離。"]', '诗', 'shi', '', NULL, '題清鏡寺留別 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7481bb63-1d8b-4a09-9057-cbeccc070239', '從軍行', '從軍行', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["海畔風吹凍泥裂，枯桐葉落枝梢折。","橫笛聞聲不見人，紅旗直上天山雪。"]', '["海畔风吹凍泥裂，枯桐葉落枝梢折。","橫笛闻声不见人，紅旗直上天山雪。"]', '诗', 'shi', '', NULL, '從軍行 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e3b3ab-d7eb-4363-aad5-3e0f3197be84', '宿淮陰作', '宿淮陰作', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["秋燈點點淮陰市，楚客聯檣宿淮水。","夜深風起魚鼈腥，韓信祠堂明月裏。"]', '["秋灯点点淮陰市，楚客聯檣宿淮水。","夜深风起鱼鼈腥，韓信祠堂明月裏。"]', '诗', 'shi', '', NULL, '宿淮陰作 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f4ef3d-dfd7-4d77-8d4c-df0e8575eeef', '春日南山行', '春日南山行', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["處處看山不可行，野花相向笑無成。","長嫌爲客過州縣，漸被時人識姓名。"]', '["处处看山不可行，野花相向笑無成。","长嫌爲客過州縣，漸被时人識姓名。"]', '诗', 'shi', '', NULL, '春日南山行 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46de16bf-9cba-40d2-8cab-92888b89d657', '步虛詞二首 一', '步虛词二首 一', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["漢武青齋讀鼎書，太官扶上畫雲車。","壇上月明宮殿閉，仰看星斗禮空虛。"]', '["漢武青斋读鼎书，太官扶上畫云车。","壇上月明宮殿閉，仰看星斗禮空虛。"]', '诗', 'shi', '', NULL, '步虛詞二首 一 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5870e3-82e9-4f97-9b2e-fb212a5afa96', '步虛詞二首 二', '步虛词二首 二', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["樓殿層層阿母家，崑崙山頂駐紅霞。","笙歌出見穆天子，相引笑看琪樹花。"]', '["楼殿層層阿母家，崑崙山頂駐紅霞。","笙歌出见穆天子，相引笑看琪樹花。"]', '诗', 'shi', '', NULL, '步虛詞二首 二 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c6fd71-0813-4060-ad07-8fa827806409', '襄陽過孟浩然舊居', '襄陽過孟浩然旧居', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["襄陽城郭春風起，漢水東流去不還。","孟子死來江樹老，煙霞猶在鹿門山。"]', '["襄陽城郭春风起，漢水东流去不還。","孟子死来江樹老，煙霞猶在鹿门山。"]', '诗', 'shi', '', NULL, '襄陽過孟浩然舊居 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c36b33-eab1-47ec-adb3-2a9ea0bb26e2', '送友人遊嵩山', '送友人游嵩山', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["嵩山歸路繞天壇，雪影松聲滿谷寒。","君見九龍潭上月，莫辭清夜訪袁安。"]', '["嵩山归路繞天壇，雪影松声满谷寒。","君见九龙潭上月，莫辞清夜訪袁安。"]', '诗', 'shi', '', NULL, '送友人遊嵩山 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea01e257-27d4-48cb-82a6-0bf168b8544d', '伏翼西洞送夏方慶', '伏翼西洞送夏方慶', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["洞裏春晴花正開，看花出洞幾時迴。","殷勤好去武陵客，莫引世人相逐來。"]', '["洞裏春晴花正开，看花出洞幾时迴。","殷勤好去武陵客，莫引世人相逐来。"]', '诗', 'shi', '', NULL, '伏翼西洞送夏方慶 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c211d043-f534-4ad0-b293-5a9c791e8c36', '贈人', '贈人', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["或櫂孤舟或杖藜，尋常適意釣長溪。","草堂竹徑在何處，落日孤煙寒渚西。"]', '["或櫂孤舟或杖藜，尋常適意釣长溪。","草堂竹徑在何处，落日孤煙寒渚西。"]', '诗', 'shi', '', NULL, '贈人 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc1b019-ffb1-4cb1-ab29-ed77ac718cd5', '句', '句', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["稚子新能編筍笠，山妻舊解補荷衣。","秋山隔岸清猨叫，湖水當門白鳥飛。"]', '["稚子新能編筍笠，山妻旧解補荷衣。","秋山隔岸清猨叫，湖水當门白鸟飞。"]', '诗', 'shi', '', NULL, '句 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3c3f84-9946-4c55-aaa7-ad22bcab3779', '東風二章 一', '东风二章 一', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["東風叶時，匪沃匪飄。","莫雪凝川，莫陰沍郊。","朝不徯夕乃銷，東風之行地上兮。","上德臨慝，匪戮匪梟。","莫暴在野，莫醜在階。","以踣以殲，夕不徯朝，隴西公來浚都兮。"]', '["东风叶时，匪沃匪飄。","莫雪凝川，莫陰沍郊。","朝不徯夕乃銷，东风之行地上兮。","上德臨慝，匪戮匪梟。","莫暴在野，莫醜在階。","以踣以殲，夕不徯朝，隴西公来浚都兮。"]', '诗', 'shi', '', NULL, '東風二章 一 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b850806a-2014-49d4-870c-cc97b0fc26ad', '東風二章 二', '东风二章 二', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["東風叶時，匪鑿匪[穮]。","莫蟄在泉，莫枯在條。","宵不徯晨乃繇，東風之行地上兮。","上德爲政，匪食匪招。","莫顧於家，莫流於遼。","以飽以迴，晨不徯霄，隴西公來浚都兮。"]', '["东风叶时，匪鑿匪[穮]。","莫蟄在泉，莫枯在條。","宵不徯晨乃繇，东风之行地上兮。","上德爲政，匪食匪招。","莫顧於家，莫流於遼。","以飽以迴，晨不徯霄，隴西公来浚都兮。"]', '诗', 'shi', '', NULL, '東風二章 二 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49243050-ebfa-4e56-a695-493e61d65601', '有所恨二章 一', '有所恨二章 一', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["相思君子，吁嗟萬里。","亦既至止，曷不覯止。","本不信巫，謂巫言是履。","在門五日，如待之死，有所恨兮。"]', '["相思君子，吁嗟万里。","亦既至止，曷不覯止。","本不信巫，謂巫言是履。","在门五日，如待之死，有所恨兮。"]', '诗', 'shi', '', NULL, '有所恨二章 一 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf4050a-da16-4038-81fc-302ce657db02', '有所恨二章 二', '有所恨二章 二', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["相思遺衣，爲憶以貽。","亦既受止，曷不保持。","本不欺友，謂友情是違。","隔生之贈，造次亡之，有所恨兮。"]', '["相思遺衣，爲憶以貽。","亦既受止，曷不保持。","本不欺友，謂友情是違。","隔生之贈，造次亡之，有所恨兮。"]', '诗', 'shi', '', NULL, '有所恨二章 二 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879a3a26-c1d4-4e47-bda6-b6e98481547d', '玩月', '玩月', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["八月十五夕，舊嘉蟾兔光。","斯從古人好，共下今宵堂。","素魄皎孤凝，芳輝紛四揚。","裴回林上頭，泛灧天中央。","皓露助流華，輕風佐浮涼。","清冷到肌骨，潔白盈衣裳。","惜此苦宜玩，攬之非可將。","含情顧廣庭，願勿沈西方。"]', '["八月十五夕，旧嘉蟾兔光。","斯從古人好，共下今宵堂。","素魄皎孤凝，芳輝紛四揚。","裴回林上头，泛灧天中央。","皓露助流华，轻风佐浮涼。","清冷到肌骨，潔白盈衣裳。","惜此苦宜玩，攬之非可將。","含情顧廣庭，願勿沈西方。"]', '诗', 'shi', '', NULL, '玩月 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358b69bc-760b-4274-9fd6-1a2251eb9699', '詠德上韋檢察', '詠德上韋檢察', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["少華類太華，太室似少室。","亞相與丞相，亦復無異質。","渟如月臨水，肅若松照日。","輝影互光澄，陰森兩蔥鬱。","連城鸞鳳分，同氣龜龍出。","併力革夷心，通籌整師律。","英豪願迴席，蠻貊皆屈膝。","中外行分途，寰瀛待清謐。"]', '["少华類太华，太室似少室。","亞相與丞相，亦复無異質。","渟如月臨水，肅若松照日。","輝影互光澄，陰森兩蔥鬱。","連城鸾鳳分，同氣龟龙出。","併力革夷心，通籌整師律。","英豪願迴席，蠻貊皆屈膝。","中外行分途，寰瀛待清謐。"]', '诗', 'shi', '', NULL, '詠德上韋檢察 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39504689-a531-4837-96ff-43ed29ace50a', '寓興', '寓兴', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["桃李有奇質，樗櫟無妙姿。","皆承慶雲沃，一種春風吹。","美惡苟同歸，喧囂徒爾爲。","相將任玄造，聊醉手中巵。"]', '["桃李有奇質，樗櫟無妙姿。","皆承慶云沃，一種春风吹。","美惡苟同归，喧囂徒爾爲。","相將任玄造，聊醉手中巵。"]', '诗', 'shi', '', NULL, '寓興 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d037ba-589c-4cda-af55-98f2cf5ad48f', '荅韓十八駑驥吟', '荅韓十八駑驥吟', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["故人舒其憤，昨示駑驥篇。","駑以易售陳，驥以難知言。","委曲感既深，咨嗟詞亦殷。","伊情有遠瀾，余志遜其源。","室在周孔堂，道通堯舜門。","調雅聲寡同，途遐勢難翻。","顧茲萬恨來，假彼二物云。","賤貴而貴賤，世人良共然。","巴蕉一葉妖，茙葵一花妍。","畢無才實資，手植堦墀前。","楩柟十圍瑰，松柏百尺堅。","罔念梁棟功，野長丘墟邊。","傷哉昌黎韓，焉得不迍邅。","上帝本厚生，大君方建元。","寶將庇羣甿，庶此規崇軒。","班爾圖永安，掄擇期精專。","君看廣廈中，豈有樹庭萱。"]', '["故人舒其憤，昨示駑驥篇。","駑以易售陳，驥以难知言。","委曲感既深，咨嗟词亦殷。","伊情有远瀾，余志遜其源。","室在周孔堂，道通堯舜门。","調雅声寡同，途遐勢难翻。","顧茲万恨来，假彼二物云。","賤貴而貴賤，世人良共然。","巴蕉一葉妖，茙葵一花妍。","畢無才實資，手植堦墀前。","楩柟十圍瑰，松柏百尺堅。","罔念梁棟功，野长丘墟邊。","傷哉昌黎韓，焉得不迍邅。","上帝本厚生，大君方建元。","寶將庇羣甿，庶此規崇軒。","班爾圖永安，掄擇期精專。","君看廣廈中，豈有樹庭萱。"]', '诗', 'shi', '', NULL, '荅韓十八駑驥吟 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc03f335-ced6-4cb0-bd9e-e24151c01b6e', '益昌行', '益昌行', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["驅馬至益昌，倍驚風俗和。","耕夫隴上謠，負者途中歌。","處處川復原，重重山與河。","人煙遍餘田，時稼無閑坡。","問業一何脩，太守德化加。","問身一何安，太守恩懷多。","賢哉我太守，在古無以過。","愛人甚愛身，治郡如治家。","雲雷既奮騰，草木遂萌芽。","乃知良二千，德足爲國華。","今時固精求，漢帝非徒嗟。","四海有青春，衆植佇揚葩。","期當作說霖，天下同雱𩃱。"]', '["驱马至益昌，倍驚风俗和。","耕夫隴上謠，負者途中歌。","处处川复原，重重山與河。","人煙遍餘田，时稼無闲坡。","问業一何脩，太守德化加。","问身一何安，太守恩懷多。","賢哉我太守，在古無以過。","愛人甚愛身，治郡如治家。","云雷既奮腾，草木遂萌芽。","乃知良二千，德足爲国华。","今时固精求，漢帝非徒嗟。","四海有青春，衆植佇揚葩。","期當作说霖，天下同雱𩃱。"]', '诗', 'shi', '', NULL, '益昌行 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455b1c96-7b63-4d5e-88c0-ee32154c68d4', '自淮中却赴洛途中作', '自淮中却赴洛途中作', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["惆悵策疲馬，孤蓬被風吹。","昨東今又西，冉冉長路岐。","歲晚樹無葉，夜寒霜滿枝。","旅人恒苦辛，冥寞天何知。"]', '["惆悵策疲马，孤蓬被风吹。","昨东今又西，冉冉长路岐。","歲晚樹無葉，夜寒霜满枝。","旅人恒苦辛，冥寞天何知。"]', '诗', 'shi', '', NULL, '自淮中却赴洛途中作 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c91cec-5b68-4b9b-9984-eecb94006d7b', '晨裝行', '晨裝行', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["村店月西出，山林鵯鵊聲。","旅燈徹夜席，束囊事晨征。","寂寂人尚眠，悠悠天未明。","豈無偃息心，所務前有程。"]', '["村店月西出，山林鵯鵊声。","旅灯徹夜席，束囊事晨征。","寂寂人尚眠，悠悠天未明。","豈無偃息心，所務前有程。"]', '诗', 'shi', '', NULL, '晨裝行 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eefb001-0b7b-435f-bd3a-61837433a2e9', '新都行', '新都行', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["縹緲空中絲，蒙籠道傍樹。","翻茲葉間吹，惹破花上露。","悠揚絲意去，苒蒻花枝住。","何計脫纏綿，天長春日暮。"]', '["縹緲空中絲，蒙籠道傍樹。","翻茲葉间吹，惹破花上露。","悠揚絲意去，苒蒻花枝住。","何計脫纏綿，天长春日暮。"]', '诗', 'shi', '', NULL, '新都行 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7693fd9-1b59-4478-844b-91bfc6d5a29d', '銅雀妓', '銅雀妓', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["蕭條登古臺，迴首黃金屋。","落葉不歸林，高陵永爲谷。","妝容徒自麗，舞態閱誰目。","惆悵繐帷空，歌聲苦於哭。"]', '["蕭條登古台，迴首黄金屋。","落葉不归林，高陵永爲谷。","妝容徒自丽，舞態閱誰目。","惆悵繐帷空，歌声苦於哭。"]', '诗', 'shi', '', NULL, '銅雀妓 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafc09ae-0b35-448d-8acb-6d5202c5180a', '太原旅懷呈薛十八侍御齊十二奉禮', '太原旅懷呈薛十八侍御齊十二奉禮', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["前來稱英雋，有食主人魚。","後來曰賢才，又受主人車。","伊予亦投刺，恩煦胡凋疎。","既覩主人面，復見主人書。","餬口百家周，賃廡三月餘。","眼見寒序臻，坐送秋光除。","西日惄飢腸，北風疾絺裾。","升堂有知音，此意當何如。"]', '["前来稱英雋，有食主人鱼。","後来曰賢才，又受主人车。","伊予亦投刺，恩煦胡凋疎。","既覩主人面，复见主人书。","餬口百家周，賃廡三月餘。","眼见寒序臻，坐送秋光除。","西日惄飢腸，北风疾絺裾。","升堂有知音，此意當何如。"]', '诗', 'shi', '', NULL, '太原旅懷呈薛十八侍御齊十二奉禮 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d786a412-340b-4aed-b485-3b45bf6efc61', '李評事公進示文集因贈之', '李評事公進示文集因贈之', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["風雅不墜地，五言始君先。","希微嘉會章，杳冥河梁篇。","理蔓語無枝，言一意則千。","往來更後人，澆蕩醨前源。","傾筐實不收，樸樕華爭繁。","大教護微旨，哲人生令孫。","高飆激頹波，坐使橫流翻。","昔日越重阻，側聆滄海傳。","逮茲覿清揚，幸覩青琅編。","泠泠中山醇，片片崑丘璠。","一杯有餘味，再覽增光鮮。","對寶人皆鑒，握鞶良自妍。","吾其告先師，六義今還全。"]', '["风雅不墜地，五言始君先。","希微嘉會章，杳冥河梁篇。","理蔓語無枝，言一意則千。","往来更後人，澆蕩醨前源。","傾筐實不收，樸樕华爭繁。","大教護微旨，哲人生令孫。","高飆激頹波，坐使橫流翻。","昔日越重阻，側聆滄海傳。","逮茲覿清揚，幸覩青琅編。","泠泠中山醇，片片崑丘璠。","一杯有餘味，再覽增光鲜。","对寶人皆鑒，握鞶良自妍。","吾其告先師，六義今還全。"]', '诗', 'shi', '', NULL, '李評事公進示文集因贈之 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee2cbb1-71a9-4702-91dc-cce9446269ff', '徐十八晦落第', '徐十八晦落第', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["嘉穀不夏熟，大器當晚成。","徐生異凡鳥，安得非時鳴。","汲汲有所爲，驅驅無本情。","懿哉蒼梧鳳，終見排雲征。"]', '["嘉穀不夏熟，大器當晚成。","徐生異凡鸟，安得非时鳴。","汲汲有所爲，驱驱無本情。","懿哉蒼梧鳳，終见排云征。"]', '诗', 'shi', '', NULL, '徐十八晦落第 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e52799f-5182-4e6f-ae2e-f411c4af69f2', '春日途中寄故園所親', '春日途中寄故园所親', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["客路度年華，故園云未返。","悠悠去源水，日日只有遠。","始歎秋葉零，又看春草晚。","寄書南飛鴻，相憶劇鄉縣。"]', '["客路度年华，故园云未返。","悠悠去源水，日日只有远。","始歎秋葉零，又看春草晚。","寄书南飞鴻，相憶劇乡縣。"]', '诗', 'shi', '', NULL, '春日途中寄故園所親 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c05f2b1-902f-49dd-a9ff-bc4fae236a7b', '蜀中將歸留辭韓相公貫之', '蜀中將归留辞韓相公貫之', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["寧體即雲構，方前恒玉食。","貧居豈及此，要自懷歸憶。","在夢關山遠，如流歲華逼。","明晨首鄉路，迢遰孤飛翼。"]', '["寧體即云構，方前恒玉食。","貧居豈及此，要自懷归憶。","在梦关山远，如流歲华逼。","明晨首乡路，迢遰孤飞翼。"]', '诗', 'shi', '', NULL, '蜀中將歸留辭韓相公貫之 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f11723-8c05-4402-8ecb-9282de704534', '江夏留別華二', '江夏留別华二', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["弭棹已傷別，不堪離緒催。","十年一心人，千里同舟來。","鄉路我尚遙，客遊君未回。","將何慰兩端，互勉臨岐杯。"]', '["弭棹已傷別，不堪離緒催。","十年一心人，千里同舟来。","乡路我尚遙，客游君未回。","將何慰兩端，互勉臨岐杯。"]', '诗', 'shi', '', NULL, '江夏留別華二 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d7c131-d44a-4feb-845b-f55e47bcfb60', '送潭州陸戶曹之任', '送潭州陸戶曹之任', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["三語又爲掾，大家聞屈聲。","多年名下人，四姓江南英。","衡嶽半天秀，湘潭無底清。","何言驅車遠，去有蒙莊情。"]', '["三語又爲掾，大家闻屈声。","多年名下人，四姓江南英。","衡嶽半天秀，湘潭無底清。","何言驱车远，去有蒙莊情。"]', '诗', 'shi', '', NULL, '送潭州陸戶曹之任 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19d180f-2283-4d4c-9adf-65d1dbdc129b', '福州送鄭楚材赴京時監察劉公亮有感激鄭意', '福州送鄭楚材赴京时監察劉公亮有感激鄭意', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["美人河嶽靈，家本滎水濆。","門承若蘭族，身蘊如瓊文。","早折青桂枝，俯窺鴻鵠羣。","邇來丹霄姿，遠逐蒼梧雲。","有伊光鑒人，惜茲瑤蕙薰。","中酣前激昂，四座同氛氳。","海郡梅霪晴，山郵炎景曛。","迴翔罷南遊，鳴唳期西聞。","秦塞鸞鳳征，越江雲雨分。","從茲一別離，佇致如堯君。"]', '["美人河嶽靈，家本滎水濆。","门承若蘭族，身蘊如瓊文。","早折青桂枝，俯窺鴻鵠羣。","邇来丹霄姿，远逐蒼梧云。","有伊光鑒人，惜茲瑤蕙薰。","中酣前激昂，四座同氛氳。","海郡梅霪晴，山郵炎景曛。","迴翔罷南游，鳴唳期西闻。","秦塞鸾鳳征，越江云雨分。","從茲一別離，佇致如堯君。"]', '诗', 'shi', '', NULL, '福州送鄭楚材赴京時監察劉公亮有感激鄭意 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b18f8d4-7e91-4311-910f-83687f2092aa', '初發太原途中寄太原所思', '初發太原途中寄太原所思', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["驅馬覺漸遠，迴頭長路塵。","高城已不見，況復城中人。","去意自未甘，居情諒猶辛。","五原東北晉，千里西南秦。","一屨不出門，一車無停輪。","流萍與繫匏，早晚期相親。"]', '["驱马覺漸远，迴头长路塵。","高城已不见，況复城中人。","去意自未甘，居情諒猶辛。","五原东北晉，千里西南秦。","一屨不出门，一车無停輪。","流萍與繫匏，早晚期相親。"]', '诗', 'shi', '', NULL, '初發太原途中寄太原所思 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c544c727-c17f-486e-a2d2-dd00027319bc', '汝川行', '汝川行', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["汝墳春女蠶忙月，朝起採桑日西沒。","輕綃裙露紅羅襪，半蹋金梯倚枝歇。","垂空玉腕若無骨，映葉朱唇似花發。","相歡誰是遊冶郎，蠶休不得岐路旁。"]', '["汝墳春女蠶忙月，朝起採桑日西沒。","轻綃裙露紅羅襪，半蹋金梯倚枝歇。","垂空玉腕若無骨，映葉朱唇似花發。","相歡誰是游冶郎，蠶休不得岐路旁。"]', '诗', 'shi', '', NULL, '汝川行 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f71b83-837d-45ff-9cc4-3d4a788aa232', '智達上人水精念珠歌', '智達上人水精念珠歌', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["水已清，清中不易當其精。","精華極，何宜更復加磨拭。","良工磨拭成貫珠，泓澄洞澈看如無。","星輝月耀莫之逾，駭雞照乘徒稱殊。","上人念佛泛貞諦，一佛一珠以爲計。","既指其珠當佛身，亦欲珠明佛像智。","咨董母，訪朱公。","得之玓瓅羣奇中，龍龕鷲嶺長隨躬。","朝自守持纖掌透，夜來月照紅條空。","窮川極陸難爲寶，孰說軖璖將瑪瑙。","連連寒溜下陰軒，熒熒泫露垂秋草。","皎晶晶，彰煌煌。","陸離電烻紛不常，凌眸暈目生光芒。","我來借問修行術，數日殷勤美茲物。","上人視日授微言，心靜如斯即諸佛。"]', '["水已清，清中不易當其精。","精华極，何宜更复加磨拭。","良工磨拭成貫珠，泓澄洞澈看如無。","星輝月耀莫之逾，駭雞照乘徒稱殊。","上人念佛泛貞諦，一佛一珠以爲計。","既指其珠當佛身，亦欲珠明佛像智。","咨董母，訪朱公。","得之玓瓅羣奇中，龙龕鷲嶺长隨躬。","朝自守持纖掌透，夜来月照紅條空。","窮川極陸难爲寶，孰说軖璖將瑪瑙。","連連寒溜下陰軒，熒熒泫露垂秋草。","皎晶晶，彰煌煌。","陸離電烻紛不常，凌眸暈目生光芒。","我来借问修行術，數日殷勤美茲物。","上人視日授微言，心静如斯即諸佛。"]', '诗', 'shi', '', NULL, '智達上人水精念珠歌 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084bd5ac-df4b-4dfe-b1b7-2b313031f1c9', '許州途中', '許州途中', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["秦川行盡潁川長，吳江越嶺已同方。","征途渺渺煙茫茫，未得還鄉傷近鄉。","隨萍逐梗見春光，行樂登臺鬬在旁。","林間啼鳥野中芳，有似故園皆斷腸。"]', '["秦川行尽潁川长，吳江越嶺已同方。","征途渺渺煙茫茫，未得還乡傷近乡。","隨萍逐梗见春光，行乐登台鬬在旁。","林间啼鸟野中芳，有似故园皆斷腸。"]', '诗', 'shi', '', NULL, '許州途中 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07a036a1-fe61-431c-acf2-31af1c614832', '賦得秋河曙耿耿送郭秀才應舉', '賦得秋河曙耿耿送郭秀才應舉', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["月沒天欲明，秋河尚凝白。","皚皚積光素，耿耿橫虛碧。","南斗接，北辰連，空濛鴻洞浮高天。","蕩蕩漫漫皆晶然，實類平蕪流大川。","星爲潭底珠，雲是波中煙。","雞唱漏盡東方作，曲渚蒼蒼曉霜落。","鴈叫疑從清淺驚，鳧聲似在沿洄泊。","幷州細侯直下孫，才應秋賦懷金門。","念排雲漢將飛翻，仰之踴躍當華軒。","夜來陪餞歐陽子，偶坐通宵見深旨。","心知慷慨日昭然，前程心在青雲裏。"]', '["月沒天欲明，秋河尚凝白。","皚皚積光素，耿耿橫虛碧。","南斗接，北辰連，空濛鴻洞浮高天。","蕩蕩漫漫皆晶然，實類平蕪流大川。","星爲潭底珠，云是波中煙。","雞唱漏尽东方作，曲渚蒼蒼晓霜落。","鴈叫疑從清淺驚，鳧声似在沿洄泊。","幷州細侯直下孫，才應秋賦懷金门。","念排云漢將飞翻，仰之踴躍當华軒。","夜来陪餞歐陽子，偶坐通宵见深旨。","心知慷慨日昭然，前程心在青云裏。"]', '诗', 'shi', '', NULL, '賦得秋河曙耿耿送郭秀才應舉 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd9de74-3cf1-458a-b466-3b200a4f02ec', '送袁秀才下第歸毘陵', '送袁秀才下第归毘陵', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["羸馬出都門，修途指江東。","關河昨夜雨，草木非春風。","矢捨雖未中，璞全終待攻。","層霄秋可翔，豈不隨高鴻。"]', '["羸马出都门，修途指江东。","关河昨夜雨，草木非春风。","矢捨雖未中，璞全終待攻。","層霄秋可翔，豈不隨高鴻。"]', '诗', 'shi', '', NULL, '送袁秀才下第歸毘陵 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce55dfbe-58f4-4c3e-989e-87eea0afc301', '聞鄰舍唱涼州有所思', '闻鄰舍唱涼州有所思', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["有善伊涼曲，離別在天涯。","虛堂正相思，所妙發鄰家。","聲音雖類聞，形影終以遐。","因之增遠懷，惆悵菖蒲花。"]', '["有善伊涼曲，離別在天涯。","虛堂正相思，所妙發鄰家。","声音雖類闻，形影終以遐。","因之增远懷，惆悵菖蒲花。"]', '诗', 'shi', '', NULL, '聞鄰舍唱涼州有所思 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be58134-7437-4e69-96c4-79b5d56a2e40', '陪太原鄭行軍中丞登汾上閣中丞詩曰汾樓秋水闊宛似到閶門惆悵江湖思惟將南客論南客即詹也輒書即事上荅', '陪太原鄭行軍中丞登汾上閣中丞诗曰汾楼秋水闊宛似到閶门惆悵江湖思惟將南客論南客即詹也輒书即事上荅', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["幷州汾上閣，登望似吳閶。","貫郭河通路，縈村水逼鄉。","城槐臨枉渚，巷市接飛梁。","莫論江湖思，南人正斷腸。"]', '["幷州汾上閣，登望似吳閶。","貫郭河通路，縈村水逼乡。","城槐臨枉渚，巷市接飞梁。","莫論江湖思，南人正斷腸。"]', '诗', 'shi', '', NULL, '陪太原鄭行軍中丞登汾上閣中丞詩曰汾樓秋水闊宛似到閶門惆悵江湖思惟將南客論南客即詹也輒書即事上荅 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30726e0d-5d2b-4fbe-8665-cab35288179d', '送少微上人歸德峯', '送少微上人归德峯', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["不負人間累，棲身任所從。","灰心聞密行，菜色見羸容。","幻世方同悟，深居願繼踪。","孤雲與禪誦，到後在何峯。"]', '["不負人间累，棲身任所從。","灰心闻密行，菜色见羸容。","幻世方同悟，深居願繼踪。","孤云與禪誦，到後在何峯。"]', '诗', 'shi', '', NULL, '送少微上人歸德峯 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d84619b-2065-42ec-81e4-fdc19b5c7b93', '荆南夏夜水樓懷昭丘直上人雲夢李莘', '荆南夏夜水楼懷昭丘直上人云梦李莘', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["無機成旅逸，中夜上江樓。","雲盡月如練，水涼風似秋。","鳧聲聞夢澤，黛色上昭丘。","不遠人情在，良宵恨獨遊。"]', '["無機成旅逸，中夜上江楼。","云尽月如練，水涼风似秋。","鳧声闻梦澤，黛色上昭丘。","不远人情在，良宵恨独游。"]', '诗', 'shi', '', NULL, '荆南夏夜水樓懷昭丘直上人雲夢李莘 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52a19f0-ead1-4794-b251-81d26a38ce12', '酬裴十二秀才孩子詠', '酬裴十二秀才孩子詠', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["算日未成年，英姿已[襃]然。","王家千里後，荀氏八龍先。","蔥蒨松猶嫩，清明月漸圓。","將何一枝桂，容易賞名賢。"]', '["算日未成年，英姿已[襃]然。","王家千里後，荀氏八龙先。","蔥蒨松猶嫩，清明月漸圓。","將何一枝桂，容易賞名賢。"]', '诗', 'shi', '', NULL, '酬裴十二秀才孩子詠 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fdf6645-69a1-40fc-8a38-29f170bc949f', '旅次舟中對月寄姜公', '旅次舟中对月寄姜公', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["中宵天色淨，片月出滄洲。","皎潔臨孤島，嬋娟入亂流。","應同故園夜，獨起異鄉愁。","那得修蓬轉，從君上庾樓。"]', '["中宵天色淨，片月出滄洲。","皎潔臨孤島，嬋娟入亂流。","應同故园夜，独起異乡愁。","那得修蓬轉，從君上庾楼。"]', '诗', 'shi', '', NULL, '旅次舟中對月寄姜公 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d3b99d-99a2-4d2a-94fe-67ad3005be16', '除夜長安客舍', '除夜长安客舍', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["十上書仍寢，如流歲又遷。","望家思獻壽，算甲恨長年。","虛牖傳寒柝，孤燈照絕編。","誰應問窮轍，泣盡更潸然。"]', '["十上书仍寢，如流歲又遷。","望家思獻壽，算甲恨长年。","虛牖傳寒柝，孤灯照絕編。","誰應问窮轍，泣尽更潸然。"]', '诗', 'shi', '', NULL, '除夜長安客舍 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8340c35c-e614-442b-88ee-953777780df5', '早秋登慈恩寺塔', '早秋登慈恩寺塔', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["寶塔過千仞，登臨盡四維。","毫端分馬頰，墨點辨蛾眉。","地逈風彌緊，天長日久遲。","因高欲有賦，遠意慘生悲。"]', '["寶塔過千仞，登臨尽四維。","毫端分马頰，墨点辨蛾眉。","地逈风彌緊，天长日久遲。","因高欲有賦，远意慘生悲。"]', '诗', 'shi', '', NULL, '早秋登慈恩寺塔 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2227f88-0595-46df-8a7f-6cf8ad77a2d6', '太原和嚴長官八月十五日夜西山童子上方玩月寄中丞少尹', '太原和嚴长官八月十五日夜西山童子上方玩月寄中丞少尹', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["西寺碧雲端，東溟白雪團。","年來一夜玩，君在半天看。","素魄當懷上，清光在下寒。","宜裁濟江什，有阻惠連歡。"]', '["西寺碧云端，东溟白雪團。","年来一夜玩，君在半天看。","素魄當懷上，清光在下寒。","宜裁濟江什，有阻惠連歡。"]', '诗', 'shi', '', NULL, '太原和嚴長官八月十五日夜西山童子上方玩月寄中丞少尹 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0403532-fc3c-4599-9a51-28e131f578a1', '九日廣陵同陳十五先輩登高懷林十二先輩', '九日廣陵同陳十五先輩登高懷林十二先輩', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["客路重陽日，登高寄上樓。","風煙今令節，臺閣古雄州。","泛菊聊斟酒，持萸嬾插頭。","情人共惆悵，良久不同遊。"]', '["客路重陽日，登高寄上楼。","风煙今令節，台閣古雄州。","泛菊聊斟酒，持萸嬾插头。","情人共惆悵，良久不同游。"]', '诗', 'shi', '', NULL, '九日廣陵同陳十五先輩登高懷林十二先輩 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994c7472-17c8-45aa-b66f-6d15bb892e27', '題嚴光釣臺', '題嚴光釣台', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["弭棹歷塵跡，悄然關我情。","伊無昔時節，豈有今日名。","辭貴不辭賤，是心誰復行。","欽哉此溪曲，永獨古風清。"]', '["弭棹歷塵跡，悄然关我情。","伊無昔时節，豈有今日名。","辞貴不辞賤，是心誰复行。","欽哉此溪曲，永独古风清。"]', '诗', 'shi', '', NULL, '題嚴光釣臺 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69588c99-4ab4-4da8-a846-bc0f2729d506', '送高士安下第歸岷南寧覲', '送高士安下第归岷南寧覲', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["偕隱有賢親，岷南四十春。","棲雲自匪石，觀國暫同塵。","就養思兒戲，延年愛鳥伸。","還看謝時去，有類潁陽人。"]', '["偕隐有賢親，岷南四十春。","棲云自匪石，观国暫同塵。","就養思兒戲，延年愛鸟伸。","還看謝时去，有類潁陽人。"]', '诗', 'shi', '', NULL, '送高士安下第歸岷南寧覲 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef860c48-a517-48a8-8aa1-826f47bfafba', '述德上興元嚴僕射', '述德上兴元嚴僕射', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["山橫碧立並雄岷，大阜洪川共降神。","心合雲雷清禍亂，力迴天地作陽春。","非熊德媿當周輔，稱傑叨慙首漢臣。","何幸腐儒無一藝，得爲門下食魚人。"]', '["山橫碧立並雄岷，大阜洪川共降神。","心合云雷清禍亂，力迴天地作陽春。","非熊德媿當周輔，稱傑叨慙首漢臣。","何幸腐儒無一藝，得爲门下食鱼人。"]', '诗', 'shi', '', NULL, '述德上興元嚴僕射 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1989e242-9e27-44c6-9413-7ca68e470f9f', '及第後酬故園親故', '及第後酬故园親故', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["才非天授學非師，以此成名曩豈期。","楊葉射頻因偶中，桂枝材美敢當之。","稱文作藝方慙德，相賀投篇料媿詞。","猶著褐衣何足羨，如君即是載鳴時。"]', '["才非天授学非師，以此成名曩豈期。","楊葉射頻因偶中，桂枝材美敢當之。","稱文作藝方慙德，相賀投篇料媿词。","猶著褐衣何足羨，如君即是載鳴时。"]', '诗', 'shi', '', NULL, '及第後酬故園親故 歐陽詹 shi');
